function design(site, analyse) {
  const xs = [
    0, 4.918, 9.836, 14.755, 19.673, 24.591,
    29.509, 34.427, 39.345, 44.264, 49.182, 54.1
  ];
  const yBottom = -7.30;
  const zLeft = -4.35;
  const zRight = 4.35;

  // Each group is ordered from heavier to lighter candidates.
  const sections = [
    [ // top chords
      "S460 CHS406.4x12.5",
      "S460 CHS355.6x12.5",
      "S460 CHS323.9x10",
      "S460 CHS273x10"
    ],
    [ // bottom chords
      "S460 CHS323.9x10",
      "S460 CHS273x10",
      "S460 CHS244.5x8",
      "S460 CHS219.1x8"
    ],
    [ // verticals
      "S460 CHS323.9x10",
      "S460 CHS273x10",
      "S460 CHS244.5x8",
      "S460 CHS219.1x8",
      "S460 CHS193.7x8"
    ],
    [ // crossed side webs
      "S460 CHS355.6x12.5",
      "S460 CHS323.9x10",
      "S460 CHS273x10",
      "S460 CHS244.5x8",
      "S460 CHS219.1x8"
    ],
    [ // transverse ties
      "S460 CHS244.5x8",
      "S460 CHS219.1x8",
      "S460 CHS193.7x8",
      "S460 CHS168.3x6.3",
      "S460 CHS139.7x6.3"
    ],
    [ // top and bottom plan bracing
      "S460 CHS244.5x8",
      "S460 CHS219.1x8",
      "S460 CHS193.7x8",
      "S460 CHS168.3x6.3",
      "S460 CHS139.7x6.3",
      "S460 CHS114.3x5"
    ]
  ];

  const note =
    "Deep pinned twin side trusses use crossed webs and triangulated top and bottom planes; section sizes are reduced only while analysis retains margin.";

  function build(sel) {
    const nodes = [];
    const members = [];
    const spec = (group) => sections[group][sel[group]];
    const add = (a, b, group) => members.push([a, b, spec(group)]);

    for (let i = 0; i < xs.length; i++) {
      nodes.push({ id: "BL" + i, x: xs[i], y: yBottom, z: zLeft, joint: "pin" });
      nodes.push({ id: "BR" + i, x: xs[i], y: yBottom, z: zRight, joint: "pin" });
    }

    for (let i = 0; i < xs.length - 1; i++) {
      // Two upper and two lower longitudinal chords.
      add("L" + i, "L" + (i + 1), 0);
      add("R" + i, "R" + (i + 1), 0);
      add("BL" + i, "BL" + (i + 1), 1);
      add("BR" + i, "BR" + (i + 1), 1);

      // Crossed web members in each vertical side truss.
      add("L" + i, "BL" + (i + 1), 3);
      add("BL" + i, "L" + (i + 1), 3);
      add("R" + i, "BR" + (i + 1), 3);
      add("BR" + i, "R" + (i + 1), 3);

      // One diagonal in each top and bottom plan panel.
      add("L" + i, "R" + (i + 1), 5);
      add("BL" + i, "BR" + (i + 1), 5);
    }

    for (let i = 0; i < xs.length; i++) {
      add("L" + i, "BL" + i, 2);
      add("R" + i, "BR" + i, 2);
      add("L" + i, "R" + i, 4);
      add("BL" + i, "BR" + i, 4);
    }

    return { note, nodes, members };
  }

  function hasMargin(r) {
    if (!r || r.ok !== true) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > 0.78) return false;
    if (typeof r.alpha_crMin === "number" && r.alpha_crMin < 5.7) return false;
    if (typeof r.frequency === "number" && r.frequency < 1.26) return false;

    if (typeof r.sag === "number" && typeof r.sagLimit === "number" &&
        r.sagLimit > 0 && r.sag / r.sagLimit > 0.82) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" &&
        r.swayLimit > 0 && r.sway / r.swayLimit > 0.82) return false;

    if (r.robustness === false) return false;
    if (r.robustness && typeof r.robustness === "object" &&
        (r.robustness.ok === false || r.robustness.pass === false)) return false;
    return true;
  }

  let calls = 0;
  const callLimit = 40;
  let bestSafe = null;
  let bestOk = null;

  function evaluate(sel) {
    if (calls >= callLimit) return null;
    const d = build(sel);
    let r;
    calls++;
    try {
      r = analyse(d);
    } catch (e) {
      return null;
    }
    if (!r || r.error) return null;

    const rec = { d, sel: sel.slice(), r };
    if (r.ok === true && typeof r.mass === "number" &&
        (!bestOk || r.mass < bestOk.r.mass)) bestOk = rec;
    if (hasMargin(r) && typeof r.mass === "number" &&
        (!bestSafe || r.mass < bestSafe.r.mass)) bestSafe = rec;
    return rec;
  }

  let current = sections.map(() => 0);
  evaluate(current);

  // Greedily reduce each member group, then make a second pass to use any
  // margin created by the reductions in the other groups.
  for (let pass = 0; pass < 2 && calls < callLimit; pass++) {
    let changed = false;

    for (let g = 0; g < sections.length && calls < callLimit; g++) {
      let bestForGroup = null;

      for (let j = current[g] + 1; j < sections[g].length && calls < callLimit; j++) {
        const trial = current.slice();
        trial[g] = j;
        const rec = evaluate(trial);
        if (rec && hasMargin(rec.r) &&
            (!bestForGroup || rec.r.mass < bestForGroup.r.mass)) {
          bestForGroup = rec;
        }
      }

      if (bestForGroup) {
        current = bestForGroup.sel;
        changed = true;
      }
    }

    if (!changed) break;
  }

  if (bestSafe) return bestSafe.d;
  if (bestOk) return bestOk.d;
  return build(sections.map(() => 0));
}

function design(site, analyse) {
  const xs = [
    0, 4.918, 9.836, 14.755, 19.673, 24.591,
    29.509, 34.427, 39.345, 44.264, 49.182, 54.1
  ];
  const yBottom = -7.50;
  const zLeft = -4.35;
  const zRight = 4.35;

  const s460 = ids => ids.map(id => "S460 CHS" + id);
  const s690 = ids => ids.map(id => "S690 CHS" + id);

  // Upper and lower chords are sized separately in the end and middle regions.
  const sections = [
    s460(["406.4x12.5", "355.6x12.5", "323.9x10", "273x10",
          "244.5x8", "219.1x8", "193.7x8", "193.7x6.3",
          "168.3x6.3", "139.7x6.3"]),
    s460(["457x16", "406.4x12.5", "355.6x12.5", "323.9x10",
          "273x10", "244.5x8", "219.1x8", "193.7x8",
          "193.7x6.3", "168.3x6.3"]),
    s690(["406.4x12.5", "355.6x12.5", "323.9x10", "273x10",
          "244.5x8", "219.1x8", "193.7x8", "193.7x6.3",
          "168.3x6.3", "139.7x6.3"]),
    s690(["457x16", "406.4x12.5", "355.6x12.5", "323.9x10",
          "273x10", "244.5x8", "219.1x8", "193.7x8",
          "193.7x6.3", "168.3x6.3"]),
    s460(["323.9x10", "273x10", "244.5x8", "219.1x8",
          "193.7x8", "193.7x6.3", "168.3x6.3", "139.7x6.3",
          "114.3x5", "88.9x5"]),
    s460(["406.4x12.5", "355.6x12.5", "323.9x10", "273x10",
          "244.5x8", "219.1x8", "193.7x8", "193.7x6.3",
          "168.3x6.3", "139.7x6.3"]),
    s460(["323.9x10", "273x10", "244.5x8", "219.1x8",
          "193.7x8", "193.7x6.3", "168.3x6.3", "139.7x6.3",
          "114.3x5", "88.9x5"]),
    s460(["323.9x10", "273x10", "244.5x8", "219.1x8",
          "193.7x8", "193.7x6.3", "168.3x6.3", "139.7x6.3",
          "114.3x5", "88.9x5"]),
    s460(["323.9x10", "273x10", "244.5x8", "219.1x8",
          "193.7x8", "193.7x6.3", "168.3x6.3", "139.7x6.3",
          "114.3x5", "88.9x5", "76.1x4"]),
    s460(["273x10", "244.5x8", "219.1x8", "193.7x8",
          "193.7x6.3", "168.3x6.3", "139.7x6.3", "114.3x5",
          "88.9x5", "76.1x4"]),
    s460(["406.4x12.5", "355.6x12.5", "323.9x10", "273x10",
          "244.5x8", "219.1x8", "193.7x8", "193.7x6.3",
          "168.3x6.3", "139.7x6.3", "114.3x5"])
  ];

  const note =
    "I added alternating transverse-frame diagonals to close the 3-D panels, used single solid side webs, and pruned sections only while the published-case analysis retained margin.";

  function build(sel) {
    const nodes = [];
    const members = [];
    const add = (a, b, group) =>
      members.push([a, b, sections[group][sel[group]]]);

    for (let i = 0; i < xs.length; i++) {
      nodes.push({
        id: "BL" + i, x: xs[i], y: yBottom, z: zLeft, joint: "pin"
      });
      nodes.push({
        id: "BR" + i, x: xs[i], y: yBottom, z: zRight, joint: "pin"
      });
    }

    for (let i = 0; i < xs.length - 1; i++) {
      const outer = i < 3 || i > 7;
      const upperGroup = outer ? 0 : 1;
      const lowerGroup = outer ? 2 : 3;

      add("L" + i, "L" + (i + 1), upperGroup);
      add("R" + i, "R" + (i + 1), upperGroup);
      add("BL" + i, "BL" + (i + 1), lowerGroup);
      add("BR" + i, "BR" + (i + 1), lowerGroup);

      // One compression-capable diagonal in each side-truss panel.
      add("L" + i, "BL" + (i + 1), 5);
      add("R" + i, "BR" + (i + 1), 5);

      // Triangulate the top and bottom longitudinal planes.
      add("L" + i, "R" + (i + 1), 8);
      add("BL" + i, "BR" + (i + 1), 9);
    }

    for (let i = 0; i < xs.length; i++) {
      add("L" + i, "BL" + i, 4);
      add("R" + i, "BR" + i, 4);
      add("L" + i, "R" + i, 6);
      add("BL" + i, "BR" + i, 7);

      // A diagonal closes every transverse frame; alternate its orientation.
      if (i % 2 === 0) add("L" + i, "BR" + i, 10);
      else add("R" + i, "BL" + i, 10);
    }

    return { note, nodes, members };
  }

  function passesMargin(r) {
    if (!r || r.ok !== true) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > 0.70) return false;

    const cr = Number.isFinite(r.alpha_crMin)
      ? r.alpha_crMin
      : (Number.isFinite(r.alpha_cr) ? r.alpha_cr : null);
    if (cr !== null && cr < 7.5) return false;

    const f = Number.isFinite(r.frequency)
      ? r.frequency
      : (Number.isFinite(r.fMin) ? r.fMin : null);
    if (f !== null && f < 1.30) return false;

    if (Number.isFinite(r.sag) && Number.isFinite(r.sagLimit) &&
        r.sagLimit > 0 && r.sag / r.sagLimit > 0.78) return false;
    if (Number.isFinite(r.sway) && Number.isFinite(r.swayLimit) &&
        r.swayLimit > 0 && r.sway / r.swayLimit > 0.78) return false;

    if (Number.isFinite(r.fatigueWorst) && r.fatigueWorst > 0.82) return false;
    if (r.robustness === false) return false;
    if (r.robustness && typeof r.robustness === "object" &&
        (r.robustness.ok === false || r.robustness.pass === false)) return false;

    return true;
  }

  let calls = 0;
  const callLimit = 128;
  let bestSafe = null;
  let bestOk = null;

  function evaluate(sel) {
    if (calls >= callLimit) return null;

    const d = build(sel);
    let r;
    calls++;
    try {
      r = analyse(d);
    } catch (e) {
      return null;
    }

    if (!r || r.error) return null;
    const rec = { d, sel: sel.slice(), r };

    if (r.ok === true && typeof r.mass === "number" &&
        (!bestOk || r.mass < bestOk.r.mass)) {
      bestOk = rec;
    }
    if (passesMargin(r) && typeof r.mass === "number" &&
        (!bestSafe || r.mass < bestSafe.r.mass)) {
      bestSafe = rec;
    }
    return rec;
  }

  let current = sections.map(() => 0);
  evaluate(current);

  // Greedy section reduction, followed by a refinement pass.
  for (let pass = 0; pass < 2 && calls < callLimit; pass++) {
    let changed = false;

    for (let g = 0; g < sections.length && calls < callLimit; g++) {
      let bestForGroup = null;

      for (let j = current[g] + 1;
           j < sections[g].length && calls < callLimit;
           j++) {
        const trial = current.slice();
        trial[g] = j;
        const rec = evaluate(trial);

        if (rec && passesMargin(rec.r) &&
            (!bestForGroup || rec.r.mass < bestForGroup.r.mass)) {
          bestForGroup = rec;
        }
      }

      if (bestForGroup) {
        current = bestForGroup.sel.slice();
        changed = true;
      }
    }

    if (!changed) break;
  }

  if (bestSafe) return bestSafe.d;
  if (bestOk) return bestOk.d;
  return build(current);
}

function design(site, analyse) {
  const xs = [
    0, 4.918, 9.836, 14.755, 19.673, 24.591,
    29.509, 34.427, 39.345, 44.264, 49.182, 54.1
  ];
  const yBottom = -7.50;
  const zLeft = -4.35;
  const zRight = 4.35;
  const note =
    "Pinned twin side trusses retain the proven load path; I tested leaner 3-D bracing and resized individual members only when analysis retained margin.";

  const chs = [
    ["33.7x2.6", 2.54], ["42.4x3.2", 3.94], ["48.3x3.2", 4.53],
    ["60.3x3.2", 5.74], ["60.3x4", 7.07], ["76.1x3.2", 7.33],
    ["76.1x4", 9.06], ["88.9x4", 10.67], ["88.9x5", 13.18],
    ["114.3x4", 13.86], ["114.3x5", 17.17], ["139.7x5", 21.16],
    ["139.7x6.3", 26.4], ["168.3x5", 25.65], ["168.3x6.3", 32.06],
    ["193.7x6.3", 37.09], ["193.7x8", 46.67], ["219.1x8", 53.06],
    ["244.5x8", 59.44], ["273x10", 82.62], ["323.9x10", 98.61],
    ["355.6x12.5", 134.74], ["406.4x12.5", 154.68],
    ["457x16", 221.67]
  ].map(x => ({ id: x[0], area: x[1] }))
   .sort((a, b) => a.area - b.area);

  const areaById = Object.create(null);
  for (const s of chs) areaById[s.id] = s.area;

  function point(id) {
    const m = /^(BL|BR|L|R)(\d+)$/.exec(id);
    if (!m) return [0, 0, 0];
    const kind = m[1];
    const i = Number(m[2]);
    const bottom = kind === "BL" || kind === "BR";
    const left = kind === "L" || kind === "BL";
    return [xs[i], bottom ? yBottom : 0, left ? zLeft : zRight];
  }

  function memberLength(a, b) {
    const p = point(a);
    const q = point(b);
    const dx = p[0] - q[0];
    const dy = p[1] - q[1];
    const dz = p[2] - q[2];
    return Math.sqrt(dx * dx + dy * dy + dz * dz);
  }

  function makeNodes() {
    const nodes = [];
    for (let i = 0; i < xs.length; i++) {
      nodes.push({
        id: "BL" + i, x: xs[i], y: yBottom, z: zLeft, joint: "pin"
      });
      nodes.push({
        id: "BR" + i, x: xs[i], y: yBottom, z: zRight, joint: "pin"
      });
    }
    return nodes;
  }

  function hasCross(mode, i) {
    if (mode === "all") return true;
    if (mode === "alt") return i % 2 === 0 || i === 11;
    if (mode === "key") return i === 0 || i === 5 || i === 6 || i === 11;
    return false;
  }

  function makeRecords(cfg) {
    const records = [];
    function add(a, b, role, i, spec) {
      records.push({
        a, b, id: a + "-" + b, role, i, initial: spec,
        length: memberLength(a, b)
      });
    }

    for (let i = 0; i < xs.length - 1; i++) {
      const outer = i < 3 || i > 7;

      add("L" + i, "L" + (i + 1), "upperChord", i,
          "S460 CHS273x10");
      add("R" + i, "R" + (i + 1), "upperChord", i,
          "S460 CHS273x10");
      add("BL" + i, "BL" + (i + 1), "lowerChord", i,
          outer ? "S690 CHS219.1x8" : "S690 CHS273x10");
      add("BR" + i, "BR" + (i + 1), "lowerChord", i,
          outer ? "S690 CHS219.1x8" : "S690 CHS273x10");

      add("L" + i, "BL" + (i + 1), "web", i,
          "S460 CHS323.9x10");
      add("R" + i, "BR" + (i + 1), "web", i,
          "S460 CHS323.9x10");

      if (cfg.topPlan) {
        add("L" + i, "R" + (i + 1), "topPlan", i,
            "S460 CHS219.1x8");
      }
      if (cfg.bottomPlan) {
        add("BL" + i, "BR" + (i + 1), "bottomPlan", i,
            "S460 CHS193.7x8");
      }
    }

    for (let i = 0; i < xs.length; i++) {
      add("L" + i, "BL" + i, "vertical", i, "S460 CHS273x10");
      add("R" + i, "BR" + i, "vertical", i, "S460 CHS273x10");
      add("L" + i, "R" + i, "topTie", i, "S460 CHS193.7x8");
      add("BL" + i, "BR" + i, "bottomTie", i, "S460 CHS193.7x6.3");

      if (hasCross(cfg.cross, i)) {
        if (i % 2 === 0) {
          add("L" + i, "BR" + i, "crossDiag", i, "S460 CHS219.1x8");
        } else {
          add("R" + i, "BL" + i, "crossDiag", i, "S460 CHS219.1x8");
        }
      }
    }

    return records;
  }

  function build(records, specs) {
    return {
      note,
      nodes: makeNodes(),
      members: records.map((m, i) => [m.a, m.b, specs[i]])
    };
  }

  function isSafe(r) {
    if (!r || r.ok !== true) return false;

    if (Number.isFinite(r.maxUtil) && r.maxUtil > 0.72) return false;
    if (Number.isFinite(r.fatigueWorst) && r.fatigueWorst > 0.80) return false;

    const cr = Number.isFinite(r.alpha_crMin)
      ? r.alpha_crMin
      : (Number.isFinite(r.alpha_cr) ? r.alpha_cr : null);
    if (cr !== null && cr < 8) return false;

    const f = Number.isFinite(r.frequency)
      ? r.frequency
      : (Number.isFinite(r.fMin) ? r.fMin : null);
    if (f !== null && f < 1.30) return false;

    if (Number.isFinite(r.sag) && Number.isFinite(r.sagLimit) &&
        r.sagLimit > 0 && r.sag / r.sagLimit > 0.82) return false;
    if (Number.isFinite(r.sway) && Number.isFinite(r.swayLimit) &&
        r.swayLimit > 0 && r.sway / r.swayLimit > 0.82) return false;

    if (r.robustness === false) return false;
    if (r.robustness && typeof r.robustness === "object" &&
        (r.robustness.ok === false || r.robustness.pass === false)) return false;

    return true;
  }

  const callLimit = 350;
  let calls = 0;
  let best = null;

  function evaluate(cfg, records, specs) {
    if (calls >= callLimit) return null;

    const d = build(records, specs);
    let r;
    calls++;
    try {
      r = analyse(d);
    } catch (e) {
      return null;
    }
    if (!r || r.error) return null;

    const out = {
      cfg,
      records,
      specs: specs.slice(),
      d,
      r
    };

    if (isSafe(r) && Number.isFinite(r.mass) &&
        (!best || r.mass < best.r.mass)) {
      best = out;
    }
    return out;
  }

  const configs = [
    { topPlan: true,  bottomPlan: true,  cross: "all" },
    { topPlan: true,  bottomPlan: false, cross: "all" },
    { topPlan: false, bottomPlan: true,  cross: "all" },
    { topPlan: true,  bottomPlan: true,  cross: "alt" },
    { topPlan: true,  bottomPlan: false, cross: "alt" },
    { topPlan: false, bottomPlan: true,  cross: "alt" },
    { topPlan: true,  bottomPlan: true,  cross: "key" },
    { topPlan: true,  bottomPlan: false, cross: "key" },
    { topPlan: false, bottomPlan: true,  cross: "key" },
    { topPlan: true,  bottomPlan: true,  cross: "none" }
  ];

  for (const cfg of configs) {
    if (calls >= callLimit) break;
    const records = makeRecords(cfg);
    const specs = records.map(m => m.initial);
    evaluate(cfg, records, specs);
  }

  if (!best) {
    const cfg = configs[0];
    const records = makeRecords(cfg);
    return build(records, records.map(m => m.initial));
  }

  let currentCfg = best.cfg;
  let currentRecords = best.records;
  let currentSpecs = best.specs.slice();
  let currentR = best.r;

  // S460 has the same pinned fatigue class as the other ordinary steels
  // and avoids the S690 fatigue penalty on the tension chord.
  const s460ChordSpecs = currentSpecs.slice();
  let hasS690Chord = false;
  for (let i = 0; i < currentRecords.length; i++) {
    if (currentRecords[i].role === "lowerChord" &&
        s460ChordSpecs[i].indexOf("S690 ") === 0) {
      s460ChordSpecs[i] = "S460 " +
        s460ChordSpecs[i].slice("S690 ".length);
      hasS690Chord = true;
    }
  }

  if (hasS690Chord && calls < callLimit) {
    const out = evaluate(currentCfg, currentRecords, s460ChordSpecs);
    const oldFatigue = Number.isFinite(currentR.fatigueWorst)
      ? currentR.fatigueWorst
      : Infinity;
    const newFatigue = out && Number.isFinite(out.r.fatigueWorst)
      ? out.r.fatigueWorst
      : Infinity;
    if (out && isSafe(out.r) &&
        out.r.mass <= currentR.mass + 1e-6 &&
        newFatigue < oldFatigue - 1e-5) {
      currentSpecs = out.specs;
      currentR = out.r;
    } else {
      // If changing the entire chord is too aggressive, try individual bars.
      for (let i = 0; i < currentRecords.length && calls < callLimit; i++) {
        if (currentRecords[i].role !== "lowerChord" ||
            currentSpecs[i].indexOf("S690 ") !== 0) continue;
        const trial = currentSpecs.slice();
        trial[i] = "S460 " + trial[i].slice("S690 ".length);
        const one = evaluate(currentCfg, currentRecords, trial);
        if (one && isSafe(one.r) &&
            one.r.mass <= currentR.mass + 1e-6 &&
            Number.isFinite(one.r.fatigueWorst) &&
            one.r.fatigueWorst < currentR.fatigueWorst - 1e-5) {
          currentSpecs = one.specs;
          currentR = one.r;
        }
      }
    }
  }

  function infoFor(r, id) {
    if (!r || !Array.isArray(r.members)) return null;
    const reverse = id.split("-").reverse().join("-");
    for (const m of r.members) {
      if (!m) continue;
      const mid = m.id || m.memberId || m.member || m.name;
      if (mid === id || mid === reverse) return m;
    }
    return null;
  }

  function materialOf(spec) {
    const k = spec.indexOf(" ");
    return k < 0 ? "S460" : spec.slice(0, k);
  }

  function sectionIdOf(spec) {
    const k = spec.indexOf("CHS");
    return k < 0 ? null : spec.slice(k + 3);
  }

  function proposalFor(index, r, specs) {
    const rec = currentRecords[index];
    const spec = specs[index];
    const sectionId = sectionIdOf(spec);
    const currentArea = areaById[sectionId];
    if (!Number.isFinite(currentArea)) return null;

    const info = infoFor(r, rec.id);
    const mode = info && info.mode ? String(info.mode).toLowerCase() : "";
    let u;
    if (info && Number.isFinite(info.util)) {
      u = Math.max(0, info.util);
    } else {
      u = Number.isFinite(r.maxUtil)
        ? Math.min(0.38, r.maxUtil * 0.60)
        : 0.30;
    }

    let target;
    let ratio;
    if (mode.indexOf("fatigue") >= 0) {
      target = 0.76;
      ratio = u / target;
    } else if (mode.indexOf("buckling") >= 0) {
      target = 0.62;
      ratio = Math.sqrt(Math.max(0.01, u / target));
    } else {
      target = 0.68;
      ratio = u / target;
    }

    if (u >= target * 0.98) return null;
    ratio = Math.max(0.32, Math.min(0.94, ratio));

    const smaller = chs.filter(s => s.area < currentArea - 1e-6);
    if (smaller.length === 0) return null;

    const goal = currentArea * ratio;
    let start = 0;
    while (start < smaller.length && smaller[start].area < goal) start++;
    if (start >= smaller.length) start = smaller.length - 1;

    return {
      start,
      smaller,
      material: materialOf(spec),
      saving: rec.length * currentArea * Math.max(0, 1 - ratio)
    };
  }

  function resizeOne(index, maxTries) {
    if (calls >= callLimit) return false;
    const proposal = proposalFor(index, currentR, currentSpecs);
    if (!proposal) return false;

    const stop = Math.min(
      proposal.smaller.length,
      proposal.start + maxTries
    );

    for (let j = proposal.start; j < stop && calls < callLimit; j++) {
      const trial = currentSpecs.slice();
      trial[index] = proposal.material + " CHS" + proposal.smaller[j].id;
      const out = evaluate(currentCfg, currentRecords, trial);

      if (out && isSafe(out.r) &&
          out.r.mass < currentR.mass - 1e-6) {
        currentSpecs = out.specs;
        currentR = out.r;
        return true;
      }
    }
    return false;
  }

  function orderedIndices(indices) {
    return indices.map(i => {
      const p = proposalFor(i, currentR, currentSpecs);
      return { i, saving: p ? p.saving : 0 };
    }).sort((a, b) => b.saving - a.saving);
  }

  const allIndices = currentRecords.map((_, i) => i);
  const changed = [];

  for (const item of orderedIndices(allIndices)) {
    if (calls >= callLimit) break;
    if (resizeOne(item.i, 2)) changed.push(item.i);
  }

  if (calls < callLimit && changed.length > 0) {
    const seen = Object.create(null);
    const uniqueChanged = [];
    for (const i of changed) {
      if (!seen[i]) {
        seen[i] = true;
        uniqueChanged.push(i);
      }
    }
    for (const item of orderedIndices(uniqueChanged)) {
      if (calls >= callLimit) break;
      resizeOne(item.i, 1);
    }
  }

  return best ? best.d : build(
    makeRecords(configs[0]),
    makeRecords(configs[0]).map(m => m.initial)
  );
}

function design(site, analyse) {
  const xs = [
    0, 4.918, 9.836, 14.755, 19.673, 24.591,
    29.509, 34.427, 39.345, 44.264, 49.182, 54.1
  ];

  const note =
    "I retained the pinned twin side-trusses and full 3-D bracing, reduced sections member by member, and screened aluminium substitutions in low-force members.";

  const chs = [
    ["33.7x2.6", 2.54], ["42.4x3.2", 3.94], ["48.3x3.2", 4.53],
    ["60.3x3.2", 5.74], ["60.3x4", 7.07], ["76.1x3.2", 7.33],
    ["76.1x4", 9.06], ["88.9x4", 10.67], ["88.9x5", 13.18],
    ["114.3x4", 13.86], ["114.3x5", 17.17], ["139.7x5", 21.16],
    ["139.7x6.3", 26.4], ["168.3x5", 25.65], ["168.3x6.3", 32.06],
    ["193.7x6.3", 37.09], ["193.7x8", 46.67], ["219.1x8", 53.06],
    ["244.5x8", 59.44], ["273x10", 82.62], ["323.9x10", 98.61],
    ["355.6x12.5", 134.74], ["406.4x12.5", 154.68],
    ["457x16", 221.67]
  ].map(s => ({ id: s[0], area: s[1] }))
   .sort((a, b) => a.area - b.area);

  const areaById = Object.create(null);
  const indexById = Object.create(null);
  for (let i = 0; i < chs.length; i++) {
    areaById[chs[i].id] = chs[i].area;
    indexById[chs[i].id] = i;
  }

  function point(id) {
    const m = /^(BL|BR|L|R)(\d+)$/.exec(id);
    if (!m) return [0, 0, 0];

    const kind = m[1];
    const i = Number(m[2]);
    const bottom = kind === "BL" || kind === "BR";
    const left = kind === "L" || kind === "BL";

    return [
      xs[i],
      bottom ? -7.50 : 0,
      left ? -4.35 : 4.35
    ];
  }

  function lengthOf(a, b) {
    const p = point(a);
    const q = point(b);
    const dx = p[0] - q[0];
    const dy = p[1] - q[1];
    const dz = p[2] - q[2];
    return Math.sqrt(dx * dx + dy * dy + dz * dz);
  }

  const initialByRole = {
    upperChord: "S460 CHS273x10",
    lowerChord: "S690 CHS273x10",
    web: "S460 CHS323.9x10",
    topPlan: "S460 CHS219.1x8",
    vertical: "S460 CHS273x10",
    topTie: "S460 CHS193.7x8",
    bottomTie: "S460 CHS193.7x6.3",
    crossDiag: "S460 CHS219.1x8"
  };

  const records = [];

  function add(a, b, role, i) {
    records.push({
      a,
      b,
      id: a + "-" + b,
      role,
      i,
      length: lengthOf(a, b),
      initial: initialByRole[role]
    });
  }

  // Two pinned longitudinal side trusses, with top-plane triangulation.
  for (let i = 0; i < xs.length - 1; i++) {
    add("L" + i, "L" + (i + 1), "upperChord", i);
    add("R" + i, "R" + (i + 1), "upperChord", i);
    add("BL" + i, "BL" + (i + 1), "lowerChord", i);
    add("BR" + i, "BR" + (i + 1), "lowerChord", i);

    add("L" + i, "BL" + (i + 1), "web", i);
    add("R" + i, "BR" + (i + 1), "web", i);

    add("L" + i, "R" + (i + 1), "topPlan", i);
  }

  // Transverse frames and alternating diagonals close the 3-D panels.
  for (let i = 0; i < xs.length; i++) {
    add("L" + i, "BL" + i, "vertical", i);
    add("R" + i, "BR" + i, "vertical", i);
    add("L" + i, "R" + i, "topTie", i);
    add("BL" + i, "BR" + i, "bottomTie", i);

    if (i % 2 === 0) {
      add("L" + i, "BR" + i, "crossDiag", i);
    } else {
      add("R" + i, "BL" + i, "crossDiag", i);
    }
  }

  function makeNodes() {
    const nodes = [];
    for (let i = 0; i < xs.length; i++) {
      nodes.push({
        id: "BL" + i, x: xs[i], y: -7.50, z: -4.35, joint: "pin"
      });
      nodes.push({
        id: "BR" + i, x: xs[i], y: -7.50, z: 4.35, joint: "pin"
      });
    }
    return nodes;
  }

  function build(specs) {
    return {
      note,
      nodes: makeNodes(),
      members: records.map((m, i) => [m.a, m.b, specs[i]])
    };
  }

  function finite(v) {
    return Number.isFinite(v);
  }

  function metric(r, primary, alternate) {
    if (finite(r[primary])) return r[primary];
    if (alternate && finite(r[alternate])) return r[alternate];
    return null;
  }

  function isSafe(r) {
    if (!r || r.ok !== true) return false;
    if (finite(r.maxUtil) && r.maxUtil > 0.72) return false;
    if (finite(r.fatigueWorst) && r.fatigueWorst > 0.80) return false;

    const cr = metric(r, "alpha_crMin", "alpha_cr");
    if (cr !== null && cr < 8) return false;

    const f = metric(r, "frequency", "fMin");
    if (f !== null && f < 1.30) return false;

    if (finite(r.sag) && finite(r.sagLimit) &&
        r.sagLimit > 0 && r.sag / r.sagLimit > 0.82) return false;
    if (finite(r.sway) && finite(r.swayLimit) &&
        r.swayLimit > 0 && r.sway / r.swayLimit > 0.82) return false;

    if (r.robustness === false) return false;
    if (r.robustness && typeof r.robustness === "object" &&
        (r.robustness.ok === false || r.robustness.pass === false)) {
      return false;
    }

    return true;
  }

  function quality(r) {
    const u = finite(r.maxUtil) ? r.maxUtil : 1;
    const fatigue = finite(r.fatigueWorst) ? r.fatigueWorst : 1;
    const sagRatio = finite(r.sag) && finite(r.sagLimit) && r.sagLimit > 0
      ? r.sag / r.sagLimit
      : 1;
    const swayRatio = finite(r.sway) && finite(r.swayLimit) && r.swayLimit > 0
      ? r.sway / r.swayLimit
      : 1;
    return u + 0.20 * fatigue + 0.03 * sagRatio + 0.01 * swayRatio;
  }

  const callLimit = 398;
  let calls = 0;
  let best = null;

  function evaluate(specs) {
    if (calls >= callLimit) return null;

    const d = build(specs);
    let r;
    calls++;
    try {
      r = analyse(d);
    } catch (e) {
      return null;
    }
    if (!r || r.error) return null;

    const out = { d, specs: specs.slice(), r };

    if (isSafe(r) && finite(r.mass)) {
      if (!best ||
          r.mass < best.r.mass - 1e-6 ||
          (Math.abs(r.mass - best.r.mass) <= 1e-6 &&
           quality(r) < quality(best.r) - 1e-6)) {
        best = out;
      }
    }
    return out;
  }

  function memberInfo(r, id) {
    if (!r || !Array.isArray(r.members)) return null;
    const reverse = id.split("-").reverse().join("-");

    for (const m of r.members) {
      if (!m) continue;
      const mid = m.id || m.memberId || m.member || m.name;
      if (mid === id || mid === reverse) return m;
    }
    return null;
  }

  function materialOf(spec) {
    const k = spec.indexOf(" ");
    return k < 0 ? "S460" : spec.slice(0, k);
  }

  function sectionIdOf(spec) {
    const k = spec.indexOf("CHS");
    return k < 0 ? null : spec.slice(k + 3);
  }

  let currentSpecs = records.map(m => m.initial);
  let current = evaluate(currentSpecs);
  if (!current) return build(currentSpecs);

  currentSpecs = current.specs.slice();

  function proposalFor(index) {
    const rec = records[index];
    const spec = currentSpecs[index];
    const sectionId = sectionIdOf(spec);
    const currentArea = areaById[sectionId];
    if (!finite(currentArea)) return null;

    const info = memberInfo(current.r, rec.id);
    let u = info && finite(info.util) ? Math.max(0, info.util) : null;
    let mode = info && info.mode ? String(info.mode).toLowerCase() : "";

    if (u === null) {
      const globalU = finite(current.r.maxUtil) ? current.r.maxUtil : 0.65;
      u = Math.min(0.42, Math.max(0.20, globalU * 0.62));
    }

    let target = 0.64;
    let ratio;

    if (mode.indexOf("fatigue") >= 0) {
      target = 0.74;
      ratio = u / target;
    } else if (mode.indexOf("buckling") >= 0 ||
               mode.indexOf("compression") >= 0) {
      target = 0.61;
      ratio = Math.sqrt(Math.max(0.01, u / target));
    } else {
      ratio = u / target;
    }

    if (u >= target * 0.98) return null;
    ratio = Math.max(0.32, Math.min(0.94, ratio));

    const smaller = chs.filter(s => s.area < currentArea - 1e-6);
    if (smaller.length === 0) return null;

    const goal = currentArea * ratio;
    let start = 0;
    while (start < smaller.length && smaller[start].area < goal) start++;
    if (start >= smaller.length) start = smaller.length - 1;

    let preferredMaterial = materialOf(spec);
    if (mode.indexOf("fatigue") >= 0 && preferredMaterial === "S690") {
      preferredMaterial = "S460";
    }

    return {
      sections: smaller.slice(start),
      material: preferredMaterial,
      sourceMaterial: materialOf(spec),
      mode,
      saving: rec.length * currentArea * Math.max(0, 1 - ratio)
    };
  }

  function orderedIndices(indices) {
    return indices.map(i => {
      const p = proposalFor(i);
      return { i, saving: p ? p.saving : 0 };
    }).sort((a, b) => b.saving - a.saving);
  }

  const changed = [];

  function resizeOne(index, maxTries, stopAt) {
    if (!current || calls >= stopAt) return false;

    const p = proposalFor(index);
    if (!p) return false;

    const sourceMaterial = materialOf(currentSpecs[index]);
    const alternatives = [p.material];

    if (p.material === "S460" && sourceMaterial === "S690") {
      alternatives.push("S690");
    } else if (p.material === "S460" && sourceMaterial === "S460" &&
               p.mode.indexOf("fatigue") < 0 &&
               (records[index].role === "web" ||
                records[index].role === "vertical" ||
                records[index].role === "upperChord" ||
                records[index].role === "lowerChord")) {
      alternatives.push("S690");
    }

    const uniqueMaterials = [];
    for (const mat of alternatives) {
      if (uniqueMaterials.indexOf(mat) < 0) uniqueMaterials.push(mat);
    }

    const count = Math.min(maxTries, p.sections.length);
    for (let j = 0; j < count; j++) {
      const section = p.sections[j];

      for (const mat of uniqueMaterials) {
        if (calls >= stopAt || calls >= callLimit) return false;

        const trial = currentSpecs.slice();
        trial[index] = mat + " CHS" + section.id;
        const out = evaluate(trial);

        if (out && isSafe(out.r) && finite(out.r.mass) &&
            out.r.mass < current.r.mass - 1e-6) {
          current = out;
          currentSpecs = out.specs.slice();
          changed.push(index);
          return true;
        }
      }
    }
    return false;
  }

  const allIndices = records.map((_, i) => i);

  for (const item of orderedIndices(allIndices)) {
    if (calls >= 245) break;
    resizeOne(item.i, 2, 245);
  }

  for (const item of orderedIndices(allIndices)) {
    if (calls >= 292) break;
    resizeOne(item.i, 1, 292);
  }

  // Where fatigue governs an S690 member, test the same section in S460.
  const fatigueIndices = records.map((m, i) => i).filter(i => {
    const info = memberInfo(current.r, records[i].id);
    return materialOf(currentSpecs[i]) === "S690" &&
      info && info.mode &&
      String(info.mode).toLowerCase().indexOf("fatigue") >= 0;
  }).sort((a, b) => {
    const ia = memberInfo(current.r, records[a].id);
    const ib = memberInfo(current.r, records[b].id);
    return (ib && finite(ib.util) ? ib.util : 0) -
           (ia && finite(ia.util) ? ia.util : 0);
  });

  for (const i of fatigueIndices) {
    if (calls >= 320) break;

    const oldFatigue = finite(current.r.fatigueWorst)
      ? current.r.fatigueWorst
      : Infinity;
    const sectionId = sectionIdOf(currentSpecs[i]);
    const trial = currentSpecs.slice();
    trial[i] = "S460 CHS" + sectionId;

    const out = evaluate(trial);
    if (out && isSafe(out.r) && finite(out.r.mass) &&
        out.r.mass <= current.r.mass + 1e-6 &&
        finite(out.r.fatigueWorst) &&
        out.r.fatigueWorst < oldFatigue - 1e-6) {
      current = out;
      currentSpecs = out.specs.slice();
    }
  }

  function alRank(index) {
    const info = memberInfo(current.r, records[index].id);
    const u = info && finite(info.util) ? info.util : 0.42;
    const mode = info && info.mode ? String(info.mode).toLowerCase() : "";
    return u + (mode.indexOf("fatigue") >= 0 ? 0.60 : 0);
  }

  function tryAluminium(index) {
    if (calls >= callLimit) return false;

    const spec = currentSpecs[index];
    const sourceMaterial = materialOf(spec);
    if (sourceMaterial === "AL6082" || sourceMaterial === "AL7075") {
      return false;
    }

    const sectionId = sectionIdOf(spec);
    const start = indexById[sectionId];
    if (!finite(start)) return false;

    for (let step = 0; step <= 2 && start + step < chs.length; step++) {
      const section = chs[start + step];

      for (const mat of ["AL6082", "AL7075"]) {
        if (calls >= callLimit) return false;

        const trial = currentSpecs.slice();
        trial[index] = mat + " CHS" + section.id;
        const out = evaluate(trial);

        if (out && isSafe(out.r) && finite(out.r.mass) &&
            out.r.mass < current.r.mass - 1e-6) {
          current = out;
          currentSpecs = out.specs.slice();
          changed.push(index);
          return true;
        }
      }
    }
    return false;
  }

  const eligibleAluminium = [];
  for (let i = 0; i < records.length; i++) {
    const role = records[i].role;
    if (role === "topPlan" || role === "topTie" ||
        role === "bottomTie" || role === "crossDiag") {
      eligibleAluminium.push(i);
      continue;
    }

    if (role === "web" || role === "vertical") {
      const info = memberInfo(current.r, records[i].id);
      const mode = info && info.mode ? String(info.mode).toLowerCase() : "";
      if (info && finite(info.util) && info.util < 0.38 &&
          mode.indexOf("fatigue") < 0) {
        eligibleAluminium.push(i);
      }
    }
  }

  eligibleAluminium.sort((a, b) => {
    const d = alRank(a) - alRank(b);
    if (Math.abs(d) > 1e-9) return d;
    return records[b].length * areaById[sectionIdOf(currentSpecs[b])] -
           records[a].length * areaById[sectionIdOf(currentSpecs[a])];
  });

  for (const i of eligibleAluminium) {
    if (calls >= callLimit) break;
    tryAluminium(i);
  }

  // Use any remaining analyses for a final local reduction pass.
  const finalIndices = records.map((m, i) => i).filter(i =>
    materialOf(currentSpecs[i]) === "AL6082" ||
    materialOf(currentSpecs[i]) === "AL7075"
  );

  for (const i of finalIndices) {
    if (calls >= callLimit) break;
    resizeOne(i, 1, callLimit);
  }

  return best ? best.d : build(currentSpecs);
}

