    s460("244.5x8"), s460("219.1x8"), s460("219.1x8"),
    s460("139.7x5"), s460("168.3x6.3"), s460("168.3x6.3"),
    s460("168.3x6.3"), s460("193.7x6.3"), s460("193.7x6.3")
  ];
  const verticalR = [
    al6082("88.9x4"), s460("273x10"), s690("244.5x8"),
    s460("244.5x8"), s460("219.1x8"), s460("273x10"),
    s460("168.3x6.3"), s460("193.7x6.3"), s460("168.3x6.3"),
    s460("168.3x6.3"), s460("168.3x6.3"), s460("193.7x6.3")
  ];
  const topTie = [
    al6082("88.9x5"), s460("193.7x6.3"), al6082("219.1x8"),
    s460("168.3x6.3"), s460("168.3x6.3"), s460("139.7x5"),
    al6082("114.3x5"), al7075("168.3x5"), s460("139.7x6.3"),
    s460("168.3x6.3"), al6082("219.1x8"), s460("193.7x6.3")
  ];
  const bottomTie = [
    al6082("88.9x5"), al7075("76.1x4"), al6082("88.9x4"),
    al6082("88.9x4"), al6082("88.9x5"), al6082("88.9x4"),
    al6082("88.9x4"), al6082("88.9x4"), al6082("88.9x5"),
    al6082("76.1x4"), al6082("88.9x5"), al7075("76.1x4")
  ];
  const crossDiag = [
    al6082("114.3x5"), s460("114.3x5"), al6082("139.7x5"),
    s460("114.3x5"), s460("114.3x5"), al7075("139.7x5"),
    s460("114.3x5"), al7075("139.7x5"), s460("114.3x5"),
    s460("114.3x5"), s460("114.3x5"), s460("114.3x5")
  ];

  const chs = [
    ["33.7x2.6", 2.54], ["42.4x3.2", 3.94], ["48.3x3.2", 4.53],
    ["60.3x3.2", 5.74], ["60.3x4", 7.07], ["76.1x3.2", 7.33],
    ["76.1x4", 9.06], ["88.9x4", 10.67], ["88.9x5", 13.18],
    ["114.3x4", 13.86], ["114.3x5", 17.17], ["139.7x5", 21.16],
    ["168.3x5", 25.65], ["139.7x6.3", 26.4], ["168.3x6.3", 32.06],
    ["193.7x6.3", 37.09], ["193.7x8", 46.67], ["219.1x8", 53.06],
    ["244.5x8", 59.44], ["273x10", 82.62], ["323.9x10", 98.61],
    ["355.6x12.5", 134.74], ["406.4x12.5", 154.68],
    ["457x16", 221.67]
  ].map(x => ({ id: x[0], area: x[1] }))
   .sort((a, b) => a.area - b.area);

  const areaById = Object.create(null);
  for (const sec of chs) areaById[sec.id] = sec.area;

  const wireArea = {
    "8": 0.30, "10": 0.47, "12": 0.68, "16": 1.21,
    "20": 1.88, "24": 2.71, "32": 4.83, "40": 7.54
  };
  const density = {
    S235: 7850, S355: 7850, S460: 7850, S690: 7850,
    SS316: 8000, AL6082: 2700, AL7075: 2810,
    GL28: 420, WIRE: 7850
  };

  function point(id) {
    const m = /^(BL|BR|L|R)(\d+)$/.exec(id);
    if (!m) return [0, 0, 0];
    const kind = m[1];
    const i = Number(m[2]);
    const bottom = kind === "BL" || kind === "BR";
    const left = kind === "L" || kind === "BL";
    return [xs[i], bottom ? -7.5 : 0, left ? -4.35 : 4.35];
  }

  function lengthOf(a, b) {
    const p = point(a);
    const q = point(b);
    const dx = p[0] - q[0];
    const dy = p[1] - q[1];
    const dz = p[2] - q[2];
    return Math.sqrt(dx * dx + dy * dy + dz * dz);
  }

  function makeNodes() {
    const nodes = [];
    for (let i = 0; i < xs.length; i++) {
      nodes.push({
        id: "BL" + i, x: xs[i], y: -7.5, z: -4.35, joint: "pin"
      });
      nodes.push({
        id: "BR" + i, x: xs[i], y: -7.5, z: 4.35, joint: "pin"
      });
    }
    return nodes;
  }

  function makeRecords(cfg) {
    const records = [];

    function add(a, b, role, i, initial) {
      records.push({
        a, b, id: a + "-" + b, role, i,
        length: lengthOf(a, b), initial
      });
    }

    for (let i = 0; i < xs.length - 1; i++) {
      add("L" + i, "L" + (i + 1), "upperChord", i, upperL[i]);
      add("R" + i, "R" + (i + 1), "upperChord", i, upperR[i]);
      add("BL" + i, "BL" + (i + 1), "lowerChord", i, lowerL[i]);
      add("BR" + i, "BR" + (i + 1), "lowerChord", i, lowerR[i]);

      const reverseWeb = cfg.webCut >= 0 && i >= cfg.webCut;
      if (reverseWeb) {
        add("BL" + i, "L" + (i + 1), "web", i, webL[i]);
        add("BR" + i, "R" + (i + 1), "web", i, webR[i]);
      } else {
        add("L" + i, "BL" + (i + 1), "web", i, webL[i]);
        add("R" + i, "BR" + (i + 1), "web", i, webR[i]);
      }

      if (cfg.altPlan && i % 2 === 1) {
        add("R" + i, "L" + (i + 1), "topPlan", i, topPlan[i]);
      } else {
        add("L" + i, "R" + (i + 1), "topPlan", i, topPlan[i]);
      }
    }

    for (let i = 0; i < xs.length; i++) {
      add("L" + i, "BL" + i, "vertical", i, verticalL[i]);
      add("R" + i, "BR" + i, "vertical", i, verticalR[i]);
      add("L" + i, "R" + i, "topTie", i, topTie[i]);
      add("BL" + i, "BR" + i, "bottomTie", i, bottomTie[i]);

      if (i % 2 === 0) {
        add("L" + i, "BR" + i, "crossDiag", i, crossDiag[i]);
      } else {
        add("R" + i, "BL" + i, "crossDiag", i, crossDiag[i]);
      }
    }

    return records;
  }

  function build(records, specs) {
    return {
      note,
      nodes: makeNodes(),
      members: records.map((m, i) => [m.a, m.b, specs[i]])
    };
  }

  function finite(x) {
    return Number.isFinite(x);
  }

  function metric(r, primary, alternate) {
    if (finite(r[primary])) return r[primary];
    if (alternate && finite(r[alternate])) return r[alternate];
    return null;
  }

  function isSafe(r) {
    if (!r || r.ok !== true) return false;
    if (finite(r.maxUtil) && r.maxUtil > 0.74) return false;
    if (finite(r.fatigueWorst) && r.fatigueWorst > 0.82) return false;

    const cr = metric(r, "alpha_crMin", "alpha_cr");
    if (cr !== null && cr < 8) return false;

    const f = metric(r, "frequency", "fMin");
    if (f !== null && f < 1.30) return false;

    if (finite(r.sag) && finite(r.sagLimit) && r.sagLimit > 0 &&
        r.sag / r.sagLimit > 0.86) return false;
    if (finite(r.sway) && finite(r.swayLimit) && r.swayLimit > 0 &&
        r.sway / r.swayLimit > 0.86) return false;

    if (r.robustness === false) return false;
    if (r.robustness && typeof r.robustness === "object" &&
        (r.robustness.ok === false || r.robustness.pass === false)) {
      return false;
    }
    return true;
  }

  function quality(r) {
    const u = finite(r.maxUtil) ? r.maxUtil : 1;
    const fatigue = finite(r.fatigueWorst) ? r.fatigueWorst : 1;
    const sag = finite(r.sag) && finite(r.sagLimit) && r.sagLimit > 0
      ? r.sag / r.sagLimit : 1;
    const sway = finite(r.sway) && finite(r.swayLimit) && r.swayLimit > 0
      ? r.sway / r.swayLimit : 1;
    return u + 0.18 * fatigue + 0.03 * sag + 0.01 * sway;
  }

  function preferable(a, b) {
    if (!a || !isSafe(a.r) || !finite(a.r.mass)) return false;
    if (!b) return true;
    if (a.r.mass < b.r.mass - 1e-6) return true;
    return Math.abs(a.r.mass - b.r.mass) <= 1e-6 &&
      quality(a.r) < quality(b.r) - 1e-6;
  }

  const callLimit = 398;
  let calls = 0;
  let best = null;
  let cur = null;

  function evaluate(records, specs, cfg) {
    if (calls >= callLimit) return null;
    const d = build(records, specs);
    let r;
    calls++;
    try {
      r = analyse(d);
    } catch (e) {
      return null;
    }
    if (!r || r.error) return null;

    const out = {
      cfg,
      records: records.slice(),
      specs: specs.slice(),
      d,
      r
    };

    if (isSafe(r) && finite(r.mass) && preferable(out, best)) best = out;
    return out;
  }

  function memberInfo(r, id) {
    if (!r || !Array.isArray(r.members)) return null;
    const reverse = id.split("-").reverse().join("-");
    for (const m of r.members) {
      if (!m) continue;
      const mid = m.id || m.memberId || m.member || m.name;
      if (mid === id || mid === reverse) return m;
    }
    return null;
  }

  function materialOf(spec) {
    const k = spec.indexOf(" ");
    return k < 0 ? spec : spec.slice(0, k);
  }

  function sectionIdOf(spec) {
    const k = spec.indexOf("CHS");
    return k < 0 ? null : spec.slice(k + 3);
  }

  function approximateMass(rec, spec) {
    const mat = materialOf(spec);
    let a = areaById[sectionIdOf(spec)];
    if (!finite(a)) {
      const w = /^WIRE WIRE(\d+)$/.exec(spec);
      if (w) a = wireArea[w[1]];
    }
    const rho = density[mat];
    if (!finite(a) || !finite(rho)) return 0;
    return rec.length * a * 1e-4 * rho;
  }

  function memberUtil(r, id) {
    const info = memberInfo(r, id);
    if (info && finite(info.util)) return Math.max(0, info.util);
    return 1;
  }

  function chooseCurrent(out) {
    if (out && preferable(out, cur)) cur = out;
  }

  const seedConfigs = [
    { webCut: -1, altPlan: false },
    { webCut: 6, altPlan: false },
    { webCut: 5, altPlan: false },
    { webCut: -1, altPlan: true },
    { webCut: 6, altPlan: true }
  ];

  for (const cfg of seedConfigs) {
    if (calls >= callLimit) break;
    const records = makeRecords(cfg);
    const out = evaluate(records, records.map(m => m.initial), cfg);
    chooseCurrent(out);
  }

  const fallbackRecords = makeRecords({ webCut: -1, altPlan: false });
  if (!cur) {
    return build(fallbackRecords, fallbackRecords.map(m => m.initial));
  }

  function pruneLow(stopAt) {
    if (!cur) return;
    const order = cur.records.map(m => {
      const u = memberUtil(cur.r, m.id);
      return {
        id: m.id,
        u,
        potential: approximateMass(m, cur.specs[cur.records.indexOf(m)]) *
          Math.max(0, 1 - u)
      };
    }).filter(x => x.u < 0.47)
      .sort((a, b) => b.potential - a.potential);

    for (const item of order) {
      if (calls >= stopAt || calls >= callLimit) break;
      const i = cur.records.findIndex(m => m.id === item.id);
      if (i < 0 || memberUtil(cur.r, item.id) >= 0.47) continue;

      const records = cur.records.filter((_, j) => j !== i);
      const specs = cur.specs.filter((_, j) => j !== i);
      const out = evaluate(records, specs, cur.cfg);
      if (out && isSafe(out.r) && finite(out.r.mass) &&
          out.r.mass < cur.r.mass - 1e-6) {
        cur = out;
      }
    }
  }

  function proposalFor(index) {
    const rec = cur.records[index];
    const spec = cur.specs[index];
    const secId = sectionIdOf(spec);
    const currentArea = areaById[secId];
    if (!finite(currentArea)) return null;

    const info = memberInfo(cur.r, rec.id);
    let u = info && finite(info.util) ? Math.max(0, info.util) : null;
    const mode = info && info.mode ? String(info.mode).toLowerCase() : "";
    if (u === null) {
      u = finite(cur.r.maxUtil) ? Math.min(0.45, cur.r.maxUtil * 0.60) : 0.35;
    }

    let target = 0.70;
    let ratio;
    if (mode.indexOf("fatigue") >= 0) {
      target = 0.76;
      ratio = u / target;
    } else if (mode.indexOf("buckling") >= 0 ||
               mode.indexOf("compression") >= 0) {
      target = 0.68;
      ratio = Math.sqrt(Math.max(0.01, u / target));
    } else {
      ratio = u / target;
    }

    if (u >= target * 0.995) return null;
    ratio = Math.max(0.32, Math.min(0.96, ratio));

    const smaller = chs.filter(s => s.area < currentArea - 1e-6);
    if (smaller.length === 0) return null;

    const goal = currentArea * ratio;
    let start = 0;
    while (start < smaller.length && smaller[start].area < goal) start++;
    if (start >= smaller.length) start = smaller.length - 1;

    return {
      material: materialOf(spec),
      sections: smaller.slice(start)
    };
  }

  function resizeOne(id, maxTries, stopAt) {
    if (!cur || calls >= stopAt || calls >= callLimit) return false;
    const index = cur.records.findIndex(m => m.id === id);
    if (index < 0) return false;

    const proposal = proposalFor(index);
    if (!proposal) return false;

    const count = Math.min(maxTries, proposal.sections.length);
    for (let j = 0; j < count; j++) {
      if (calls >= stopAt || calls >= callLimit) return false;
      const trial = cur.specs.slice();
      trial[index] = proposal.material + " CHS" + proposal.sections[j].id;
      const out = evaluate(cur.records, trial, cur.cfg);
      if (out && isSafe(out.r) && finite(out.r.mass) &&
          out.r.mass < cur.r.mass - 1e-6) {
        cur = out;
        return true;
      }
    }
    return false;
  }

  function orderedResizeIds() {
    if (!cur) return [];
    return cur.records.map((m, i) => {
      const u = memberUtil(cur.r, m.id);
      return {
        id: m.id,
        priority: approximateMass(m, cur.specs[i]) *
          Math.max(0.03, 1 - Math.min(0.98, u) / 0.80)
      };
    }).sort((a, b) => b.priority - a.priority);
  }

  function resizePass(stopAt, maxTries) {
    const order = orderedResizeIds();
    for (const item of order) {
      if (calls >= stopAt || calls >= callLimit) break;
      resizeOne(item.id, maxTries, stopAt);
    }
  }

  pruneLow(42);
  resizePass(178, 2);
  resizePass(278, 2);

  function tryAluminium(id, stopAt) {
    if (!cur || calls >= stopAt || calls >= callLimit) return false;
    const index = cur.records.findIndex(m => m.id === id);
    if (index < 0) return false;

    const rec = cur.records[index];
    const spec = cur.specs[index];
    const sourceMaterial = materialOf(spec);
    const secId = sectionIdOf(spec);
    const currentArea = areaById[secId];
    if (!finite(currentArea) || sourceMaterial === "AL6082" ||
        sourceMaterial === "AL7075") return false;

    const info = memberInfo(cur.r, rec.id);
    const u = info && finite(info.util) ? info.util :
      (finite(cur.r.maxUtil) ? cur.r.maxUtil * 0.55 : 0.40);
    const mode = info && info.mode ? String(info.mode).toLowerCase() : "";
    if (mode.indexOf("fatigue") >= 0 || u > 0.50) return false;

    const buckling = mode.indexOf("buckling") >= 0 ||
      mode.indexOf("compression") >= 0;
    if (buckling && u > 0.27) return false;

    let trial = cur.specs.slice();
    trial[index] = "AL7075 CHS" + secId;
    let out = evaluate(cur.records, trial, cur.cfg);
    if (out && isSafe(out.r) && finite(out.r.mass) &&
        out.r.mass < cur.r.mass - 1e-6) {
      cur = out;
      return true;
    }

    if (calls >= stopAt || calls >= callLimit) return false;
    const factor = buckling ? 1.35 : 1.25;
    const larger = chs.find(s => s.area >= currentArea * factor);
    if (!larger || larger.area > currentArea * 1.80) return false;

    trial = cur.specs.slice();
    trial[index] = "AL7075 CHS" + larger.id;
    out = evaluate(cur.records, trial, cur.cfg);
    if (out && isSafe(out.r) && finite(out.r.mass) &&
        out.r.mass < cur.r.mass - 1e-6) {
      cur = out;
      return true;
    }
    return false;
  }

  const alOrder = cur.records.map((m, i) => ({
    id: m.id,
    mass: approximateMass(m, cur.specs[i])
  })).sort((a, b) => b.mass - a.mass);

  for (const item of alOrder) {
    if (calls >= 326 || calls >= callLimit) break;
    tryAluminium(item.id, 326);
  }

  function addAssistWires(state, wireSpec) {
    const records = state.records.slice();
    const specs = state.specs.slice();
    const extras = [];

    for (const m of state.records) {
      if (m.role === "topPlan") {
        if (m.a === "L" + m.i) {
          extras.push({
            a: "R" + m.i, b: "L" + (m.i + 1),
            role: "planCable", i: m.i
          });
        } else {
          extras.push({
            a: "L" + m.i, b: "R" + (m.i + 1),
            role: "planCable", i: m.i
          });
        }
      } else if (m.role === "crossDiag") {
        if (m.a === "L" + m.i) {
          extras.push({
            a: "R" + m.i, b: "BL" + m.i,
            role: "crossCable", i: m.i
          });
        } else {
          extras.push({
            a: "L" + m.i, b: "BR" + m.i,
            role: "crossCable", i: m.i
          });
        }
      }
    }

    for (const e of extras) {
      records.push({
        a: e.a, b: e.b, id: e.a + "-" + e.b,
        role: e.role, i: e.i, length: lengthOf(e.a, e.b),
        initial: wireSpec
      });
      specs.push(wireSpec);
    }
    return evaluate(records, specs, state.cfg);
  }

  if (calls < callLimit && best) {
    const source = best;
    let branch = null;
    for (const size of [16, 20, 24, 32, 40]) {
      if (calls >= callLimit) break;
      const out = addAssistWires(source, "WIRE WIRE" + size);
      if (out && isSafe(out.r) && finite(out.r.mass)) {
        branch = out;
        break;
      }
    }

    if (branch) {
      const saved = cur;
      cur = branch;

      const braces = cur.records.filter(m =>
        m.role === "topPlan" || m.role === "crossDiag"
      ).map(m => ({
        id: m.id,
        mass: approximateMass(m, cur.specs[cur.records.indexOf(m)])
      })).sort((a, b) => b.mass - a.mass);

      for (const item of braces) {
        if (calls >= callLimit) break;
        resizeOne(item.id, 2, callLimit);
      }
      if (calls < callLimit) resizePass(callLimit, 2);
      cur = saved;
    }
  }

  if (best && calls < callLimit) {
    cur = best;
    pruneLow(callLimit);
    if (calls < callLimit) resizePass(callLimit, 2);
  }

  return best ? best.d :
    build(fallbackRecords, fallbackRecords.map(m => m.initial));
}

