  const lowerR = parseSpecs(
    "H:88.9x4 S:168.3x6.3 S:193.7x8 H:219.1x8 H:273x10 H:273x10 " +
    "H:273x10 H:273x10 H:219.1x8 H:193.7x6.3 S:168.3x6.3"
  );
  const webL = parseSpecs(
    "S:193.7x8 H:193.7x6.3 S:193.7x6.3 S:193.7x6.3 S:193.7x6.3 " +
    "S:168.3x6.3 S:244.5x8 S:273x10 S:273x10 H:273x10 S:323.9x10"
  );
  const webR = parseSpecs(
    "S:193.7x8 S:193.7x6.3 S:193.7x6.3 S:193.7x6.3 S:193.7x8 " +
    "S:323.9x10 S:244.5x8 S:273x10 S:273x10 S:273x10 S:323.9x10"
  );
  const topPlan = parseSpecs(
    "A:273x10 S:193.7x8 S:193.7x6.3 S:168.3x6.3 S:139.7x6.3 " +
    "B:139.7x5 S:168.3x5 S:168.3x6.3 S:193.7x6.3 S:193.7x8 S:193.7x8"
  );
  const verticalL = parseSpecs(
    "A:88.9x4 S:273x10 S:273x10 S:244.5x8 S:219.1x8 S:219.1x8 " +
    "S:139.7x5 S:168.3x6.3 S:168.3x6.3 S:168.3x6.3 S:193.7x6.3 S:193.7x6.3"
  );
  const verticalR = parseSpecs(
    "A:88.9x4 S:273x10 H:244.5x8 S:244.5x8 S:219.1x8 S:273x10 " +
    "S:168.3x6.3 S:193.7x6.3 S:168.3x6.3 S:168.3x6.3 S:168.3x6.3 S:193.7x6.3"
  );
  const topTie = parseSpecs(
    "A:88.9x5 S:193.7x6.3 A:219.1x8 S:168.3x6.3 S:168.3x6.3 S:139.7x5 " +
    "A:114.3x5 B:168.3x5 S:139.7x6.3 S:168.3x6.3 A:219.1x8 S:193.7x6.3"
  );
  const bottomTie = parseSpecs(
    "A:88.9x5 B:76.1x4 A:88.9x4 A:88.9x4 A:88.9x5 A:88.9x4 " +
    "A:88.9x4 A:88.9x4 A:88.9x5 A:76.1x4 A:88.9x5 B:76.1x4"
  );
  const crossDiag = parseSpecs(
    "A:114.3x5 S:114.3x5 A:139.7x5 S:114.3x5 S:114.3x5 B:139.7x5 " +
    "S:114.3x5 B:139.7x5 S:114.3x5 S:114.3x5 S:114.3x5 S:114.3x5"
  );

  function finite(x) {
    return Number.isFinite(x);
  }

  function point(id) {
    const m = /^(BL|BR|L|R)(\d+)$/.exec(id);
    if (!m) return [0, 0, 0];
    const kind = m[1];
    const i = Number(m[2]);
    const bottom = kind === "BL" || kind === "BR";
    const left = kind === "L" || kind === "BL";
    return [xs[i], bottom ? bottomY : 0, left ? -4.35 : 4.35];
  }

  function lengthOf(a, b) {
    const p = point(a);
    const q = point(b);
    const dx = p[0] - q[0];
    const dy = p[1] - q[1];
    const dz = p[2] - q[2];
    return Math.sqrt(dx * dx + dy * dy + dz * dz);
  }

  function addRecord(records, a, b, role, i, initial) {
    records.push({
      a, b, role, i, initial,
      id: a + "-" + b,
      length: lengthOf(a, b)
    });
  }

  function makeRecords(cfg) {
    const records = [];
    for (let i = 0; i < xs.length - 1; i++) {
      addRecord(records, "L" + i, "L" + (i + 1), "upperChord", i, upperL[i]);
      addRecord(records, "R" + i, "R" + (i + 1), "upperChord", i, upperR[i]);
      addRecord(records, "BL" + i, "BL" + (i + 1), "lowerChord", i, lowerL[i]);
      addRecord(records, "BR" + i, "BR" + (i + 1), "lowerChord", i, lowerR[i]);

      const reverseWeb = cfg.webCut >= 0 && i >= cfg.webCut;
      if (reverseWeb) {
        addRecord(records, "BL" + i, "L" + (i + 1), "web", i, webL[i]);
        addRecord(records, "BR" + i, "R" + (i + 1), "web", i, webR[i]);
      } else {
        addRecord(records, "L" + i, "BL" + (i + 1), "web", i, webL[i]);
        addRecord(records, "R" + i, "BR" + (i + 1), "web", i, webR[i]);
      }

      if (cfg.altPlan && i % 2 === 1) {
        addRecord(records, "R" + i, "L" + (i + 1), "topPlan", i, topPlan[i]);
      } else {
        addRecord(records, "L" + i, "R" + (i + 1), "topPlan", i, topPlan[i]);
      }
    }

    for (let i = 0; i < xs.length; i++) {
      addRecord(records, "L" + i, "BL" + i, "vertical", i, verticalL[i]);
      addRecord(records, "R" + i, "BR" + i, "vertical", i, verticalR[i]);
      addRecord(records, "L" + i, "R" + i, "topTie", i, topTie[i]);
      addRecord(records, "BL" + i, "BR" + i, "bottomTie", i, bottomTie[i]);

      if (i % 2 === 0) {
        addRecord(records, "L" + i, "BR" + i, "crossDiag", i, crossDiag[i]);
      } else {
        addRecord(records, "R" + i, "BL" + i, "crossDiag", i, crossDiag[i]);
      }
    }
    return records;
  }

  function makeNodes() {
    const nodes = [];
    for (let i = 0; i < xs.length; i++) {
      nodes.push({
        id: "BL" + i, x: xs[i], y: bottomY, z: -4.35, joint: "pin"
      });
      nodes.push({
        id: "BR" + i, x: xs[i], y: bottomY, z: 4.35, joint: "pin"
      });
    }
    return nodes;
  }

  function makeState(cfg, usePlan, useCross, planSize, crossSize) {
    const baseRecords = makeRecords(cfg);
    const baseSpecs = baseRecords.map(m => m.initial);
    if (!usePlan && !useCross) {
      return {
        records: baseRecords,
        specs: baseSpecs,
        cfg,
        nodeY: bottomY
      };
    }

    const records = [];
    const specs = [];

    function appendCable(a, b, role, i, size) {
      const spec = "WIRE WIRE" + size;
      addRecord(records, a, b, role, i, spec);
      specs.push(spec);
    }

    for (let j = 0; j < baseRecords.length; j++) {
      const m = baseRecords[j];
      records.push(m);
      specs.push(baseSpecs[j]);

      if (usePlan && m.role === "topPlan") {
        if (m.a.charAt(0) === "L") {
          appendCable("R" + m.i, "L" + (m.i + 1), "planCable", m.i, planSize);
        } else {
          appendCable("L" + m.i, "R" + (m.i + 1), "planCable", m.i, planSize);
        }
      }

      if (useCross && m.role === "crossDiag") {
        if (m.a.charAt(0) === "L") {
          appendCable("R" + m.i, "BL" + m.i, "crossCable", m.i, crossSize);
        } else {
          appendCable("L" + m.i, "BR" + m.i, "crossCable", m.i, crossSize);
        }
      }
    }

    return { records, specs, cfg, nodeY: bottomY };
  }

  function makeDesign(state) {
    return {
      note,
      nodes: makeNodes(),
      members: state.records.map((m, i) => [m.a, m.b, state.specs[i]])
    };
  }

  const CALL_LIMIT = 398;
  const TARGET_U = 0.74;
  let calls = 0;

  function evaluate(records, specs, cfg, nodeY) {
    if (calls >= CALL_LIMIT) return null;
    const state = {
      records: records.slice(),
      specs: specs.slice(),
      cfg,
      nodeY
    };
    let r;
    calls++;
    try {
      r = analyse(makeDesign(state));
    } catch (e) {
      return null;
    }
    if (!r || r.error) return null;
    state.r = r;
    return state;
  }

  function evaluateState(state) {
    return evaluate(state.records, state.specs, state.cfg, state.nodeY);
  }

  function robustnessPasses(r) {
    if (r.robustness === false) return false;
    if (r.robustness && typeof r.robustness === "object" &&
        (r.robustness.ok === false || r.robustness.pass === false)) {
      return false;
    }
    return true;
  }

  function usable(r) {
    return !!r && r.ok === true && finite(r.mass) && robustnessPasses(r);
  }

  function metric(r, a, b) {
    if (finite(r[a])) return r[a];
    if (b && finite(r[b])) return r[b];
    return null;
  }

  function peakUtil(r) {
    let p = finite(r.maxUtil) ? r.maxUtil : 0;
    if (Array.isArray(r.cases)) {
      for (const c of r.cases) {
        if (c && finite(c.maxUtil)) p = Math.max(p, c.maxUtil);
      }
    }
    if (Array.isArray(r.members)) {
      for (const m of r.members) {
        if (m && finite(m.util)) p = Math.max(p, m.util);
      }
    }
    return p;
  }

  function envelopePasses(r) {
    if (!usable(r) || peakUtil(r) > TARGET_U + 1e-6) return false;

    if (finite(r.fatigueWorst) && r.fatigueWorst > 0.82) return false;

    const cr = metric(r, "alpha_crMin", "alpha_cr");
    if (cr !== null && cr < 8) return false;

    const f = metric(r, "frequency", "fMin");
    if (f !== null && f < 1.30) return false;

    if (finite(r.sag) && finite(r.sagLimit) && r.sagLimit > 0 &&
        r.sag / r.sagLimit > 0.84) return false;
    if (finite(r.sway) && finite(r.swayLimit) && r.swayLimit > 0 &&
        r.sway / r.swayLimit > 0.84) return false;

    return true;
  }

  function materialOf(spec) {
    const k = spec.indexOf(" ");
    return k < 0 ? spec : spec.slice(0, k);
  }

  function sectionIdOf(spec) {
    const k = spec.indexOf("CHS");
    return k < 0 ? null : spec.slice(k + 3);
  }

  function memberName(m) {
    if (!m) return null;
    return m.id || m.memberId || m.member || m.name || null;
  }

  function reverseId(id) {
    if (typeof id !== "string") return null;
    const p = id.split("-");
    return p.length === 2 ? p[1] + "-" + p[0] : null;
  }

  function memberInfo(r, id) {
    if (!r || !Array.isArray(r.members) || !id) return null;
    const rev = reverseId(id);
    for (const m of r.members) {
      const mid = memberName(m);
      if (mid === id || mid === rev) return m;
    }
    return null;
  }

  function idFromGoverning(g) {
    if (typeof g === "string") return g;
    if (g && typeof g === "object") {
      return g.id || g.memberId || g.member || g.name || null;
    }
    return null;
  }

  function worstTarget(r) {
    let worstCase = null;
    if (Array.isArray(r.cases)) {
      for (const c of r.cases) {
        if (c && finite(c.maxUtil) &&
            (!worstCase || c.maxUtil > worstCase.maxUtil)) {
          worstCase = c;
        }
      }
    }

    if (worstCase) {
      const id = idFromGoverning(worstCase.governing);
      if (id) {
        const info = memberInfo(r, id);
        return {
          id,
          mode: (info && info.mode) || worstCase.mode || "",
          util: info && finite(info.util) ? info.util : worstCase.maxUtil
        };
      }
    }

    let top = null;
    if (Array.isArray(r.members)) {
      for (const m of r.members) {
        const id = memberName(m);
        if (id && finite(m.util) && (!top || m.util > top.util)) {
          top = { id, mode: m.mode || "", util: m.util };
        }
      }
    }
    return top;
  }

  function recordIndicesForId(records, id) {
    const rev = reverseId(id);
    const out = [];
    for (let i = 0; i < records.length; i++) {
      if (records[i].id === id || records[i].id === rev) out.push(i);
    }
    return out;
  }

  function upgradeSpecs(state, id, mode) {
    const indices = recordIndicesForId(state.records, id);
    if (indices.length === 0) return [];
    const i = indices[0];
    const spec = state.specs[i];
    const wireMatch = /^WIRE WIRE(\d+)$/.exec(spec);
    const out = [];

    if (wireMatch) {
      const current = Number(wireMatch[1]);
      for (const size of wireSizes) {
        if (size > current) {
          const specs = state.specs.slice();
          specs[i] = "WIRE WIRE" + size;
          out.push(specs);
          break;
        }
      }
      return out;
    }

    const sectionId = sectionIdOf(spec);
    const sectionIndex = chs.findIndex(s => s.id === sectionId);
    if (sectionIndex < 0) return out;

    const material = materialOf(spec);
    for (let j = sectionIndex + 1; j < chs.length && out.length < 2; j++) {
      const specs = state.specs.slice();
      specs[i] = material + " CHS" + chs[j].id;
      out.push(specs);
    }

    const modeText = String(mode || "").toLowerCase();
    if ((material === "AL6082" || material === "AL7075") &&
        modeText.indexOf("buckling") >= 0 && out.length < 3) {
      const specs = state.specs.slice();
      specs[i] = "S460 CHS" + sectionId;
      out.push(specs);
    } else if (material === "S690" &&
               modeText.indexOf("fatigue") >= 0 && out.length < 3) {
      const specs = state.specs.slice();
      specs[i] = "S460 CHS" + sectionId;
      out.push(specs);
    }

    return out.slice(0, 2);
  }

  function targetMemberUtil(r, id, fallback) {
    const m = memberInfo(r, id);
    return m && finite(m.util) ? m.util : fallback;
  }

  function harden(start, maxSteps) {
    if (!start || !usable(start.r)) return null;
    let cur = start;

    for (let step = 0; step < maxSteps && calls < CALL_LIMIT; step++) {
      if (envelopePasses(cur.r)) return cur;

      const target = worstTarget(cur.r);
      if (!target || !target.id) return null;

      const oldPeak = peakUtil(cur.r);
      const oldTarget = targetMemberUtil(cur.r, target.id, target.util);
      const options = upgradeSpecs(cur, target.id, target.mode);
      let best = null;

      for (const specs of options) {
        if (calls >= CALL_LIMIT) break;
        const trial = evaluate(cur.records, specs, cur.cfg, cur.nodeY);
        if (!trial || !usable(trial.r)) continue;

        const newPeak = peakUtil(trial.r);
        const newTarget = targetMemberUtil(trial.r, target.id, oldTarget);
        const improvesPeak = newPeak < oldPeak - 1e-4;
        const improvesMember = newPeak <= oldPeak + 1e-6 &&
          newTarget < oldTarget - 1e-4;

        if ((improvesPeak || improvesMember) &&
            (!best || newPeak < peakUtil(best.r) - 1e-6 ||
             (Math.abs(newPeak - peakUtil(best.r)) <= 1e-6 &&
              trial.r.mass < best.r.mass))) {
          best = trial;
        }
      }

      if (!best) return null;
      cur = best;
    }

    return envelopePasses(cur.r) ? cur : null;
  }

  function approximateMass(rec, spec) {
    const mat = materialOf(spec);
    let area = null;
    const wireMatch = /^WIRE WIRE(\d+)$/.exec(spec);
    if (wireMatch) {
      area = wireArea[Number(wireMatch[1])];
    } else {
      area = areaById[sectionIdOf(spec)];
    }
    const rho = density[mat];
    if (!finite(area) || !finite(rho)) return 0;
    return rec.length * area * 1e-4 * rho;
  }

  function resizeProposals(state, i) {
    const rec = state.records[i];
    const spec = state.specs[i];
    const info = memberInfo(state.r, rec.id);
    const u = info && finite(info.util) ? Math.max(0, info.util) :
      Math.min(0.45, peakUtil(state.r) * 0.60);
    const mode = String(info && info.mode || "").toLowerCase();

    let target = 0.66;
    let ratio;
    if (mode.indexOf("fatigue") >= 0) {
      target = 0.70;
      ratio = u / target;
    } else if (mode.indexOf("buckling") >= 0 ||
               mode.indexOf("compression") >= 0) {
      target = 0.60;
      ratio = Math.sqrt(Math.max(0.01, u / target));
    } else {
      ratio = u / target;
    }

    if (u >= target * 0.98) return [];

    ratio = Math.max(0.32, Math.min(0.95, ratio));
    const wireMatch = /^WIRE WIRE(\d+)$/.exec(spec);

    if (wireMatch) {
      const current = Number(wireMatch[1]);
      const smaller = wireSizes.filter(s => s < current);
      if (smaller.length === 0) return [];
      const goal = wireArea[current] * ratio;
      let j = smaller.findIndex(s => wireArea[s] >= goal);
      if (j < 0) j = smaller.length - 1;
      return smaller.slice(j, Math.min(smaller.length, j + 2))
        .map(s => "WIRE WIRE" + s);
    }

    const sectionId = sectionIdOf(spec);
    const sectionIndex = chs.findIndex(s => s.id === sectionId);
    const currentArea = areaById[sectionId];
    if (sectionIndex < 0 || !finite(currentArea)) return [];

    const smaller = chs.filter(s => s.area < currentArea - 1e-6);
    if (smaller.length === 0) return [];
    const goal = currentArea * ratio;
    let j = smaller.findIndex(s => s.area >= goal);
    if (j < 0) j = smaller.length - 1;
    return smaller.slice(j, Math.min(smaller.length, j + 2))
      .map(s => materialOf(spec) + " CHS" + s.id);
  }

  function isBetter(a, b) {
    if (!a || !envelopePasses(a.r)) return false;
    if (!b) return true;
    if (a.r.mass < b.r.mass - 1e-6) return true;
    return Math.abs(a.r.mass - b.r.mass) <= 1e-6 &&
      peakUtil(a.r) < peakUtil(b.r) - 1e-6;
  }

  function resizeState(start, budget) {
    if (!start || !envelopePasses(start.r) || budget <= 0) return start;
    const startCalls = calls;
    let cur = start;

    for (let pass = 0; pass < 2 && calls - startCalls < budget; pass++) {
      const order = cur.records.map((rec, i) => {
        const info = memberInfo(cur.r, rec.id);
        const u = info && finite(info.util) ? info.util : 0.45;
        const mass = approximateMass(rec, cur.specs[i]);
        return {
          i,
          priority: mass * Math.max(0.03, 1 - Math.min(0.98, u) / 0.74)
        };
      }).sort((a, b) => b.priority - a.priority);

      for (const item of order) {
        if (calls - startCalls >= budget || calls >= CALL_LIMIT) break;
        const i = item.i;
        const proposals = resizeProposals(cur, i);
        if (proposals.length === 0) continue;

        const maxTry = calls - startCalls < budget * 0.65 ? 2 : 1;
        for (const replacement of proposals.slice(0, maxTry)) {
          if (calls - startCalls >= budget || calls >= CALL_LIMIT) break;
          const specs = cur.specs.slice();
          specs[i] = replacement;
          const trial = evaluate(cur.records, specs, cur.cfg, cur.nodeY);
          if (trial && envelopePasses(trial.r) &&
              trial.r.mass < cur.r.mass - 1e-6) {
            cur = trial;
            break;
          }
        }
      }
    }

    const materialOrder = cur.records.map((rec, i) => {
      const info = memberInfo(cur.r, rec.id);
      const u = info && finite(info.util) ? info.util : 1;
      return {
        i,
        u,
        mass: approximateMass(rec, cur.specs[i]),
        mode: String(info && info.mode || "").toLowerCase()
      };
    }).sort((a, b) => b.mass - a.mass);

    for (const item of materialOrder) {
      if (calls - startCalls >= budget || calls >= CALL_LIMIT) break;
      const spec = cur.specs[item.i];
      const mat = materialOf(spec);
      if (mat !== "S460" && mat !== "S690") continue;
      if (item.mode.indexOf("fatigue") >= 0) continue;
      if (item.u > (item.mode.indexOf("buckling") >= 0 ? 0.24 : 0.34)) continue;

      const sectionId = sectionIdOf(spec);
      if (!sectionId) continue;
      const specs = cur.specs.slice();
      specs[item.i] = "AL7075 CHS" + sectionId;

      const trial = evaluate(cur.records, specs, cur.cfg, cur.nodeY);
      if (trial && envelopePasses(trial.r) &&
          trial.r.mass < cur.r.mass - 1e-6) {
        cur = trial;
      }
    }

    return cur;
  }

  function removeLowForceMembers(start, budget) {
    if (!start || !envelopePasses(start.r) || budget <= 0) return start;
    const startCalls = calls;
    let cur = start;

    const order = cur.records.map(rec => {
      const info = memberInfo(cur.r, rec.id);
      const u = info && finite(info.util) ? info.util : 1;
      return {
        id: rec.id,
        u,
        mass: approximateMass(rec, cur.specs[
          cur.records.findIndex(x => x.id === rec.id)
        ])
      };
    }).filter(x => x.u < 0.30)
     .sort((a, b) => b.mass - a.mass);

    for (const item of order) {
      if (calls - startCalls >= budget || calls >= CALL_LIMIT) break;
      if (item.u >= 0.30) continue;

      const i = cur.records.findIndex(rec => rec.id === item.id);
      if (i < 0) continue;

      const records = cur.records.filter((_, j) => j !== i);
      const specs = cur.specs.filter((_, j) => j !== i);
      const trial = evaluate(records, specs, cur.cfg, cur.nodeY);
      if (trial && envelopePasses(trial.r) &&
          trial.r.mass < cur.r.mass - 1e-6) {
        cur = trial;
      }
    }
    return cur;
  }

  const seedConfigs = [
    { webCut: -1, altPlan: false },
    { webCut: 5, altPlan: false },
    { webCut: 6, altPlan: false },
    { webCut: -1, altPlan: true },
    { webCut: 6, altPlan: true }
  ];

  const candidates = [];
  const layouts = [];
  let baseState = null;
  let baseOut = null;

  for (const cfg of seedConfigs) {
    if (calls >= CALL_LIMIT) break;
    const state = makeState(cfg, false, false, 0, 0);
    const out = evaluateState(state);
    layouts.push({ cfg, out });
    if (out && usable(out.r)) candidates.push(out);
    if (cfg.webCut === -1 && !cfg.altPlan) {
      baseState = state;
      baseOut = out;
    }
  }

  const wireTrials = [
    { plan: true, cross: false, p: 16, c: 0 },
    { plan: true, cross: false, p: 24, c: 0 },
    { plan: false, cross: true, p: 0, c: 16 },
    { plan: false, cross: true, p: 0, c: 24 },
    { plan: true, cross: true, p: 16, c: 16 },
    { plan: true, cross: true, p: 24, c: 24 },
    { plan: true, cross: true, p: 32, c: 32 }
  ];

  const defaultCfg = { webCut: -1, altPlan: false };
  for (const w of wireTrials) {
    if (calls >= CALL_LIMIT) break;
    const state = makeState(defaultCfg, w.plan, w.cross, w.p, w.c);
    const out = evaluateState(state);
    if (out && usable(out.r)) candidates.push(out);
  }

  function hasPlanCable(state) {
    return state.records.some(m => m.role === "planCable");
  }

  function hasCrossCable(state) {
    return state.records.some(m => m.role === "crossCable");
  }

  function rank(out) {
    return out.r.mass + 1000 * Math.max(0, peakUtil(out.r) - TARGET_U);
  }

  function bestOf(list) {
    let best = null;
    for (const x of list) {
      if (!x || !usable(x.r)) continue;
      if (!best || rank(x) < rank(best)) best = x;
    }
    return best;
  }

  const shortlist = [];
  function addShort(x) {
    if (x && shortlist.indexOf(x) < 0) shortlist.push(x);
  }

  if (baseOut && usable(baseOut.r)) addShort(baseOut);

  for (const item of layouts) {
    if (!item.out || !usable(item.out.r)) continue;
    addShort(item.out);
  }

  addShort(bestOf(candidates.filter(x =>
    hasPlanCable(x) && !hasCrossCable(x)
  )));
  addShort(bestOf(candidates.filter(x =>
    hasCrossCable(x) && !hasPlanCable(x)
  )));
  addShort(bestOf(candidates.filter(x =>
    hasPlanCable(x) && hasCrossCable(x)
  )));
  addShort(bestOf(candidates));

  const hardened = [];
  for (const x of shortlist) {
    if (calls >= CALL_LIMIT) break;
    const h = harden(x, 6);
    if (h && envelopePasses(h.r)) hardened.push(h);
  }

  function cheapest(list) {
    let best = null;
    for (const x of list) {
      if (isBetter(x, best)) best = x;
    }
    return best;
  }

  const bestSolid = cheapest(hardened.filter(x =>
    !hasPlanCable(x) && !hasCrossCable(x)
  ));
  const bestWire = cheapest(hardened.filter(x =>
    hasPlanCable(x) || hasCrossCable(x)
  ));

  let fallback = baseOut && usable(baseOut.r) ? baseOut : null;
  if (!fallback) fallback = bestOf(candidates);

  let winner = cheapest(hardened);
  if (!winner) {
    return fallback ? makeDesign(fallback) : makeDesign(baseState);
  }

  const reserveForPruning = 20;
  const wireBudget = bestWire
    ? Math.min(24, Math.max(0, CALL_LIMIT - calls - reserveForPruning))
    : 0;
  const solidBudget = Math.max(
    0,
    Math.min(230, CALL_LIMIT - calls - reserveForPruning - wireBudget)
  );

  const optimizedSolid = bestSolid
    ? resizeState(bestSolid, solidBudget)
    : null;
  const optimizedWire = bestWire
    ? resizeState(bestWire, wireBudget)
    : null;

  if (isBetter(optimizedSolid, winner)) winner = optimizedSolid;
  if (isBetter(optimizedWire, winner)) winner = optimizedWire;

  const pruned = removeLowForceMembers(
    winner,
    Math.min(reserveForPruning, Math.max(0, CALL_LIMIT - calls))
  );
  if (isBetter(pruned, winner)) winner = pruned;

  return makeDesign(winner || fallback || baseState);
}

function design(site, analyse) {
  const note =
    "I kept the verified full-depth pinned trusses, hardened fatigue and buckling hot spots, then resized or substituted members only when conservative analysis margins remained.";

  const xs = [
    0, 4.918, 9.836, 14.755, 19.673, 24.591,
    29.509, 34.427, 39.345, 44.264, 49.182, 54.1
  ];
  const bottomY = -7.53;

  const chs = [
    ["33.7x2.6", 2.54], ["42.4x3.2", 3.94], ["48.3x3.2", 4.53],
    ["60.3x3.2", 5.74], ["60.3x4", 7.07], ["76.1x3.2", 7.33],
    ["76.1x4", 9.06], ["88.9x4", 10.67], ["88.9x5", 13.18],
    ["114.3x4", 13.86], ["114.3x5", 17.17], ["139.7x5", 21.16],
    ["168.3x5", 25.65], ["139.7x6.3", 26.4], ["168.3x6.3", 32.06],
    ["193.7x6.3", 37.09], ["193.7x8", 46.67], ["219.1x8", 53.06],
    ["244.5x8", 59.44], ["273x10", 82.62], ["323.9x10", 98.61],
    ["355.6x12.5", 134.74], ["406.4x12.5", 154.68],
    ["457x16", 221.67]
  ].map(x => ({ id: x[0], area: x[1] }));

  const areaById = Object.create(null);
  for (const s of chs) areaById[s.id] = s.area;

  const aliases = {
    S: "S460", H: "S690", A: "AL6082", B: "AL7075"
  };

  function parseSpecs(text) {
    return text.trim().split(/\s+/).map(token => {
      const p = token.split(":");
      return aliases[p[0]] + " CHS" + p[1];
    });
  }

  const upperL = parseSpecs(
    "S:193.7x8 S:168.3x5 S:193.7x6.3 S:219.1x8 S:244.5x8 S:244.5x8 " +
    "S:219.1x8 S:193.7x6.3 S:168.3x5 S:193.7x6.3 S:219.1x8"
  );
  const upperR = parseSpecs(
    "S:193.7x8 S:193.7x6.3 S:193.7x8 S:193.7x8 S:219.1x8 S:219.1x8 " +
    "S:193.7x8 S:193.7x6.3 S:168.3x5 S:168.3x6.3 S:219.1x8"
  );
  const lowerL = parseSpecs(
    "H:33.7x2.6 S:139.7x6.3 S:193.7x8 H:219.1x8 H:273x10 H:273x10 " +
    "H:273x10 H:273x10 H:219.1x8 S:193.7x8 S:139.7x6.3"
  );
  const lowerR = parseSpecs(
    "H:33.7x2.6 S:168.3x5 S:193.7x8 H:193.7x8 H:273x10 H:273x10 " +
    "H:273x10 H:244.5x8 H:193.7x8 H:193.7x6.3 S:168.3x5"
  );
  const webL = parseSpecs(
    "S:193.7x8 H:193.7x6.3 S:168.3x6.3 S:193.7x6.3 S:193.7x6.3 " +
    "S:168.3x6.3 S:244.5x8 S:273x10 S:273x10 H:273x10 S:323.9x10"
  );
  const webR = parseSpecs(
    "S:193.7x8 S:193.7x6.3 S:168.3x6.3 S:193.7x6.3 S:193.7x8 " +
    "S:323.9x10 S:244.5x8 S:273x10 S:273x10 S:273x10 S:323.9x10"
  );
  const topPlan = parseSpecs(
    "A:273x10 S:193.7x8 S:193.7x6.3 S:168.3x6.3 S:139.7x6.3 " +
    "B:139.7x5 S:139.7x5 S:168.3x6.3 S:193.7x6.3 S:193.7x6.3 S:193.7x8"
  );
  const verticalL = parseSpecs(
    "A:42.4x3.2 S:273x10 S:273x10 S:244.5x8 S:219.1x8 S:219.1x8 " +
    "S:139.7x5 S:168.3x6.3 S:168.3x6.3 S:139.7x6.3 S:168.3x6.3 S:193.7x6.3"
  );
  const verticalR = parseSpecs(
    "A:48.3x3.2 S:273x10 H:244.5x8 S:244.5x8 S:219.1x8 S:273x10 " +
    "S:168.3x6.3 S:193.7x6.3 S:168.3x6.3 S:139.7x6.3 S:168.3x6.3 S:193.7x6.3"
  );
  const topTie = parseSpecs(
    "A:88.9x5 S:193.7x6.3 A:219.1x8 S:168.3x6.3 S:139.7x6.3 S:114.3x5 " +
    "A:114.3x4 B:168.3x5 S:139.7x6.3 S:168.3x6.3 A:219.1x8 S:193.7x6.3"
  );
  const bottomTie = parseSpecs(
    "A:60.3x3.2 B:76.1x4 A:88.9x4 A:88.9x4 A:88.9x4 A:88.9x4 " +
    "A:88.9x4 A:88.9x4 A:88.9x4 A:88.9x4 A:88.9x4 B:76.1x4"
  );
  const crossDiag = parseSpecs(
    "S:88.9x4 S:114.3x5 S:139.7x5 S:114.3x5 S:114.3x5 B:139.7x5 " +
    "S:114.3x5 B:139.7x5 S:114.3x5 S:114.3x5 S:114.3x5 S:114.3x5"
  );

  function point(id) {
    const m = /^(BL|BR|L|R)(\d+)$/.exec(id);
    if (!m) return [0, 0, 0];
    const kind = m[1];
    const i = Number(m[2]);
    const bottom = kind === "BL" || kind === "BR";
    const left = kind === "L" || kind === "BL";
    return [xs[i], bottom ? bottomY : 0, left ? -4.35 : 4.35];
  }

  function lengthOf(a, b) {
    const p = point(a);
    const q = point(b);
    const dx = p[0] - q[0];
    const dy = p[1] - q[1];
    const dz = p[2] - q[2];
    return Math.sqrt(dx * dx + dy * dy + dz * dz);
  }

  const records = [];
  function add(a, b, role, i, initial) {
    records.push({
      a, b, role, i, initial,
      id: a + "-" + b,
      length: lengthOf(a, b)
    });
  }

  for (let i = 0; i < xs.length - 1; i++) {
    add("L" + i, "L" + (i + 1), "upper", i, upperL[i]);
    add("R" + i, "R" + (i + 1), "upper", i, upperR[i]);
    add("BL" + i, "BL" + (i + 1), "lower", i, lowerL[i]);
    add("BR" + i, "BR" + (i + 1), "lower", i, lowerR[i]);
    add("L" + i, "BL" + (i + 1), "web", i, webL[i]);
    add("R" + i, "BR" + (i + 1), "web", i, webR[i]);
    add("L" + i, "R" + (i + 1), "plan", i, topPlan[i]);
  }

  for (let i = 0; i < xs.length; i++) {
    add("L" + i, "BL" + i, "vertical", i, verticalL[i]);
    add("R" + i, "BR" + i, "vertical", i, verticalR[i]);
    add("L" + i, "R" + i, "topTie", i, topTie[i]);
    add("BL" + i, "BR" + i, "bottomTie", i, bottomTie[i]);

    if (i % 2 === 0) {
      add("L" + i, "BR" + i, "cross", i, crossDiag[i]);
    } else {
      add("R" + i, "BL" + i, "cross", i, crossDiag[i]);
    }
  }

  function makeNodes() {
    const nodes = [];
    for (let i = 0; i < xs.length; i++) {
      nodes.push({
        id: "BL" + i, x: xs[i], y: bottomY, z: -4.35, joint: "pin"
      });
      nodes.push({
        id: "BR" + i, x: xs[i], y: bottomY, z: 4.35, joint: "pin"
      });
    }
    return nodes;
  }

  function makeDesign(state) {
    return {
      note,
      nodes: makeNodes(),
      members: state.records.map((m, i) => [m.a, m.b, state.specs[i]])
    };
  }

  const density = {
    S235: 7850, S355: 7850, S460: 7850, S690: 7850,
    SS316: 8000, AL6082: 2700, AL7075: 2810
  };
  const fy = {
    S235: 235, S355: 355, S460: 460, S690: 690,
    SS316: 240, AL6082: 260, AL7075: 480
  };
  const fatigue = {
    S235: 90, S355: 90, S460: 90, S690: 50,
    SS316: 90, AL6082: 32, AL7075: 32
  };

  function finite(x) {
    return Number.isFinite(x);
  }

  function materialOf(spec) {
    const k = spec.indexOf(" ");
    return k < 0 ? spec : spec.slice(0, k);
  }

  function sectionIdOf(spec) {
    const k = spec.indexOf("CHS");
    return k < 0 ? null : spec.slice(k + 3);
  }

  function sectionIndex(spec) {
    const id = sectionIdOf(spec);
    return chs.findIndex(s => s.id === id);
  }

  function areaOf(spec) {
    return areaById[sectionIdOf(spec)];
  }

  function approximateMass(rec, spec) {
    const a = areaOf(spec);
    const rho = density[materialOf(spec)];
    if (!finite(a) || !finite(rho)) return 0;
    return rec.length * a * 1e-4 * rho;
  }

  function reverseId(id) {
    const p = String(id || "").split("-");
    return p.length === 2 ? p[1] + "-" + p[0] : null;
  }

  function memberInfo(state, id) {
    const list = state && state.r && state.r.members;
    if (!Array.isArray(list)) return null;
    const rev = reverseId(id);
    for (const m of list) {
      if (!m) continue;
      const mid = m.id || m.memberId || m.member || m.name;
      if (mid === id || mid === rev) return m;
    }
    return null;
  }

  function metric(r, a, b) {
    if (finite(r[a])) return r[a];
    if (b && finite(r[b])) return r[b];
    return null;
  }

  function peakUtil(r) {
    let p = finite(r.maxUtil) ? r.maxUtil : 0;
    if (Array.isArray(r.cases)) {
      for (const c of r.cases) {
        if (c && finite(c.maxUtil)) p = Math.max(p, c.maxUtil);
      }
    }
    if (Array.isArray(r.members)) {
      for (const m of r.members) {
        if (m && finite(m.util)) p = Math.max(p, m.util);
      }
    }
    return p;
  }

  function risk(r) {
    if (!r || r.ok !== true || r.robustness === false) return 1e8;
    if (r.robustness && typeof r.robustness === "object" &&
        (r.robustness.ok === false || r.robustness.pass === false)) {
      return 1e8;
    }

    let z = peakUtil(r) / 0.68;

    if (finite(r.fatigueWorst)) {
      z = Math.max(z, r.fatigueWorst / 0.68);
    }

    if (finite(r.sag) && finite(r.sagLimit) && r.sagLimit > 0) {
      z = Math.max(z, (r.sag / r.sagLimit) / 0.82);
    }
    if (finite(r.sway) && finite(r.swayLimit) && r.swayLimit > 0) {
      z = Math.max(z, (r.sway / r.swayLimit) / 0.82);
    }

    const cr = metric(r, "alpha_crMin", "alpha_cr");
    if (cr !== null) z = Math.max(z, 10 / Math.max(1e-6, cr));

    const f = metric(r, "frequency", "fMin");
    if (f !== null) z = Math.max(z, 1.35 / Math.max(1e-6, f));

    return z;
  }

  function hardScore(r) {
    let score = risk(r);
    if (!r || !Array.isArray(r.members)) return score;
    let excess = 0;
    for (const m of r.members) {
      if (!m || !finite(m.util)) continue;
      const e = Math.max(0, m.util / 0.68 - 1);
      excess += Math.min(3, e) * Math.min(3, e);
    }
    if (finite(r.fatigueWorst)) {
      const e = Math.max(0, r.fatigueWorst / 0.68 - 1);
      excess += e * e;
    }
    return score + 0.015 * excess;
  }

  function nominalPass(state) {
    return !!state && state.r && state.r.ok === true &&
      finite(state.r.mass) && risk(state.r) < 1e7;
  }

  function robustPass(state) {
    return nominalPass(state) && risk(state.r) <= 1.000001;
  }

  const CALL_LIMIT = 398;
  let calls = 0;

  function evaluate(specs, recs) {
    if (calls >= CALL_LIMIT) return null;
    const useRecords = recs || records;
    const state = {
      records: useRecords.slice(),
      specs: specs.slice(),
      r: null
    };
    calls++;
    try {
      state.r = analyse(makeDesign(state));
    } catch (e) {
      return null;
    }
    if (!state.r || state.r.error) return null;
    return state;
  }

  let bestHard = null;
  let bestRobust = null;

  function remember(state) {
    if (!nominalPass(state)) return;

    const hs = hardScore(state.r);
    if (!bestHard ||
        hs < hardScore(bestHard.r) - 1e-8 ||
        (Math.abs(hs - hardScore(bestHard.r)) <= 1e-8 &&
         state.r.mass < bestHard.r.mass)) {
      bestHard = state;
    }

    if (robustPass(state)) {
      if (!bestRobust ||
          state.r.mass < bestRobust.r.mass - 1e-6 ||
          (Math.abs(state.r.mass - bestRobust.r.mass) <= 1e-6 &&
           risk(state.r) < risk(bestRobust.r) - 1e-7)) {
        bestRobust = state;
      }
    }
  }

  const initialSpecs = records.map(m => m.initial);
  const baseline = evaluate(initialSpecs);
  if (!baseline) {
    return {
      note,
      nodes: makeNodes(),
      members: records.map(m => [m.a, m.b, m.initial])
    };
  }
  remember(baseline);

  function addUnique(list, spec, current) {
    if (spec && spec !== current && list.indexOf(spec) < 0) list.push(spec);
  }

  function makeAlSpecs(state, i) {
    const rec = state.records[i];
    const spec = state.specs[i];
    const mat = materialOf(spec);
    if (mat !== "S460" && mat !== "S690" &&
        mat !== "S355" && mat !== "S235") return [];

    const info = memberInfo(state, rec.id);
    if (!info) return [];
    const mode = String(info.mode || "").toLowerCase();
    if (mode.indexOf("buckling") >= 0 ||
        mode.indexOf("compression") >= 0) return [];
    if (mode.indexOf("fatigue") < 0 &&
        mode.indexOf("tension") < 0) return [];

    const tension = finite(info.tension) ? Math.max(0, info.tension) : 0;
    const compression = finite(info.compression)
      ? Math.max(0, info.compression) : 0;
    if (compression > Math.max(20, 0.15 * tension)) return [];

    const a = areaOf(spec);
    const u = finite(info.util) ? Math.max(0, info.util) : 0.5;
    const oldFy = fy[mat] || 460;
    const oldFatigue = fatigue[mat] || 90;

    let needed = tension > 0
      ? tension * 11 / (480 * 0.60)
      : a * Math.max(0.12, u) * oldFy / (480 * 0.60);

    if (mode.indexOf("fatigue") >= 0) {
      needed = Math.max(
        needed,
        a * u * oldFatigue / (32 * 0.66)
      );
    }

    let pos = chs.findIndex(s => s.area >= needed);
    if (pos < 0) return [];

    const choices = [];
    if (pos > 0) choices.push(pos - 1);
    choices.push(pos);

    const out = [];
    const oldCost = a * (density[mat] || 7850);
    for (const j of choices) {
      const newCost = chs[j].area * density.AL7075;
      if (newCost >= oldCost * 0.995) continue;
      addUnique(out, "AL7075 CHS" + chs[j].id, spec);
    }
    return out;
  }

  function hardIndices(state) {
    const rows = [];
    for (let i = 0; i < state.records.length; i++) {
      const info = memberInfo(state, state.records[i].id);
      if (info && finite(info.util)) {
        rows.push({ i, util: info.util });
      }
    }
    rows.sort((a, b) => b.util - a.util);

    const out = [];
    for (const x of rows.slice(0, 6)) out.push(x.i);

    function idFromGoverning(g) {
      if (typeof g === "string") return g;
      if (g && typeof g === "object") {
        return g.id || g.memberId || g.member || g.name || null;
      }
      return null;
    }

    if (Array.isArray(state.r.cases)) {
      const cases = state.r.cases.slice()
        .filter(c => c && finite(c.maxUtil))
        .sort((a, b) => b.maxUtil - a.maxUtil);
      for (const c of cases.slice(0, 4)) {
        const id = idFromGoverning(c.governing);
        if (!id) continue;
        const rev = reverseId(id);
        const i = state.records.findIndex(m => m.id === id || m.id === rev);
        if (i >= 0 && out.indexOf(i) < 0) out.push(i);
      }
    }
    return out;
  }

  function hardOptions(state, i) {
    const spec = state.specs[i];
    const mat = materialOf(spec);
    const modeInfo = memberInfo(state, state.records[i].id);
    const mode = String(modeInfo && modeInfo.mode || "").toLowerCase();
    const u = modeInfo && finite(modeInfo.util) ? modeInfo.util : 0;
    const k = sectionIndex(spec);
    const out = [];

    if (k >= 0 && k + 1 < chs.length) {
      addUnique(out, mat + " CHS" + chs[k + 1].id, spec);
    }
    if (k >= 0 && u > 0.72 && k + 2 < chs.length) {
      addUnique(out, mat + " CHS" + chs[k + 2].id, spec);
    }

    if (mat === "S690" && mode.indexOf("fatigue") >= 0) {
      addUnique(out, "S460 CHS" + sectionIdOf(spec), spec);
      if (k >= 0 && k + 1 < chs.length) {
        addUnique(out, "S460 CHS" + chs[k + 1].id, spec);
      }
    }

    if (mat === "S460" &&
        (mode.indexOf("buckling") >= 0 ||
         mode.indexOf("compression") >= 0 ||
         mode.indexOf("tension") >= 0)) {
      addUnique(out, "S690 CHS" + sectionIdOf(spec), spec);
    }

    if (mode.indexOf("fatigue") >= 0 ||
        mode.indexOf("tension") >= 0) {
      for (const s of makeAlSpecs(state, i).slice(0, 2)) {
        addUnique(out, s, spec);
      }
    }
    return out;
  }

  let cur = baseline;
  const hardEnd = Math.min(CALL_LIMIT - 1, calls + 110);

  for (let step = 0; step < 30 && calls < hardEnd; step++) {
    if (risk(cur.r) <= 1.000001) break;

    const oldScore = hardScore(cur.r);
    let winner = null;
    let winnerScore = oldScore;
    const picks = hardIndices(cur).slice(0, 5);

    for (const i of picks) {
      const options = hardOptions(cur, i).slice(0, 5);
      for (const replacement of options) {
        if (calls >= hardEnd) break;
        const specs = cur.specs.slice();
        specs[i] = replacement;
        const trial = evaluate(specs, cur.records);
        if (!trial || !nominalPass(trial)) continue;

        remember(trial);
        const score = hardScore(trial.r);
        if (score < winnerScore - 1e-8) {
          winner = trial;
          winnerScore = score;
        }
      }
      if (calls >= hardEnd) break;
    }

    if (!winner) break;
    cur = winner;
  }

  if (bestRobust) cur = bestRobust;

  function fatigueGradePass(start, budget) {
    let state = start;
    const startCalls = calls;
    const order = state.records.map((rec, i) => {
      const info = memberInfo(state, rec.id);
      return {
        id: rec.id,
        i,
        util: info && finite(info.util) ? info.util : 0,
        mode: String(info && info.mode || "").toLowerCase()
      };
    }).filter(x =>
      x.mode.indexOf("fatigue") >= 0 &&
      materialOf(state.specs[x.i]) === "S690"
    ).sort((a, b) => b.util - a.util);

    for (const item of order) {
      if (calls - startCalls >= budget || calls >= CALL_LIMIT) break;
      const i = state.records.findIndex(m => m.id === item.id);
      if (i < 0) continue;
      const spec = state.specs[i];
      const replacement = "S460 CHS" + sectionIdOf(spec);
      const specs = state.specs.slice();
      specs[i] = replacement;

      const trial = evaluate(specs, state.records);
      if (!trial || !robustPass(trial)) continue;
      if (trial.r.mass <= state.r.mass + 1e-6 &&
          risk(trial.r) < risk(state.r) - 1e-6) {
        state = trial;
        remember(state);
      }
    }
    return state;
  }

  function resizePass(start, budget) {
    let state = start;
    if (!robustPass(state) || budget <= 0) return state;

    const startCalls = calls;
    const order = state.records.map((rec, i) => {
      const info = memberInfo(state, rec.id);
      const u = info && finite(info.util) ? info.util : 0.45;
      const mass = approximateMass(rec, state.specs[i]);
      return {
        id: rec.id,
        priority: mass * Math.max(0.03, 1 - Math.min(0.98, u) / 0.78)
      };
    }).sort((a, b) => b.priority - a.priority);

    for (const item of order) {
      if (calls - startCalls >= budget || calls >= CALL_LIMIT) break;
      const i = state.records.findIndex(m => m.id === item.id);
      if (i < 0) continue;

      const spec = state.specs[i];
      const k = sectionIndex(spec);
      if (k <= 0) continue;

      const specs = state.specs.slice();
      specs[i] = materialOf(spec) + " CHS" + chs[k - 1].id;
      const trial = evaluate(specs, state.records);
      if (trial && robustPass(trial) &&
          trial.r.mass < state.r.mass - 1e-6) {
        state = trial;
        remember(state);
      }
    }
    return state;
  }

  function aluminiumPass(start, budget) {
    let state = start;
    if (!robustPass(state) || budget <= 0) return state;

    const startCalls = calls;
    const order = state.records.map((rec, i) => {
      const options = makeAlSpecs(state, i);
      if (options.length === 0) return null;
      const oldMass = approximateMass(rec, state.specs[i]);
      const newMass = Math.min.apply(null, options.map(s =>
        approximateMass(rec, s)
      ));
      return { id: rec.id, saving: oldMass - newMass };
    }).filter(x => x && x.saving > 0)
      .sort((a, b) => b.saving - a.saving);

    for (const item of order) {
      if (calls - startCalls >= budget || calls >= CALL_LIMIT) break;
      const i = state.records.findIndex(m => m.id === item.id);
      if (i < 0) continue;

      const options = makeAlSpecs(state, i);
      for (const replacement of options) {
        if (calls - startCalls >= budget || calls >= CALL_LIMIT) break;
        const specs = state.specs.slice();
        specs[i] = replacement;
        const trial = evaluate(specs, state.records);

        if (trial && robustPass(trial) &&
            trial.r.mass < state.r.mass - 1e-6) {
          state = trial;
          remember(state);
          break;
        }
      }
    }
    return state;
  }

  if (bestRobust && calls < CALL_LIMIT - 2) {
    cur = bestRobust;

    cur = fatigueGradePass(
      cur,
      Math.min(22, Math.max(0, CALL_LIMIT - calls - 2))
    );

    cur = resizePass(
      cur,
      Math.min(records.length, Math.max(0, CALL_LIMIT - calls - 2))
    );

    cur = aluminiumPass(
      cur,
      Math.min(100, Math.max(0, CALL_LIMIT - calls - 2))
    );

    cur = resizePass(
      cur,
      Math.max(0, CALL_LIMIT - calls - 2)
    );
  }

  const winner = bestRobust || bestHard || baseline;
  return makeDesign(winner);
}

function design(site, analyse) {
  const note =
    "I used maximum-depth twin side trusses with triangulated 3-D restraint, keeping only section and cable variants with conservative analysis margins.";

  const xs = [
    0, 4.918, 9.836, 14.755, 19.673, 24.591,
    29.509, 34.427, 39.345, 44.264, 49.182, 54.1
  ];
  const bottomY = -7.53;
  const limit = 398;

  const chs = [
    ["33.7x2.6", 2.54, 2.6], ["42.4x3.2", 3.94, 3.2],
    ["48.3x3.2", 4.53, 3.2], ["60.3x3.2", 5.74, 3.2],
    ["60.3x4", 7.07, 4], ["76.1x3.2", 7.33, 3.2],
    ["76.1x4", 9.06, 4], ["88.9x4", 10.67, 4],
    ["88.9x5", 13.18, 5], ["114.3x4", 13.86, 4],
    ["114.3x5", 17.17, 5], ["139.7x5", 21.16, 5],
    ["168.3x5", 25.65, 5], ["139.7x6.3", 26.4, 6.3],
    ["168.3x6.3", 32.06, 6.3], ["193.7x6.3", 37.09, 6.3],
    ["193.7x8", 46.67, 8], ["219.1x8", 53.06, 8],
    ["244.5x8", 59.44, 8], ["273x10", 82.62, 10],
    ["323.9x10", 98.61, 10], ["355.6x12.5", 134.74, 12.5],
    ["406.4x12.5", 154.68, 12.5], ["457x16", 221.67, 16]
  ].map(s => ({ id: s[0], area: s[1], wall: s[2] }));

  const areaById = Object.create(null);
  for (const s of chs) areaById[s.id] = s.area;

  const wireArea = {
    8: 0.30, 10: 0.47, 12: 0.68, 16: 1.21,
    20: 1.88, 24: 2.71, 32: 4.83, 40: 7.54
  };
  const density = {
    S235: 7850, S355: 7850, S460: 7850, S690: 7850,
    SS316: 8000, AL6082: 2700, AL7075: 2810,
    GL28: 420, WIRE: 7850
  };
  const fy = {
    S235: 235, S355: 355, S460: 460, S690: 690,
    SS316: 240, AL6082: 260, AL7075: 480
  };
  const fatigue = {
    S235: 90, S355: 90, S460: 90, S690: 50,
    SS316: 90, AL6082: 32, AL7075: 32
  };

  const aliases = { S: "S460", H: "S690", A: "AL6082", B: "AL7075" };
  function parseSpecs(text) {
    return text.trim().split(/\s+/).map(token => {
      const k = token.indexOf(":");
      return aliases[token.slice(0, k)] + " CHS" + token.slice(k + 1);
    });
  }

  const upperL = parseSpecs(
    "S:193.7x8 S:168.3x5 S:193.7x6.3 S:219.1x8 S:244.5x8 S:244.5x8 " +
    "S:219.1x8 S:193.7x6.3 S:168.3x5 S:193.7x6.3 S:219.1x8"
  );
  const upperR = parseSpecs(
    "S:193.7x8 S:193.7x6.3 S:193.7x8 S:193.7x8 S:219.1x8 S:219.1x8 " +
    "S:193.7x8 S:193.7x6.3 S:168.3x5 S:168.3x6.3 S:219.1x8"
  );
  const lowerL = parseSpecs(
    "H:33.7x2.6 S:139.7x6.3 S:193.7x8 H:219.1x8 H:273x10 H:273x10 " +
    "H:273x10 H:273x10 H:219.1x8 S:193.7x8 S:139.7x6.3"
  );
  const lowerR = parseSpecs(
    "H:33.7x2.6 S:168.3x5 S:193.7x8 H:193.7x8 H:273x10 H:273x10 " +
    "H:273x10 H:244.5x8 H:193.7x8 H:193.7x6.3 S:168.3x5"
  );
  const webL = parseSpecs(
    "S:193.7x8 H:193.7x6.3 S:168.3x6.3 S:193.7x6.3 S:193.7x6.3 " +
    "S:168.3x6.3 S:244.5x8 S:273x10 S:273x10 H:273x10 S:323.9x10"
  );
  const webR = parseSpecs(
    "S:193.7x8 S:193.7x6.3 S:168.3x6.3 S:193.7x6.3 S:193.7x8 " +
    "S:323.9x10 S:244.5x8 S:273x10 S:273x10 S:273x10 S:323.9x10"
  );
  const topPlan = parseSpecs(
    "A:273x10 S:193.7x8 S:193.7x6.3 S:168.3x6.3 S:139.7x6.3 " +
    "B:139.7x5 S:168.3x5 S:168.3x6.3 S:193.7x6.3 S:193.7x8 S:193.7x8"
  );
  const verticalL = parseSpecs(
    "A:42.4x3.2 S:273x10 S:273x10 S:244.5x8 S:219.1x8 S:219.1x8 " +
    "S:139.7x5 S:168.3x6.3 S:168.3x6.3 S:168.3x6.3 S:193.7x6.3 S:193.7x6.3"
  );
  const verticalR = parseSpecs(
    "A:48.3x3.2 S:273x10 H:244.5x8 S:244.5x8 S:219.1x8 S:273x10 " +
    "S:168.3x6.3 S:193.7x6.3 S:168.3x6.3 S:168.3x6.3 S:168.3x6.3 S:193.7x6.3"
  );
  const topTie = parseSpecs(
    "A:88.9x5 S:193.7x6.3 A:219.1x8 S:168.3x6.3 S:139.7x6.3 S:114.3x5 " +
    "A:114.3x4 B:168.3x5 S:139.7x6.3 S:168.3x6.3 A:219.1x8 S:193.7x6.3"
  );
  const bottomTie = parseSpecs(
    "A:60.3x3.2 B:76.1x4 A:88.9x4 A:88.9x4 A:88.9x4 A:88.9x4 " +
    "A:88.9x4 A:88.9x4 A:88.9x4 A:88.9x4 A:88.9x4 B:76.1x4"
  );
  const crossDiag = parseSpecs(
    "A:88.9x4 S:114.3x5 A:139.7x5 S:114.3x5 S:114.3x5 B:139.7x5 " +
    "S:114.3x5 B:139.7x5 S:114.3x5 S:114.3x5 S:114.3x5 S:114.3x5"
  );

  function finite(x) {
    return Number.isFinite(x);
  }

  function materialOf(spec) {
    const k = spec.indexOf(" ");
    return k < 0 ? spec : spec.slice(0, k);
  }

  function sectionIdOf(spec) {
    const k = spec.indexOf("CHS");
    return k < 0 ? null : spec.slice(k + 3);
  }

  function areaOf(spec) {
    const wm = /^WIRE WIRE(\d+)$/.exec(spec);
    if (wm) return wireArea[Number(wm[1])];
    return areaById[sectionIdOf(spec)];
  }

  function sectionIndex(spec) {
    const id = sectionIdOf(spec);
    return chs.findIndex(s => s.id === id);
  }

  function wallOf(spec) {
    const id = sectionIdOf(spec);
    const s = chs.find(x => x.id === id);
    return s ? s.wall : null;
  }

  function heavierSpec(a, b) {
    const aa = areaOf(a);
    const ab = areaOf(b);
    if (aa > ab + 1e-8) return a;
    if (ab > aa + 1e-8) return b;

    const ma = materialOf(a);
    const mb = materialOf(b);
    const aSteel = ma === "S235" || ma === "S355" || ma === "S460" || ma === "S690";
    const bSteel = mb === "S235" || mb === "S355" || mb === "S460" || mb === "S690";
    if (aSteel && !bSteel) return a;
    if (bSteel && !aSteel) return b;
    if (ma === "S460") return a;
    if (mb === "S460") return b;
    return a;
  }

  function pointMap(bottomXs) {
    const p = Object.create(null);
    for (let i = 0; i < xs.length; i++) {
      p["L" + i] = [xs[i], 0, -4.35];
      p["R" + i] = [xs[i], 0, 4.35];
    }
    for (let i = 0; i < bottomXs.length; i++) {
      p["BL" + i] = [bottomXs[i], bottomY, -4.35];
      p["BR" + i] = [bottomXs[i], bottomY, 4.35];
    }
    return p;
  }

  function makeBottomNodes(bottomXs) {
    const nodes = [];
    for (let i = 0; i < bottomXs.length; i++) {
      nodes.push({
        id: "BL" + i, x: bottomXs[i], y: bottomY, z: -4.35, joint: "pin"
      });
      nodes.push({
        id: "BR" + i, x: bottomXs[i], y: bottomY, z: 4.35, joint: "pin"
      });
    }
    return nodes;
  }

  function makeRecord(a, b, role, i, spec, points) {
    const p = points[a];
    const q = points[b];
    const dx = p[0] - q[0];
    const dy = p[1] - q[1];
    const dz = p[2] - q[2];
    return {
      a, b, role, i, initial: spec,
      id: a + "-" + b,
      length: Math.sqrt(dx * dx + dy * dy + dz * dz)
    };
  }

  function makeBase(cfg) {
    const points = pointMap(xs);
    const nodes = makeBottomNodes(xs);
    const records = [];

    function add(a, b, role, i, spec) {
      records.push(makeRecord(a, b, role, i, spec, points));
    }

    for (let i = 0; i < xs.length - 1; i++) {
      add("L" + i, "L" + (i + 1), "upperChord", i, upperL[i]);
      add("R" + i, "R" + (i + 1), "upperChord", i, upperR[i]);
      add("BL" + i, "BL" + (i + 1), "lowerChord", i, lowerL[i]);
      add("BR" + i, "BR" + (i + 1), "lowerChord", i, lowerR[i]);

      const reverse = cfg.webCut >= 0 && i >= cfg.webCut;
      if (reverse) {
        add("BL" + i, "L" + (i + 1), "web", i, webL[i]);
        add("BR" + i, "R" + (i + 1), "web", i, webR[i]);
      } else {
        add("L" + i, "BL" + (i + 1), "web", i, webL[i]);
        add("R" + i, "BR" + (i + 1), "web", i, webR[i]);
      }

      if (cfg.altPlan && i % 2 === 1) {
        add("R" + i, "L" + (i + 1), "topPlan", i, topPlan[i]);
      } else {
        add("L" + i, "R" + (i + 1), "topPlan", i, topPlan[i]);
      }
    }

    for (let i = 0; i < xs.length; i++) {
      add("L" + i, "BL" + i, "vertical", i, verticalL[i]);
      add("R" + i, "BR" + i, "vertical", i, verticalR[i]);
      add("L" + i, "R" + i, "topTie", i, topTie[i]);
      add("BL" + i, "BR" + i, "bottomTie", i, bottomTie[i]);

      if (i % 2 === 0) {
        add("L" + i, "BR" + i, "crossDiag", i, crossDiag[i]);
      } else {
        add("R" + i, "BL" + i, "crossDiag", i, crossDiag[i]);
      }
    }

    return {
      kind: "base",
      cfg,
      nodes,
      points,
      records,
      specs: records.map(m => m.initial)
    };
  }

  function makeWarren() {
    const mids = [];
    for (let i = 0; i < xs.length - 1; i++) {
      mids.push((xs[i] + xs[i + 1]) / 2);
    }

    const points = pointMap(mids);
    const nodes = makeBottomNodes(mids);
    const records = [];

    function add(a, b, role, i, spec) {
      records.push(makeRecord(a, b, role, i, spec, points));
    }

    for (let i = 0; i < xs.length - 1; i++) {
      add("L" + i, "L" + (i + 1), "upperChord", i, upperL[i]);
      add("R" + i, "R" + (i + 1), "upperChord", i, upperR[i]);

      const wl = heavierSpec(
        webL[i],
        heavierSpec(verticalL[i], verticalL[i + 1])
      );
      const wr = heavierSpec(
        webR[i],
        heavierSpec(verticalR[i], verticalR[i + 1])
      );
      add("L" + i, "BL" + i, "web", 2 * i, wl);
      add("L" + (i + 1), "BL" + i, "web", 2 * i + 1, wl);
      add("R" + i, "BR" + i, "web", 2 * i, wr);
      add("R" + (i + 1), "BR" + i, "web", 2 * i + 1, wr);

      if (i < xs.length - 2) {
        add("BL" + i, "BL" + (i + 1), "lowerChord", i,
          heavierSpec(lowerL[i], lowerL[i + 1]));
        add("BR" + i, "BR" + (i + 1), "lowerChord", i,
          heavierSpec(lowerR[i], lowerR[i + 1]));

        if (i % 2 === 0) {
          add("BL" + i, "BR" + (i + 1), "bottomPlan", i,
            heavierSpec(topPlan[i], topPlan[i + 1]));
        } else {
          add("BR" + i, "BL" + (i + 1), "bottomPlan", i,
            heavierSpec(topPlan[i], topPlan[i + 1]));
        }
      }

      if (i % 2 === 0) {
        add("L" + i, "R" + (i + 1), "topPlan", i, topPlan[i]);
      } else {
        add("R" + i, "L" + (i + 1), "topPlan", i, topPlan[i]);
      }
    }

    for (let i = 0; i < xs.length; i++) {
      add("L" + i, "R" + i, "topTie", i, topTie[i]);
    }
    for (let i = 0; i < mids.length; i++) {
      add("BL" + i, "BR" + i, "bottomTie", i,
        heavierSpec(bottomTie[i], bottomTie[i + 1]));
    }
    for (let i = 0; i < mids.length; i++) {
      if (i % 2 === 0) {
        add("L" + i, "BR" + i, "crossDiag", i,
          "S460 CHS139.7x5");
      } else {
        add("R" + i, "BL" + i, "crossDiag", i,
          "S460 CHS139.7x5");
      }
    }
    add("R11", "BL10", "crossDiag", 11, "S460 CHS139.7x5");

    return {
      kind: "warren",
      nodes,
      points,
      records,
      specs: records.map(m => m.initial)
    };
  }

  function oppositeCableEnds(m) {
    const i = m.i;
    if (m.role === "web") {
      const isLeft = m.a.charAt(0) === "L" || m.b.charAt(0) === "L";
      const top0 = (isLeft ? "L" : "R") + i;
      const top1 = (isLeft ? "L" : "R") + (i + 1);
      const bot0 = (isLeft ? "BL" : "BR") + i;
      const bot1 = (isLeft ? "BL" : "BR") + (i + 1);
      if (m.a === top0 || m.b === top0) return [bot0, top1];
      return [top0, bot1];
    }
    if (m.role === "topPlan") {
      if (m.a === "L" + i) {
        return ["R" + i, "L" + (i + 1)];
      }
      return ["L" + i, "R" + (i + 1)];
    }
    if (m.role === "crossDiag") {
      if (m.a === "L" + i) return ["R" + i, "BL" + i];
      return ["L" + i, "BR" + i];
    }
    return null;
  }

  function makeCableVariant(state, flags) {
    const records = state.records.slice();
    const specs = state.specs.slice();

    for (let i = 0; i < state.records.length; i++) {
      const m = state.records[i];
      const selected =
        (flags.web && m.role === "web") ||
        (flags.plan && m.role === "topPlan") ||
        (flags.cross && m.role === "crossDiag");
      if (!selected) continue;

      const ends = oppositeCableEnds(m);
      if (!ends || !state.points[ends[0]] || !state.points[ends[1]]) continue;
      const cable = makeRecord(
        ends[0], ends[1],
        m.role === "web" ? "webCable" :
          m.role === "topPlan" ? "planCable" : "crossCable",
        m.i, "WIRE WIRE40", state.points
      );
      records.push(cable);
      specs.push("WIRE WIRE40");
    }

    return {
      kind: "wire",
      cfg: state.cfg,
      flags,
      nodes: state.nodes,
      points: state.points,
      records,
      specs
    };
  }

  function makeDesign(state) {
    return {
      note,
      nodes: state.nodes.map(n => ({
        id: n.id, x: n.x, y: n.y, z: n.z, joint: n.joint
      })),
      members: state.records.map((m, i) => [m.a, m.b, state.specs[i]])
    };
  }

  let calls = 0;
  function evaluateState(src) {
    if (calls >= limit) return null;
    const state = {
      kind: src.kind,
      cfg: src.cfg,
      flags: src.flags,
      nodes: src.nodes,
      points: src.points,
      records: src.records,
      specs: src.specs.slice(),
      r: null
    };
    calls++;
    try {
      state.r = analyse(makeDesign(state));
    } catch (e) {
      return null;
    }
    if (!state.r || state.r.error) return null;
    return state;
  }

  function robustnessPasses(r) {
    if (r.robustness === false) return false;
    if (r.robustness && typeof r.robustness === "object" &&
        (r.robustness.ok === false || r.robustness.pass === false)) {
      return false;
    }
    return true;
  }

  function peakUtil(r) {
    let p = finite(r.maxUtil) ? r.maxUtil : 0;
    if (Array.isArray(r.cases)) {
      for (const c of r.cases) {
        if (c && finite(c.maxUtil)) p = Math.max(p, c.maxUtil);
      }
    }
    if (Array.isArray(r.members)) {
      for (const m of r.members) {
        if (m && finite(m.util)) p = Math.max(p, m.util);
      }
    }
    return p;
  }

  function metric(r, a, b) {
    if (finite(r[a])) return r[a];
    if (b && finite(r[b])) return r[b];
    return null;
  }

  function safe(r) {
    if (!r || r.ok !== true || !finite(r.mass) || !robustnessPasses(r)) {
      return false;
    }
    if (peakUtil(r) > 0.74 + 1e-6) return false;
    if (finite(r.fatigueWorst) && r.fatigueWorst > 0.82) return false;

    const cr = metric(r, "alpha_crMin", "alpha_cr");
    if (cr !== null && cr < 8) return false;

    const f = metric(r, "frequency", "fMin");
    if (f !== null && f < 1.30) return false;

    if (finite(r.sag) && finite(r.sagLimit) && r.sagLimit > 0 &&
        r.sag / r.sagLimit > 0.84) return false;
    if (finite(r.sway) && finite(r.swayLimit) && r.swayLimit > 0 &&
        r.sway / r.swayLimit > 0.84) return false;
    return true;
  }

  function reserveScore(r) {
    let v = peakUtil(r) / 0.74;
    if (finite(r.fatigueWorst)) {
      v = Math.max(v, r.fatigueWorst / 0.82);
    }
    const cr = metric(r, "alpha_crMin", "alpha_cr");
    if (cr !== null && cr > 0) v = Math.max(v, 8 / cr);
    const f = metric(r, "frequency", "fMin");
    if (f !== null && f > 0) v = Math.max(v, 1.30 / f);
    if (finite(r.sag) && finite(r.sagLimit) && r.sagLimit > 0) {
      v = Math.max(v, (r.sag / r.sagLimit) / 0.84);
    }
    if (finite(r.sway) && finite(r.swayLimit) && r.swayLimit > 0) {
      v = Math.max(v, (r.sway / r.swayLimit) / 0.84);
    }
    return v;
  }

  function isBetter(a, b) {
    if (!a || !safe(a.r)) return false;
    if (!b || !safe(b.r)) return true;
    if (a.r.mass < b.r.mass - 1e-6) return true;
    if (Math.abs(a.r.mass - b.r.mass) <= 1e-6) {
      return reserveScore(a.r) < reserveScore(b.r) - 1e-7;
    }
    return false;
  }

  function bestOf(list) {
    let best = null;
    for (const x of list) {
      if (isBetter(x, best)) best = x;
    }
    return best;
  }

  function reverseId(id) {
    if (typeof id !== "string") return null;
    const p = id.split("-");
    return p.length === 2 ? p[1] + "-" + p[0] : null;
  }

  function memberName(m) {
    return m && (m.id || m.memberId || m.member || m.name);
  }

  function memberInfo(state, id) {
    if (!state || !state.r || !Array.isArray(state.r.members)) return null;
    const rev = reverseId(id);
    for (const m of state.r.members) {
      const mid = memberName(m);
      if (mid === id || mid === rev) return m;
    }
    return null;
  }

  function approximateMass(rec, spec) {
    const a = areaOf(spec);
    const rho = density[materialOf(spec)];
    if (!finite(a) || !finite(rho)) return 0;
    return rec.length * a * 1e-4 * rho;
  }

  function resizeOptions(state, i) {
    const spec = state.specs[i];
    if (spec.indexOf("CHS") < 0) return [];
    const idx = sectionIndex(spec);
    if (idx <= 0) return [];

    const info = memberInfo(state, state.records[i].id);
    if (!info || !finite(info.util)) return [];
    const u = Math.max(0, info.util);
    const mode = String(info.mode || "").toLowerCase();
    const isBuckling =
      mode.indexOf("buckling") >= 0 ||
      mode.indexOf("compression") >= 0;
    const isFatigue = mode.indexOf("fatigue") >= 0;
    const target = isBuckling ? 0.60 : isFatigue ? 0.70 : 0.66;
    if (u >= target * 0.99) return [];

    let ratio = isBuckling
      ? Math.sqrt(Math.max(0.01, u / target))
      : u / target;
    ratio = Math.max(0.35, Math.min(0.96, ratio));
    const goal = chs[idx].area * ratio;
    const mat = materialOf(spec);
    const carbon =
      mat === "S235" || mat === "S355" || mat === "S460" || mat === "S690";

    function allowed(j) {
      return !carbon || chs[j].wall >= 4.0;
    }

    let pick = -1;
    for (let j = idx - 1; j >= 0; j--) {
      if (allowed(j) && chs[j].area <= goal + 1e-8) {
        pick = j;
        break;
      }
    }
    if (pick < 0) {
      for (let j = idx - 1; j >= 0; j--) {
        if (allowed(j)) {
          pick = j;
          break;
        }
      }
    }
    if (pick < 0) return [];

    const out = [mat + " CHS" + chs[pick].id];
    for (let j = pick + 1; j < idx; j++) {
      if (allowed(j)) {
        out.push(mat + " CHS" + chs[j].id);
        break;
      }
    }
    return out;
  }

  function resizePass(start, budget) {
    if (!start || !safe(start.r) || budget <= 0) return start;
    const startCalls = calls;
    let cur = start;

    for (let pass = 0; pass < 2 && calls - startCalls < budget; pass++) {
      const order = cur.records.map((rec, i) => {
        const info = memberInfo(cur, rec.id);
        const u = info && finite(info.util) ? info.util : 1;
        return {
          i,
          priority: approximateMass(rec, cur.specs[i]) *
            Math.max(0.03, 1 - Math.min(0.98, u) / 0.74)
        };
      }).sort((a, b) => b.priority - a.priority);

      for (const item of order) {
        if (calls - startCalls >= budget || calls >= limit) break;
        const opts = resizeOptions(cur, item.i);
        const tries = calls - startCalls < budget * 0.55 ? 2 : 1;

        for (const replacement of opts.slice(0, tries)) {
          if (calls - startCalls >= budget || calls >= limit) break;
          const specs = cur.specs.slice();
          specs[item.i] = replacement;
          const trial = evaluateState({
            kind: cur.kind, cfg: cur.cfg, flags: cur.flags,
            nodes: cur.nodes, points: cur.points,
            records: cur.records, specs
          });
          if (trial && safe(trial.r) &&
              trial.r.mass < cur.r.mass - 1e-6) {
            cur = trial;
            break;
          }
        }
      }
    }
    return cur;
  }

  function aluminiumOptions(state, i) {
    const spec = state.specs[i];
    const mat = materialOf(spec);
    if (mat !== "S235" && mat !== "S355" &&
        mat !== "S460" && mat !== "S690") return [];

    const info = memberInfo(state, state.records[i].id);
    if (!info) return [];
    const mode = String(info.mode || "").toLowerCase();
    const tension = finite(info.tension) ? Math.max(0, info.tension) : 0;
    const compression = finite(info.compression)
      ? Math.max(0, info.compression) : 0;
    if (compression > Math.max(20, 0.15 * tension)) return [];
    if (tension <= 0 && mode.indexOf("fatigue") < 0) return [];

    const a = areaOf(spec);
    const u = finite(info.util) ? Math.max(0, info.util) : 0.5;
    const oldFy = fy[mat] || 460;
    const oldFatigue = fatigue[mat] || 90;

    let need = tension > 0
      ? 11 * tension / (480 * 0.60)
      : a * Math.max(0.12, u) * oldFy / (480 * 0.60);

    if (mode.indexOf("fatigue") >= 0) {
      need = Math.max(
        need,
        a * u * oldFatigue / (32 * 0.66)
      );
    }

    let first = chs.findIndex(s => s.area >= need);
    if (first < 0) return [];

    const out = [];
    for (let j = first; j < chs.length && out.length < 2; j++) {
      const candidate = "AL7075 CHS" + chs[j].id;
      if (approximateMass(state.records[i], candidate) <
          approximateMass(state.records[i], spec) * 0.98) {
        out.push(candidate);
      }
    }
    return out;
  }

  function aluminiumPass(start, budget) {
    if (!start || !safe(start.r) || budget <= 0) return start;
    const startCalls = calls;
    let cur = start;

    const order = cur.records.map((rec, i) => {
      const opts = aluminiumOptions(cur, i);
      if (opts.length === 0) return null;
      const oldMass = approximateMass(rec, cur.specs[i]);
      const newMass = Math.min.apply(null, opts.map(s => approximateMass(rec, s)));
      return { i, saving: oldMass - newMass };
    }).filter(x => x && x.saving > 0)
      .sort((a, b) => b.saving - a.saving);

    for (const item of order) {
      if (calls - startCalls >= budget || calls >= limit) break;
      const opts = aluminiumOptions(cur, item.i);
      for (const replacement of opts) {
        if (calls - startCalls >= budget || calls >= limit) break;
        const specs = cur.specs.slice();
        specs[item.i] = replacement;
        const trial = evaluateState({
          kind: cur.kind, cfg: cur.cfg, flags: cur.flags,
          nodes: cur.nodes, points: cur.points,
          records: cur.records, specs
        });
        if (trial && safe(trial.r) &&
            trial.r.mass < cur.r.mass - 1e-6) {
          cur = trial;
          break;
        }
      }
    }
    return cur;
  }

  function fatigueGradePass(start, budget) {
    if (!start || !safe(start.r) || budget <= 0) return start;
    const startCalls = calls;
    let cur = start;

    const order = cur.records.map((rec, i) => {
      const info = memberInfo(cur, rec.id);
      return {
        i,
        u: info && finite(info.util) ? info.util : 0,
        mode: String(info && info.mode || "").toLowerCase()
      };
    }).filter(x =>
      x.mode.indexOf("fatigue") >= 0 &&
      materialOf(cur.specs[x.i]) === "S690"
    ).sort((a, b) => b.u - a.u);

    for (const item of order) {
      if (calls - startCalls >= budget || calls >= limit) break;
      const specs = cur.specs.slice();
      specs[item.i] = "S460 CHS" + sectionIdOf(specs[item.i]);

      const trial = evaluateState({
        kind: cur.kind, cfg: cur.cfg, flags: cur.flags,
        nodes: cur.nodes, points: cur.points,
        records: cur.records, specs
      });
      if (trial && safe(trial.r) &&
          trial.r.mass <= cur.r.mass + 1e-6 &&
          reserveScore(trial.r) < reserveScore(cur.r) - 1e-6) {
        cur = trial;
      }
    }
    return cur;
  }

  function optimize(start, budget) {
    if (!start || !safe(start.r) || budget <= 0) return start;
    const startCalls = calls;
    let cur = start;

    cur = fatigueGradePass(cur, Math.min(10, Math.floor(budget * 0.12)));
    cur = resizePass(cur, Math.floor(budget * 0.48));
    cur = aluminiumPass(cur, Math.floor(budget * 0.28));

    const remaining = Math.max(0, budget - (calls - startCalls));
    cur = resizePass(cur, remaining);
    return cur;
  }

  const defaultCfg = { webCut: -1, altPlan: false };
  let fallback = makeBase(defaultCfg);
  const first = evaluateState(fallback);
  if (first) fallback = first;

  const solidPool = [];
  if (first && safe(first.r)) solidPool.push(first);

  const configs = [
    { webCut: 5, altPlan: false },
    { webCut: 6, altPlan: false },
    { webCut: -1, altPlan: true },
    { webCut: 6, altPlan: true }
  ];

  for (const cfg of configs) {
    if (calls >= limit) break;
    const out = evaluateState(makeBase(cfg));
    if (out && safe(out.r)) solidPool.push(out);
  }

  const bestSolid = bestOf(solidPool);
  const cableSeed = bestSolid || (first && first.r ? first : null);
  const wirePool = [];

  if (cableSeed && calls < limit) {
    const variants = [
      { web: true, plan: false, cross: false },
      { web: false, plan: true, cross: false },
      { web: true, plan: true, cross: false }
    ];
    for (const flags of variants) {
      if (calls >= limit) break;
      const out = evaluateState(makeCableVariant(cableSeed, flags));
      if (out && safe(out.r)) wirePool.push(out);
    }
  }

  let warren = null;
  if (calls < limit) {
    const out = evaluateState(makeWarren());
    if (out && safe(out.r)) warren = out;
  }

  const bestWeb = bestOf(wirePool.filter(s =>
    s.flags && s.flags.web && !s.flags.plan
  ));
  const bestWebPlan = bestOf(wirePool.filter(s =>
    s.flags && s.flags.web && s.flags.plan
  ));
  const bestPlan = bestOf(wirePool.filter(s =>
    s.flags && !s.flags.web && s.flags.plan
  ));

  const starts = [];
  function addStart(s) {
    if (s && starts.indexOf(s) < 0) starts.push(s);
  }

  addStart(bestSolid);
  addStart(bestWeb);
  addStart(bestWebPlan);
  if (!bestWeb && !bestWebPlan) addStart(bestPlan);
  addStart(warren);

  let winner = bestOf(starts);
  if (!winner && first && safe(first.r)) winner = first;

  for (let i = 0; i < starts.length && calls < limit; i++) {
    const slots = starts.length - i;
    const budget = Math.floor((limit - calls) / slots);
    const trial = optimize(starts[i], budget);
    if (isBetter(trial, winner)) winner = trial;
  }

  return makeDesign(winner || fallback);
}

function design(site, analyse) {
  const xs = [0, 4.918, 9.836, 14.755, 19.673, 24.591, 29.509, 34.427, 39.345, 44.264, 49.182, 54.1];
  const H = 7.5;
  const halfW = 4.35;

  const nodes = [];
  for (let i = 0; i < xs.length; i++) {
    nodes.push({ id: "C" + i, x: xs[i], y: -H, z: 0, joint: "pin" });
  }

  const mem = [];
  function add(a, b, g) {
    mem.push({ a, b, g });
  }

  // Top longitudinal chords (deck edge beams)
  for (let i = 0; i < 11; i++) {
    const d = Math.min(i, 10 - i);
    add("L" + i, "L" + (i + 1), "top" + d);
    add("R" + i, "R" + (i + 1), "top" + d);
  }

  // Bottom central chord
  for (let i = 0; i < 11; i++) {
    const d = Math.min(i, 10 - i);
    add("C" + i, "C" + (i + 1), "bot" + d);
  }

  // Top cross beams
  for (let i = 0; i < 12; i++) {
    add("L" + i, "R" + i, "cross");
  }

  // Inclined transverse struts to the central lower chord
  for (let i = 0; i < 12; i++) {
    const d = Math.min(i, 11 - i);
    add("L" + i, "C" + i, "strut" + d);
    add("R" + i, "C" + i, "strut" + d);
  }

  // Side diagonals, Warren-like, with both end bottom nodes anchored
  for (let i = 0; i < 11; i++) {
    const g = "diag" + Math.min(i, 10 - i);
    if (i === 10) {
      add("L10", "C11", g);
      add("R10", "C11", g);
    } else if (i % 2 === 0) {
      add("L" + (i + 1), "C" + i, g);
      add("R" + (i + 1), "C" + i, g);
    } else {
      add("L" + i, "C" + (i + 1), g);
      add("R" + i, "C" + (i + 1), g);
    }
  }

  // Top-plan bracing between deck lines
  for (let i = 0; i < 11; i++) {
    if (i % 2 === 0) {
      add("L" + i, "R" + (i + 1), "plan");
    } else {
      add("R" + i, "L" + (i + 1), "plan");
    }
  }

  const specs = [
    "S690 CHS48.3x3.2",
    "S690 CHS60.3x4",
    "S690 CHS76.1x4",
    "S690 CHS88.9x4",
    "S690 CHS88.9x5",
    "S690 CHS114.3x4",
    "S690 CHS114.3x5",
    "S690 CHS139.7x5",
    "S690 CHS168.3x5",
    "S690 CHS139.7x6.3",
    "S690 CHS168.3x6.3",
    "S690 CHS193.7x6.3",
    "S690 CHS193.7x8",
    "S690 CHS219.1x8",
    "S690 CHS244.5x8",
    "S690 CHS273x10",
    "S690 CHS323.9x10",
    "S690 CHS355.6x12.5",
    "S690 CHS406.4x12.5",
    "S690 CHS457x16"
  ];

  const groups = Array.from(new Set(mem.map(m => m.g)));

  function copyMap(m) {
    const o = {};
    for (const g of groups) o[g] = m[g];
    return o;
  }

  function build(assign) {
    return {
      note: "S690 triangular under-deck space truss with central lower chord and top-plan bracing.",
      nodes: nodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: n.joint })),
      members: mem.map(m => [m.a, m.b, assign[m.g]])
    };
  }

  let calls = 0;
  const cache = new Map();

  function evaluate(assign) {
    const key = groups.map(g => assign[g]).join("|");
    if (cache.has(key)) return cache.get(key);
    if (calls >= 400) return null;
    calls++;
    const d = build(assign);
    const r = analyse(d);
    cache.set(key, r);
    return r;
  }

  function acceptable(r) {
    if (!r || r.error || r.ok !== true) return false;

    const util = Number(r.maxUtil);
    if (isFinite(util) && util > 0.60) return false;

    const fat = Number(r.fatigueWorst);
    if (isFinite(fat) && fat > 0.65) return false;

    const acr = Number(r.alphaCr);
    if (isFinite(acr) && acr > 0 && acr < 7.5) return false;

    const f = Number(r.frequency);
    if (isFinite(f) && f > 0 && f < 1.35) return false;

    if (r.sagLimit && r.sag && Number(r.sag) > 0.80 * Number(r.sagLimit)) return false;
    if (r.swayLimit && r.sway && Number(r.sway) > 0.80 * Number(r.swayLimit)) return false;

    if (r.robustness === false) return false;
    if (r.robustness && typeof r.robustness === "object" && r.robustness.ok === false) return false;

    return true;
  }

  let bestSafeMap = null;
  let bestSafeMass = Infinity;
  let bestSafeRes = null;

  let bestAnyMap = null;
  let bestAnyMass = Infinity;
  let bestAnyRes = null;

  function run(assign) {
    const r = evaluate(assign);
    if (r && r.ok === true) {
      const mass = Number(r.mass);
      const mm = isFinite(mass) ? mass : Infinity;
      if (mm < bestAnyMass) {
        bestAnyMass = mm;
        bestAnyMap = copyMap(assign);
        bestAnyRes = r;
      }
      if (acceptable(r) && mm < bestSafeMass) {
        bestSafeMass = mm;
        bestSafeMap = copyMap(assign);
        bestSafeRes = r;
      }
    }
    return r;
  }

  const initMap = {};
  const maxSpec = specs[specs.length - 1];
  for (const g of groups) initMap[g] = maxSpec;

  run(initMap);

  // Coordinate descent using binary search on the sorted section list.
  for (let pass = 0; pass < 3 && calls < 395; pass++) {
    let changed = false;

    for (const g of groups) {
      if (calls >= 395) break;

      const current = initMap[g] ? initMap[g] : maxSpec;
      let localCurrent = current;
      // Use the actual evolving map, not initMap.  Keep a local copy only for fallback.
      localCurrent = bestSafeMap && bestSafeMap[g] ? bestSafeMap[g] : (initMap ? initMap[g] : maxSpec);

      // The map is initialized below if absent.
      if (!globalThis.__dummyKardashevMap) {
        // no-op; kept deliberately simple
      }

      // Ensure the evolving map exists.
      if (typeof design._map === "undefined") {
        design._map = copyMap(initMap);
      }
      const map = design._map;

      const old = map[g];

      let lo = 0;
      let hi = specs.length - 1;
      let best = -1;
      let bestResLocal = null;

      while (lo <= hi && calls < 395) {
        const mid = (lo + hi) >> 1;
        map[g] = specs[mid];
        const r = run(map);
        if (acceptable(r)) {
          best = mid;
          bestResLocal = r;
          hi = mid - 1;
        } else {
          lo = mid + 1;
        }
      }

      if (best >= 0) {
        map[g] = specs[best];
        if (specs[best] !== old) changed = true;
      } else {
        map[g] = old;
      }
    }

    if (!changed) break;
  }

  let chosenMap = bestSafeMap || bestAnyMap || initMap;
  let chosenRes = bestSafeMap ? bestSafeRes : (bestAnyMap ? bestAnyRes : null);

  const out = build(chosenMap);
  const approxMass = chosenRes && chosenRes.mass ? Math.round(Number(chosenRes.mass)) : 0;
  out.note = "S690 triangular under-deck space truss with a central lower chord and top-plan bracing; nominal mass approx " + approxMass + " kg.";
  return out;
}

