    ["B10","L11","S690 CHS193.7x6.3"],["B10","R11","S690 CHS193.7x6.3"]
  ];

  function baseDesign() {
    return {
      note: "attempt-4 Warren spine plus mixed S690/AL7075 member resizing",
      nodes: bNodes.map(n => ({id:n.id, x:n.x, y:n.y, z:n.z, joint:n.joint})),
      members: baseMembers.map(m => [m[0], m[1], m[2]])
    };
  }

  const s690Sorted = CHS.map(p => "S690 " + p[0]).sort((a,b) => areaOf(a) - areaOf(b));
  const alSorted = CHS.map(p => "AL7075 " + p[0]).sort((a,b) => areaOf(a) - areaOf(b));

  function cloneDesign(d) {
    return {
      note: d.note,
      nodes: d.nodes.map(n => ({id:n.id, x:n.x, y:n.y, z:n.z, joint:n.joint})),
      members: d.members.map(m => [m[0], m[1], m[2]])
    };
  }

  function memberLength(m) {
    const a = coord[m[0]], b = coord[m[1]];
    if (!a || !b) return 1;
    const dx = a.x - b.x, dy = a.y - b.y, dz = a.z - b.z;
    return Math.sqrt(dx*dx + dy*dy + dz*dz);
  }
  function memberMass(m) {
    return massPerM(m[2]) * memberLength(m);
  }

  function keyOf(d) {
    let s = "";
    for (let i = 0; i < d.members.length; i++) {
      const m = d.members[i];
      s += m[0] + "|" + m[1] + "|" + m[2] + ";";
    }
    return s;
  }

  function evalD(d) {
    const key = keyOf(d);
    if (cache.has(key)) return cache.get(key);
    if (calls >= LIMIT) return null;
    let r;
    try { r = analyse(d); } catch (e) { r = {error:String(e)}; }
    calls++;
    cache.set(key, r);
    return r;
  }

  function safe(r, strict) {
    if (!r || r.error || r.ok !== true) return false;
    const mu = Number(r.maxUtil);
    if (!isFinite(mu) || mu > 0.785) return false;
    const fat = Number(r.fatigueWorst);
    if (isFinite(fat) && fat > 0.80) return false;
    const ac = Number(r.alphaCr);
    if (isFinite(ac) && ac > 0 && ac < (strict ? 10.0 : 7.0)) return false;
    const fr = Number(r.frequency);
    if (isFinite(fr) && fr > 0 && fr < (strict ? 1.35 : 1.28)) return false;
    if (r.sagLimit && r.sag && Number(r.sag) > 0.90 * Number(r.sagLimit)) return false;
    if (r.swayLimit && r.sway && Number(r.sway) > 0.90 * Number(r.swayLimit)) return false;
    if (r.robustness === false) return false;
    if (r.robustness && typeof r.robustness === "object" && r.robustness.ok === false) return false;
