  let current = baseDesign();
  let currentRes = evalD(current);
  let fallback = cloneDesign(current);
  let bestDesign = null;
  let bestRes = null;
  let bestMass = Infinity;

  function consider(d, r) {
    if (!r || !safe(r)) return;
    const m = Number(r.mass);
    if (!isFinite(m)) return;
    if (m < bestMass - 1e-6) {
      bestMass = m;
      bestDesign = cloneDesign(d);
      bestRes = r;
    }
  }

  consider(current, currentRes);

  function evaluateSpec(idx, spec) {
    const old = current.members[idx][2];
    if (old === spec) return currentRes;
    current.members[idx][2] = spec;
    const r = evalD(current);
    current.members[idx][2] = old;
    return r;
  }

  function optimizeIndex(idx) {
    const m0 = current.members[idx];
    if (!m0) return false;
    const oldSpec = m0[2];
    const oldMass = memberMass(m0);
    const L = memberLength(m0);
    let bestSpec = null;
    let bestR = null;
    let bestM = oldMass;

    function search(list) {
      if (!list.length) return;
      let lo = 0, hi = list.length - 1, found = -1, foundR = null;
      while (lo <= hi && calls < LIMIT - 5) {
        const mid = (lo + hi) >> 1;
        const spec = list[mid];
        const r = evaluateSpec(idx, spec);
        if (r && safe(r)) {
          found = mid;
          foundR = r;
          hi = mid - 1;
        } else {
          lo = mid + 1;
        }
      }
      if (found >= 0) {
        const spec = list[found];
        const mm = massPerM(spec) * L;
        if (mm < bestM - 1e-4) {
          bestM = mm;
          bestSpec = spec;
          bestR = foundR;
        }
      }
    }

    const sList = s690Sorted.filter(s => massPerM(s) * L < oldMass - 1e-4);
    const aList = alSorted.filter(s => massPerM(s) * L < oldMass - 1e-4);
    search(sList);
    search(aList);

    if (bestSpec) {
      current.members[idx][2] = bestSpec;
      currentRes = bestR;
      consider(current, currentRes);
      return true;
    }
    return false;
  }

  function removeLoop(maxRemovals) {
    let removed = 0;
    while (removed < maxRemovals && calls < LIMIT - 80 && currentRes && currentRes.members) {
      let cand = [];
      for (let i = 0; i < current.members.length; i++) {
        const info = currentRes.members[i] || {};
        const util = Number(info.util);
        if (!isFinite(util) || util > 0.32) continue;
        const mass = memberMass(current.members[i]);
        if (mass < 7) continue;
        let score = mass * (0.5 - Math.min(util, 0.32));
        const mode = String(info.mode || "");
        if (mode.indexOf("fat") >= 0) score *= 0.25;
        cand.push({i, score});
      }
      if (!cand.length) break;
      cand.sort((a,b) => b.score - a.score);
      let did = false;
      for (const c of cand) {
        if (calls >= LIMIT - 80) break;
        const trial = cloneDesign(current);
        trial.members.splice(c.i, 1);
        const r = evalD(trial);
        if (r && safe(r, true)) {
          current = trial;
          currentRes = r;
          consider(current, currentRes);
          removed++;
          did = true;
          break;
        }
      }
      if (!did) break;
    }
  }

