    let arr = [];
    for (let i = 0; i < current.members.length; i++) {
      const info = (currentRes && currentRes.members && currentRes.members[i]) || {};
      const mass = memberMass(current.members[i]);
      if (mass < 2) continue;
      const util = Number(info.util);
      const u = isFinite(util) ? Math.min(Math.max(util, 0), 0.95) : 0.5;
      const comp = Math.max(0, Number(info.compression) || 0);
      const ten = Math.max(0, Number(info.tension) || 0);
      const mode = String(info.mode || "");
      let score = mass * (1 - u);
      if (comp > 0 && comp > ten * 0.9) {
        score += mass * 0.9 * (comp / (comp + ten + 1));
      }
      if (mode.indexOf("buckl") >= 0 || mode.indexOf("compress") >= 0) {
        score += mass * 0.8;
      }
      if (mode.indexOf("fat") >= 0) {
        score *= 0.25;
      }
      score += mass * 0.03;
      arr.push({i, score});
    }
    arr.sort((a,b) => b.score - a.score);
    return arr.map(o => o.i);
  }

  removeLoop(8);

  let order = candidateOrder();
  const selected = order.slice(0, Math.min(32, order.length));
  for (let k = 0; k < selected.length; k++) {
    if (calls >= LIMIT - 25) break;
    optimizeIndex(selected[k]);
  }

  removeLoop(5);

  if (calls < LIMIT - 8) {
    let order2 = candidateOrder();
    const n2 = Math.min(10, order2.length);
    for (let k = 0; k < n2; k++) {
      if (calls >= LIMIT - 5) break;
      optimizeIndex(order2[k]);
    }
  }

  if (calls < LIMIT - 3) {
    let order3 = candidateOrder();
    for (let k = 0; k < order3.length; k++) {
      if (calls >= LIMIT - 3) break;
      optimizeIndex(order3[k]);
    }
  }

  if (bestDesign) {
    bestDesign.note = "Mix S690 and AL7075 CHS in the proven mid-panel Warren spine; greedily resized/removed low-utilisation members with conservative stiffness, buckling and fatigue margins.";
    return bestDesign;
  }
  return fallback;
}

