  let bestStrict = null, bestStrictR = null, bestStrictMass = Infinity;
  let bestRelaxed = null, bestRelaxedR = null, bestRelaxedMass = Infinity;
  function consider(d, r) {
    if (!r || !safe(r, false)) return;
    const m = Number(r.mass);
    if (safe(r, true)) {
      if (isFinite(m) && m < bestStrictMass) {
        bestStrictMass = m;
        bestStrict = cloneDesign(d);
        bestStrictR = r;
      }
    }
    if (isFinite(m) && m < bestRelaxedMass) {
      bestRelaxedMass = m;
      bestRelaxed = cloneDesign(d);
      bestRelaxedR = r;
    }
  }

  let current = cloneDesign(baseline);
  let currentR = evalD(current);
  consider(current, currentR);

  const groups = {};
  for (let i = 0; i < current.members.length; i++) {
    const [a, b] = current.members[i];
    const isB = s => s[0] === 'B';
    const isDeck = s => s[0] === 'L' || s[0] === 'R';
    if (isB(a) && isB(b)) {
      groups.lower = (groups.lower || []).concat(i);
    } else if (isB(a) || isB(b)) {
      groups.web = (groups.web || []).concat(i);
      const deckNode = isB(a) ? b : a;
      if (deckNode[0] === 'L') groups.webL = (groups.webL || []).concat(i);
      else groups.webR = (groups.webR || []).concat(i);
    } else {
      const ida = parseInt(a.slice(1));
      const idb = parseInt(b.slice(1));
      if (a[0] === b[0]) {
        groups.topchord = (groups.topchord || []).concat(i);
      } else if (ida === idb) {
        groups.cross = (groups.cross || []).concat(i);
      } else {
        groups.topdiag = (groups.topdiag || []).concat(i);
      }
    }
  }
  groups.all = Array.from({length: current.members.length}, (_, i) => i);
  groups.chords = (groups.lower || []).concat(groups.topchord || [], groups.cross || [], groups.topdiag || []);

  groups.lowerEnd = [];
  groups.lowerMid = [];
  if (groups.lower) {
    for (let i of groups.lower) {
      const [a, b] = current.members[i];
      const ia = parseInt(a.slice(1));
      const ib = parseInt(b.slice(1));
      const minIdx = Math.min(ia, ib);
      if (minIdx <= 1 || minIdx >= 8) groups.lowerEnd.push(i);
      else groups.lowerMid.push(i);
    }
  }

  function scaleGroup(d, indices, factor) {
    const nd = cloneDesign(d);
    for (let idx of indices) {
      const oldSpec = nd.members[idx][2];
      const oldMass = massOf(oldSpec);
      const target = oldMass * factor;
      let chosen = null;
      for (let c of ALL) {
        if (c.mass <= target + 1e-9) chosen = c;
        else break;
      }
      if (!chosen) chosen = ALL[0];
      if (chosen.mass < oldMass - 1e-6) {
        nd.members[idx][2] = chosen.mat + " " + chosen.id;
      }
    }
    return nd;
  }

  let curStrict = cloneDesign(baseline);
  let rStrict = currentR;
  let curRelax = cloneDesign(baseline);
  let rRelax = currentR;

  const groupOrder = ["lowerEnd","lowerMid","webL","webR","topchord","cross","topdiag","lower","web","chords","all"];
  const factors = [0.8, 0.6, 0.4];

  for (let pass = 0; pass < 2; pass++) {
    let changed = false;
    for (let gname of groupOrder) {
      const idxs = groups[gname];
      if (!idxs || idxs.length === 0) continue;
      let bestTrial = null, bestR = null, bestM = Infinity;
      for (let f of factors) {
        if (calls >= 340) break;
        const trial = scaleGroup(curStrict, idxs, f);
        const r = evalD(trial);
        if (r && safe(r, true)) {
          const m = Number(r.mass);
          if (isFinite(m) && m < bestM) {
            bestM = m; bestTrial = trial; bestR = r;
          }
        }
      }
      if (bestTrial && bestM < Number(rStrict.mass) - 1e-6) {
        curStrict = bestTrial;
        rStrict = bestR;
        changed = true;
        consider(curStrict, rStrict);
      }
    }
    if (!changed) break;
  }

  curRelax = cloneDesign(curStrict);
  rRelax = evalD(curRelax);
  if (!rRelax || !safe(rRelax, false)) {
    curRelax = cloneDesign(baseline);
    rRelax = currentR;
  }

  for (let pass = 0; pass < 2; pass++) {
    let changed = false;
    for (let gname of groupOrder) {
      const idxs = groups[gname];
      if (!idxs || idxs.length === 0) continue;
      let bestTrial = null, bestR = null, bestM = Infinity;
      for (let f of factors) {
        if (calls >= 360) break;
        const trial = scaleGroup(curRelax, idxs, f);
        const r = evalD(trial);
        if (r && safe(r, false)) {
          const m = Number(r.mass);
          if (isFinite(m) && m < bestM) {
            bestM = m; bestTrial = trial; bestR = r;
          }
        }
      }
      if (bestTrial && bestM < Number(rRelax.mass) - 1e-6) {
        curRelax = bestTrial;
        rRelax = bestR;
        changed = true;
        consider(curRelax, rRelax);
      }
    }
    if (!changed) break;
  }

  function repairDesign(d, r) {
    let cur = cloneDesign(d);
    let rr = r;
    for (let iter = 0; iter < 15; iter++) {
      if (!rr || safe(rr, true)) return {d: cur, r: rr};
      if (calls >= 385) break;
      let worstIdx = -1, worstUtil = -1;
      if (rr.members) {
        for (let i = 0; i < rr.members.length; i++) {
          const mi = rr.members[i];
          if (!mi) continue;
          const u = Number(mi.util);
          if (isFinite(u) && u > worstUtil) {
            worstUtil = u;
            worstIdx = i;
          }
        }
      }
      if (worstIdx < 0) break;
      const oldSpec = cur.members[worstIdx][2];
      const oldMass = massOf(oldSpec);
      const heavier = ALL.filter(c => c.mass > oldMass + 1e-9).sort((a, b) => a.mass - b.mass);
      let upgraded = false;
      for (let c of heavier) {
        if (calls >= 385) break;
        const trial = cloneDesign(cur);
        trial.members[worstIdx][2] = c.mat + " " + c.id;
        const nr = evalD(trial);
        if (nr && nr.ok === true) {
          cur = trial;
          rr = nr;
          upgraded = true;
          break;
        }
      }
      if (!upgraded) break;
    }
    return {d: cur, r: rr};
  }

  if (bestRelaxed && bestRelaxedMass < bestStrictMass - 1e-6 && calls < 380) {
    const rep = repairDesign(bestRelaxed, bestRelaxedR);
    if (rep.r && safe(rep.r, true)) {
      consider(rep.d, rep.r);
    }
  }

  let optDesign = bestStrict ? cloneDesign(bestStrict) : cloneDesign(baseline);
  let optR = bestStrictR || currentR;
  if (!optR || !safe(optR, true)) {
    optDesign = cloneDesign(baseline);
    optR = currentR;
  }

  function memberPotential(idx) {
    const m = optDesign.members[idx];
    const curMass = massOf(m[2]) * lengthOfMember(m);
    const minMass = ALL[0].mass * lengthOfMember(m);
    return curMass - minMass;
  }

  let order = [];
  for (let i = 0; i < optDesign.members.length; i++) order.push(i);
  order.sort((i, j) => {
    let ui = 0.5, uj = 0.5;
    if (optR && optR.members) {
      const mi = optR.members[i];
      if (mi && isFinite(Number(mi.util))) ui = Number(mi.util);
      const mj = optR.members[j];
      if (mj && isFinite(Number(mj.util))) uj = Number(mj.util);
    }
    const scoreI = memberPotential(i) * (1.2 - Math.min(ui, 0.8));
    const scoreJ = memberPotential(j) * (1.2 - Math.min(uj, 0.8));
