  });

  function optimizeIndex(idx, levelStrict) {
    const oldSpec = optDesign.members[idx][2];
    const oldMassPerM = massOf(oldSpec);
    const L = lengthOfMember(optDesign.members[idx]);
    const oldMass = oldMassPerM * L;
    const cands = ALL.filter(c => c.mass < oldMassPerM - 1e-9);
    if (cands.length === 0) return false;
    let lo = 0, hi = cands.length - 1, best = -1, bestR = null;
    while (lo <= hi && calls < 390) {
      const mid = (lo + hi) >> 1;
      const c = cands[mid];
      const trial = cloneDesign(optDesign);
      trial.members[idx][2] = c.mat + " " + c.id;
      const r = evalD(trial);
      if (r && safe(r, levelStrict)) {
        best = mid;
        bestR = r;
        hi = mid - 1;
      } else {
        lo = mid + 1;
      }
    }
    if (best >= 0) {
      const c = cands[best];
      optDesign.members[idx][2] = c.mat + " " + c.id;
      optR = bestR;
      consider(optDesign, optR);
      return true;
    }
    return false;
  }

  const maxOpt = Math.min(35, order.length);
  for (let k = 0; k < maxOpt; k++) {
    if (calls >= 390) break;
    const idx = order[k];
    optimizeIndex(idx, true);
  }

  if (optR && optR.members) {
    for (let pass = 0; pass < 2; pass++) {
      if (calls >= 392) break;
      let removed = false;
      let remCands = [];
      for (let i = 0; i < optDesign.members.length; i++) {
        const mi = optR.members[i];
        if (!mi) continue;
        const util = Number(mi.util);
        if (!isFinite(util) || util > 0.30) continue;
        const mass = massOf(optDesign.members[i][2]) * lengthOfMember(optDesign.members[i]);
        if (mass < 5) continue;
        remCands.push({i, mass, util});
      }
      remCands.sort((a, b) => b.mass - a.mass);
      for (let cand of remCands) {
        if (calls >= 392) break;
        const trial = cloneDesign(optDesign);
        trial.members.splice(cand.i, 1);
        const r = evalD(trial);
        if (r && safe(r, true)) {
          optDesign = trial;
          optR = r;
          consider(optDesign, optR);
          removed = true;
          break;
        }
      }
      if (!removed) break;
    }
  }

  if (calls < 395) {
    for (let k = maxOpt; k < Math.min(order.length, maxOpt + 15); k++) {
      if (calls >= 395) break;
      optimizeIndex(order[k], true);
    }
  }

  if (bestStrict && calls < 398) {
    let cur = cloneDesign(bestStrict);
    let rr = bestStrictR;
    for (let gname of groupOrder) {
      if (calls >= 398) break;
      const idxs = groups[gname];
      if (!idxs || idxs.length === 0) continue;
      let bestTrial = null, bestR = null, bestM = Infinity;
      for (let f of [0.9, 0.8, 0.7]) {
        if (calls >= 398) break;
        const trial = scaleGroup(cur, idxs, f);
        const r = evalD(trial);
        if (r && safe(r, true)) {
          const m = Number(r.mass);
          if (isFinite(m) && m < bestM) {
            bestM = m; bestTrial = trial; bestR = r;
          }
        }
      }
      if (bestTrial && bestM < Number(rr.mass) - 1e-6) {
        cur = bestTrial;
        rr = bestR;
        consider(cur, rr);
      }
    }
  }

  let finalDesign = bestStrict ? cloneDesign(bestStrict) : cloneDesign(baseline);
  finalDesign.note = "Attempt 6: group-scaled and individually optimized S690/AL7075 Warren spine with conservative strict margins.";
  return finalDesign;
}

