        if (!tr || tr.ok !== true) continue;
        if (passes(tr, targetMode)) {
          cur.members[worst][2] = c.spec;
          rr = tr;
          improved = true;
          break;
        }
        const newU = Number(tr.maxUtil);
        const oldU = Number(rr.maxUtil);
        if (isFinite(newU) && isFinite(oldU) && newU < oldU - 1e-4) {
          cur.members[worst][2] = c.spec;
          rr = tr;
          improved = true;
          break;
        }
      }
