  }

  // Group scaling (non-cables only).
  const groups = buildGroups(cur);
  const groupList = [groups.bottom, groups.webL, groups.webR, groups.topL, groups.topR, groups.cross, groups.web, groups.all];
  for (let pass = 0; pass < 2 && calls < LIMIT - 40; pass++) {
    let changed = false;
    for (const idxs of groupList) {
      if (!idxs || !idxs.length || calls >= LIMIT - 40) continue;
      let bestTrial = null, bestR = null, bestM = Infinity;
      for (const f of [0.82, 0.68, 0.54]) {
        if (calls >= LIMIT - 40) break;
        const trial = scaleGroup(cur, idxs, f);
        const r = evalD(trial);
        if (r && r.ok === true && passes(r, optMode)) {
          const m = Number(r.mass);
          if (isFinite(m) && m < bestM) {
            bestM = m;
            bestTrial = trial;
            bestR = r;
          }
        }
      }
      if (bestTrial && bestM < Number(curR.mass) - 1e-6) {
        cur = bestTrial;
        curR = bestR;
        consider(cur, curR);
        changed = true;
      }
    }
    if (!changed) break;
  }

  function optimizeOne(idx) {
    if (idx < 0 || idx >= cur.members.length) return false;
    const oldSpec = cur.members[idx][2];
    const oldMass = massM(oldSpec);
    if (oldMass <= 0) return false;
    const info = (curR && curR.members && curR.members[idx]) || {};
    let lists = [];
    if (oldSpec.startsWith("WIRE")) {
      lists = [wirelist];
    } else {
      lists = [s690chs, alchs, s690rod, alrod];
      const modeStr = String(info.mode || "");
      if (modeStr.indexOf("buckl") >= 0 || (Number(info.compression) || 0) > 0) {
        lists.push(s690shs, alshs);
      }
    }
    let best = null;
    for (const list of lists) {
      if (calls >= LIMIT - 10) break;
      const res = findInList(cur, curR, idx, list, optMode, oldMass);
      if (res && (!best || res.mass < best.mass)) best = res;
    }
    if (best) {
      cur.members[idx][2] = best.spec;
      curR = best.r;
      consider(cur, curR);
      return true;
    }
    return false;
  }

  // Individual optimization passes.
  for (let pass = 0; pass < 3 && calls < LIMIT - 20; pass++) {
    let arr = [];
    for (let i = 0; i < cur.members.length; i++) {
      const m = cur.members[i];
      const mass = memberMass(m);
      const info = (curR && curR.members && curR.members[i]) || {};
      let util = Number(info.util);
      if (!isFinite(util)) util = 0.5;
      let score = mass * (1.25 - Math.min(util, 0.85));
      if (m[2].startsWith("WIRE")) score *= 1.6;
      arr.push({i, score});
    }
    arr.sort((a,b)=>b.score-a.score);
    const n = Math.min(pass === 0 ? 30 : 18, arr.length);
    let changed = false;
    for (let k = 0; k < n && calls < LIMIT - 10; k++) {
      if (optimizeOne(arr[k].i)) changed = true;
    }
    if (!changed) break;
  }

  // Removal of low-utilization redundant members.
  for (let iter = 0; iter < 10 && calls < LIMIT - 10; iter++) {
    if (!curR || !curR.members) break;
    let cand = [];
    for (let i = 0; i < cur.members.length; i++) {
      const info = curR.members[i];
      if (!info) continue;
      const util = Number(info.util);
      if (!isFinite(util) || util > 0.32) continue;
      const mass = memberMass(cur.members[i]);
      if (mass < 4) continue;
      let score = mass * (0.5 - Math.min(util, 0.32));
      if (String(info.mode || "").indexOf("fat") >= 0) score *= 0.3;
      cand.push({i, score});
    }
    if (!cand.length) break;
    cand.sort((a,b)=>b.score-a.score);
    let removed = false;
    for (const c of cand) {
      if (calls >= LIMIT - 10) break;
      const trial = clone(cur);
      trial.members.splice(c.i, 1);
      const r = evalD(trial);
      if (r && r.ok === true && passes(r, optMode)) {
        cur = trial;
        curR = r;
        consider(cur, curR);
        removed = true;
        break;
      }
    }
    if (!removed) break;
  }

  // Final individual pass after removals.
  if (calls < LIMIT - 10) {
    let arr = [];
    for (let i = 0; i < cur.members.length; i++) {
      const m = cur.members[i];
      const mass = memberMass(m);
      const info = (curR && curR.members && curR.members[i]) || {};
      let util = Number(info.util);
      if (!isFinite(util)) util = 0.5;
      arr.push({i, score: mass * (1.2 - Math.min(util, 0.8))});
    }
    arr.sort((a,b)=>b.score-a.score);
    for (let k = 0; k < Math.min(18, arr.length) && calls < LIMIT - 5; k++) {
      optimizeOne(arr[k].i);
    }
  }

  // Prefer a strict design unless a relaxed design is substantially lighter.
  let finalD = null;
  if (bestStrictD && bestStrictR) {
