    }
  } else if (bestRelaxD) {
    finalD = clone(bestRelaxD);
  } else if (curR && curR.ok === true) {
    finalD = clone(cur);
  } else {
    finalD = clone(base);
  }
  finalD.note = "Attempt 7: attempt-6 S690/AL7075 spine with full X wire top-plan bracing and selectively removed redundant top/web members.";
  return finalD;
}

