    ["SHS120x6",27.36],["SHS140x6",32.16],["SHS150x8",45.44],["SHS180x8",55.04],
    ["SHS200x10",76],["SHS250x10",96],["SHS300x12.5",143.75],["SHS350x16",213.76]
  ];
  const ROD = [
    ["ROD12",1.13],["ROD16",2.01],["ROD20",3.14],["ROD25",4.91],
    ["ROD32",8.04],["ROD40",12.57],["ROD50",19.63],["ROD64",32.17]
  ];

  const ALL = [];
  for (const [sec,a] of CHS) {
    ALL.push({mat:"S690", sec:sec, spec:"S690 "+sec, area:a, mass:a*7850/10000});
    ALL.push({mat:"AL7075", sec:sec, spec:"AL7075 "+sec, area:a, mass:a*2810/10000});
  }
  for (const [sec,a] of SHS) {
    ALL.push({mat:"S690", sec:sec, spec:"S690 "+sec, area:a, mass:a*7850/10000});
    ALL.push({mat:"AL7075", sec:sec, spec:"AL7075 "+sec, area:a, mass:a*2810/10000});
  }
  for (const [sec,a] of ROD) {
    ALL.push({mat:"S690", sec:sec, spec:"S690 "+sec, area:a, mass:a*7850/10000});
    ALL.push({mat:"AL7075", sec:sec, spec:"AL7075 "+sec, area:a, mass:a*2810/10000});
  }
  ALL.sort((a,b)=>a.mass-b.mass);

  const massMap = new Map();
  for (const c of ALL) massMap.set(c.spec, c.mass);
  function massPerM(spec) {
    const v = massMap.get(spec);
    return v === undefined ? 1e9 : v;
  }

  function cloneDesign(d) {
    return {
      note: d.note || "",
      nodes: d.nodes.map(n => ({id:n.id, x:n.x, y:n.y, z:n.z, joint:n.joint || "pin"})),
      members: d.members.map(m => [m[0], m[1], m[2]])
    };
  }

  const baseline = {
    note: "attempt-7 baseline",
    nodes: nodes.map(n => ({id:n.id, x:n.x, y:n.y, z:n.z, joint:n.joint})),
    members: baseMembers.map(m => [m[0], m[1], m[2]])
  };

  const MAX = 398;
  let calls = 0;
  const cache = new Map();

  function evalD(d) {
    const key = d.members.map(m => m[0]+"|"+m[1]+"|"+m[2]).join(";");
    if (cache.has(key)) return cache.get(key);
    if (calls >= MAX) return null;
    let r;
    try { r = analyse(d); } catch (e) { r = {error:String(e)}; }
    calls++;
    cache.set(key, r);
    return r;
  }

  const tStrict = {mu:0.72, fat:0.75, ac:8.0, freq:1.25, sagFrac:0.90, swayFrac:0.90};
  const tMedium = {mu:0.76, fat:0.79, ac:6.5, freq:1.22, sagFrac:0.93, swayFrac:0.93};
  const tRelaxed = {mu:0.80, fat:0.83, ac:5.5, freq:1.20, sagFrac:0.96, swayFrac:0.96};

  function good(r, t) {
    if (!r || r.error || r.ok !== true) return false;
    const mu = Number(r.maxUtil);
    if (!isFinite(mu) || mu > t.mu) return false;
    const fat = Number(r.fatigueWorst);
    if (isFinite(fat) && fat > t.fat) return false;
    const ac = Number(r.alphaCr);
    if (isFinite(ac) && ac > 0 && ac < t.ac) return false;
    const fr = Number(r.frequency);
    if (isFinite(fr) && fr > 0 && fr < t.freq) return false;
    if (r.sagLimit && r.sag && Number(r.sag) > t.sagFrac * Number(r.sagLimit)) return false;
    if (r.swayLimit && r.sway && Number(r.sway) > t.swayFrac * Number(r.swayLimit)) return false;
    const rob = r.robustness;
    if (rob === false) return false;
    if (rob && typeof rob === "object" && rob.ok === false) return false;
    return true;
  }

  function badness(r, t) {
    if (!r || r.error || r.ok !== true) return 1e9;
    let b = 0;
    b = Math.max(b, (Number(r.maxUtil) || 0) / t.mu);
    if (isFinite(Number(r.fatigueWorst))) b = Math.max(b, Number(r.fatigueWorst) / t.fat);
    const ac = Number(r.alphaCr);
    if (isFinite(ac) && ac > 0) b = Math.max(b, t.ac / ac);
    const fr = Number(r.frequency);
    if (isFinite(fr) && fr > 0) b = Math.max(b, t.freq / fr);
    if (r.sagLimit && r.sag) b = Math.max(b, Number(r.sag) / (t.sagFrac * Number(r.sagLimit)));
    if (r.swayLimit && r.sway) b = Math.max(b, Number(r.sway) / (t.swayFrac * Number(r.swayLimit)));
    const rob = r.robustness;
    if (rob === false) return 1e9;
    if (rob && typeof rob === "object" && rob.ok === false) return 1e9;
    return b;
  }

  let bestStrictD = null, bestStrictR = null, bestStrictMass = Infinity;
  let bestMediumD = null, bestMediumR = null, bestMediumMass = Infinity;
  let bestRelaxedD = null, bestRelaxedR = null, bestRelaxedMass = Infinity;

  function consider(d, r) {
    if (!r || r.error || r.ok !== true) return;
    const m = Number(r.mass);
    if (!isFinite(m)) return;
    if (good(r, tStrict) && m < bestStrictMass) {
      bestStrictMass = m;
      bestStrictD = cloneDesign(d);
      bestStrictR = r;
    }
    if (good(r, tMedium) && m < bestMediumMass) {
      bestMediumMass = m;
      bestMediumD = cloneDesign(d);
      bestMediumR = r;
    }
    if (good(r, tRelaxed) && m < bestRelaxedMass) {
      bestRelaxedMass = m;
      bestRelaxedD = cloneDesign(d);
      bestRelaxedR = r;
    }
  }

  const baseR = evalD(baseline);
  consider(baseline, baseR);

  function repair(start, startR, tier) {
    let d = cloneDesign(start);
    let r = startR;
    const changed = new Set();

    for (let iter = 0; iter < 40; iter++) {
      if (good(r, tier)) break;
      if (calls >= MAX - 12) break;

      const mu = Number(r && r.maxUtil) || 0;
      const fat = Number(r && r.fatigueWorst) || 0;
      const ratioMu = mu / tier.mu;
      const ratioFat = fat / tier.fat;
      const wantFatigue = ratioFat >= ratioMu;

      let idx = -1;
      let worst = -1;

      if (r && r.members && r.members.length === d.members.length) {
        for (let i = 0; i < d.members.length; i++) {
          const mi = r.members[i];
          if (!mi) continue;
          const u = Number(mi.util);
          if (!isFinite(u)) continue;
          const mode = String(mi.mode || "").toLowerCase();
          const isFat = mode.indexOf("fat") >= 0;
          if (wantFatigue && !isFat) continue;
          if (!wantFatigue && isFat) continue;
          if (u > worst) {
            worst = u;
            idx = i;
          }
        }
        if (idx < 0) {
          worst = -1;
          for (let i = 0; i < d.members.length; i++) {
            const mi = r.members[i];
            if (!mi) continue;
            const u = Number(mi.util);
            if (isFinite(u) && u > worst) {
              worst = u;
              idx = i;
            }
          }
        }
      }

      if (idx < 0) {
        let worstMass = -1;
        for (let i = 0; i < d.members.length; i++) {
          const m = massPerM(d.members[i][2]);
          if (m > worstMass) {
            worstMass = m;
            idx = i;
          }
        }
      }
      if (idx < 0 || idx >= d.members.length) break;

      const oldSpec = d.members[idx][2];
      const oldMass = massPerM(oldSpec);
      const cands = ALL
        .filter(c => c.mass > oldMass * 1.02)
        .sort((a, b) => a.mass - b.mass);
      if (!cands.length) break;

      const curBad = badness(r, tier);
      let bestD = null;
      let bestR = null;
      let bestBad = Infinity;
      let bestMass = Infinity;
      let foundGood = false;

      for (let ci = 0; ci < cands.length && ci < 14; ci++) {
        if (calls >= MAX - 6) break;
        const c = cands[ci];
        const trial = cloneDesign(d);
        trial.members[idx][2] = c.spec;
        const tr = evalD(trial);
        if (!tr || tr.error || tr.ok !== true) continue;
        consider(trial, tr);
        const bad = badness(tr, tier);
        if (good(tr, tier)) {
          bestD = trial;
          bestR = tr;
          bestBad = bad;
          bestMass = c.mass;
          foundGood = true;
          break;
        }
        if (bad < bestBad - 1e-9 || (Math.abs(bad - bestBad) < 1e-9 && c.mass < bestMass)) {
          bestBad = bad;
          bestD = trial;
          bestR = tr;
          bestMass = c.mass;
        }
      }

      if (!bestD) break;
      if (!foundGood && bestBad > curBad + 1e-6) break;

      d = bestD;
      r = bestR;
      changed.add(idx);
      consider(d, r);
    }

    return {d, r, changed};
  }

  let rep = repair(baseline, baseR, tStrict);
  let cur = rep.d;
  let curR = rep.r;

  if (!good(curR, tStrict) && calls < MAX - 40) {
    const rep2 = repair(cur, curR, tMedium);
    if (rep2.r && rep2.r.ok === true) {
      cur = rep2.d;
      curR = rep2.r;
      consider(cur, curR);
    }
  }

  if (good(curR, tStrict)) {
    const changedArr = Array.from(rep.changed)
      .sort((a, b) => massPerM(cur.members[b][2]) - massPerM(cur.members[a][2]));

    for (const idx of changedArr) {
      if (calls >= MAX - 30) break;
      const oldSpec = cur.members[idx][2];
      const oldMass = massPerM(oldSpec);
      const cands = ALL
        .filter(c => c.mass < oldMass - 1e-6)
        .sort((a, b) => a.mass - b.mass);
      if (!cands.length) continue;

      let lo = 0, hi = cands.length - 1;
      let bestD = null, bestR = null;

      while (lo <= hi && calls < MAX - 12) {
        const mid = (lo + hi) >> 1;
        const trial = cloneDesign(cur);
        trial.members[idx][2] = cands[mid].spec;
        const tr = evalD(trial);
        if (good(tr, tStrict)) {
          bestD = trial;
          bestR = tr;
          hi = mid - 1;
        } else {
          lo = mid + 1;
        }
      }

      if (bestD) {
        cur = bestD;
        curR = bestR;
        consider(cur, curR);
      }
    }
  }

  if (good(curR, tStrict)) {
    for (let pass = 0; pass < 3; pass++) {
      if (calls >= MAX - 20) break;
      const order = Array.from({length: cur.members.length}, (_, i) => i)
        .sort((i, j) => massPerM(cur.members[j][2]) - massPerM(cur.members[i][2]));
      let any = false;

      for (const idx of order) {
        if (calls >= MAX - 10) break;
        const oldSpec = cur.members[idx][2];
        const oldMass = massPerM(oldSpec);
        const lower = ALL
          .filter(c => c.mass < oldMass - 1e-6)
          .sort((a, b) => b.mass - a.mass);
        if (!lower.length) continue;

        const c = lower[0];
        const trial = cloneDesign(cur);
        trial.members[idx][2] = c.spec;
        const tr = evalD(trial);
        if (good(tr, tStrict)) {
          cur = trial;
          curR = tr;
          any = true;
          consider(cur, curR);
        }
      }

      if (!any) break;
    }
  }

  let finalD = null;
  let finalR = null;

  if (bestStrictD && bestStrictR) {
    finalD = bestStrictD;
    finalR = bestStrictR;
  } else if (bestMediumD && bestMediumR) {
    finalD = bestMediumD;
    finalR = bestMediumR;
  } else if (bestRelaxedD && bestRelaxedR) {
    finalD = bestRelaxedD;
    finalR = bestRelaxedR;
  } else if (curR && curR.ok === true) {
    finalD = cloneDesign(cur);
    finalR = curR;
  } else {
    finalD = cloneDesign(baseline);
    finalR = baseR;
  }

  if (good(curR, tStrict)) {
    const m = Number(curR.mass);
    const bestM = finalR ? Number(finalR.mass) : Infinity;
    if (!finalD || (isFinite(m) && m < bestM)) {
      finalD = cloneDesign(cur);
      finalR = curR;
    }
  }

  finalD.note = "Attempt 8 final: attempt-7 spine repaired and resized with strict deterministic margins for material, thickness and imperfection variability.";
  return {
    note: finalD.note,
    nodes: finalD.nodes,
    joints: {},
    members: finalD.members
  };
}

function design(site, analyse) {
  // Twin Warren girders below the deck (top chords = deck edge nodes at y=0),
  // bottom chords at y=-H, top and bottom lateral bracing (box action).
  // Every member is sized individually by iterating analyse(): utilisation
  // above 0.85 gets the next larger tube, below 0.60 the next smaller one.
  const X = [0, 4.918, 9.836, 14.755, 19.673, 24.591, 29.509, 34.427, 39.345, 44.264, 49.182, 54.1];
  const ZL = -4.35, ZR = 4.35, H = 7.4;
  const MAT = "S460 ";
  const SEC = ["CHS33.7x2.6","CHS42.4x3.2","CHS48.3x3.2","CHS60.3x3.2","CHS60.3x4","CHS76.1x3.2",
    "CHS76.1x4","CHS88.9x4","CHS88.9x5","CHS114.3x4","CHS114.3x5","CHS139.7x5","CHS168.3x5",
    "CHS139.7x6.3","CHS168.3x6.3","CHS193.7x6.3","CHS193.7x8","CHS219.1x8","CHS244.5x8",
    "CHS273x10","CHS323.9x10","CHS355.6x12.5","CHS406.4x12.5","CHS457x16"];
  const LAT = ["ST", "TL", "BS", "BB"];
  const CH = ["TC", "BC", "D"];

  // Bottom nodes at mid-panel positions, both edge lines
  const nodes = [];
  for (let i = 0; i <= 10; i++) {
    const xm = (X[i] + X[i + 1]) / 2;
    nodes.push({ id: "BL" + i, x: xm, y: -H, z: ZL, joint: "pin" });
    nodes.push({ id: "BR" + i, x: xm, y: -H, z: ZR, joint: "pin" });
  }

  const mem = [];
  const add = (a, b, g, idx) => mem.push({ a: a, b: b, g: g, idx: idx });

  // Warren diagonals (both trusses)
  for (let i = 0; i <= 10; i++) {
    add("L" + i, "BL" + i, "D", 14);
    add("BL" + i, "L" + (i + 1), "D", 14);
    add("R" + i, "BR" + i, "D", 14);
    add("BR" + i, "R" + (i + 1), "D", 14);
  }
  // Top chords (deck edge lines, compression)
  for (let i = 0; i <= 10; i++) {
    add("L" + i, "L" + (i + 1), "TC", 19);
    add("R" + i, "R" + (i + 1), "TC", 19);
  }
  // Bottom chords (tension)
  for (let i = 0; i <= 9; i++) {
    add("BL" + i, "BL" + (i + 1), "BC", 16);
    add("BR" + i, "BR" + (i + 1), "BC", 16);
  }
  // Top plane: struts at each deck node and one diagonal per panel
  for (let i = 0; i <= 11; i++) add("L" + i, "R" + i, "ST", 7);
  for (let i = 0; i <= 10; i++) add("L" + i, "R" + (i + 1), "TL", 7);
  // Bottom plane: struts and one diagonal per panel
  for (let i = 0; i <= 10; i++) add("BL" + i, "BR" + i, "BS", 7);
  for (let i = 0; i <= 9; i++) add("BL" + i, "BR" + (i + 1), "BB", 7);

  const specOf = (m) => MAT + SEC[m.idx];
  const build = () => {
    const ns = nodes.map((n) => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: n.joint }));
    const ms = mem.map((m) => ({ a: m.a, b: m.b, spec: specOf(m) }));
    return {
      note: "Twin Warren girders (depth 7.4 m) at z=±4.35 with top and bottom lateral bracing; S460 tubes sized per member by utilisation.",
      nodes: ns,
      joints: {},
      members: ms
    };
  };

  let best = null;
  let last = null;
  const prevStep = new Array(mem.length).fill(0);

  for (let it = 0; it < 60; it++) {
    const d = build();
    const r = analyse(d);
    if (!r || r.error) break;
    last = d;
    if (r.ok && (best === null || r.mass < best.mass)) best = { mass: r.mass, d: d };

    const mr = Array.isArray(r.members) ? r.members : [];
    const lat = (typeof r.alphaCr === "number" && r.alphaCr < 5) ||
                (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > r.swayLimit);
    const chordUp = (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > r.sagLimit) ||
                    (typeof r.fMin === "number" && r.fMin < 1.2);

    let changed = 0;
    for (let k = 0; k < mem.length; k++) {
      const m = mem[k];
      const u = (mr[k] && typeof mr[k].util === "number") ? mr[k].util : null;
      let step = 0;
      if (u !== null) {
        if (u > 0.85) step = 1;
        else if (u < 0.6 && prevStep[k] !== 1) step = -1;
      }
      if (lat && LAT.indexOf(m.g) >= 0) step = Math.max(step, 1);
      if (chordUp && CH.indexOf(m.g) >= 0) step = Math.max(step, 1);
      let ni = m.idx + step;
      if (ni < 0) ni = 0;
      if (ni > SEC.length - 1) ni = SEC.length - 1;
      if (ni !== m.idx) {
        m.idx = ni;
        changed++;
      }
      prevStep[k] = step;
    }
    if (changed === 0) break;
  }

  if (best) return best.d;
  return last || build();
}

function design(site, analyse) {
  // Twin Warren girders at z = ±4.35 (top chords = deck edge nodes, bottom chords at y = -7.4),
  // top and bottom lateral bracing. Cross members are added until the frame has no internal
  // mechanism (rigidity rank check). Members are sized by utilisation, a fatigue proxy and the
  // global checks reported by analyse().
  const X = [0, 4.918, 9.836, 14.755, 19.673, 24.591, 29.509, 34.427, 39.345, 44.264, 49.182, 54.1];
  const ZL = -4.35, ZR = 4.35, H = 7.4;
  const MAT = "S690 ";
  const SEC = ["CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2", "CHS60.3x3.2", "CHS60.3x4", "CHS76.1x3.2",
    "CHS76.1x4", "CHS88.9x4", "CHS88.9x5", "CHS114.3x4", "CHS114.3x5", "CHS139.7x5", "CHS168.3x5",
    "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x6.3", "CHS193.7x8", "CHS219.1x8", "CHS244.5x8",
    "CHS273x10", "CHS323.9x10", "CHS355.6x12.5", "CHS406.4x12.5", "CHS457x16"];
  const AREA = [2.54, 3.94, 4.53, 5.74, 7.07, 7.33, 9.06, 10.67, 13.18, 13.86, 17.17, 21.16, 25.65,
    26.4, 32.06, 37.09, 46.67, 53.06, 59.44, 82.62, 98.61, 134.74, 154.68, 221.67];
  const NS = SEC.length;

  // ---- node positions ----
  const pos = {};
  const nodes = [];
  for (let i = 0; i < 12; i++) { pos["L" + i] = [X[i], 0, ZL]; pos["R" + i] = [X[i], 0, ZR]; }
  for (let i = 0; i <= 10; i++) {
    const xm = (X[i] + X[i + 1]) / 2;
    pos["BL" + i] = [xm, -H, ZL];
    pos["BR" + i] = [xm, -H, ZR];
    nodes.push({ id: "BL" + i, x: xm, y: -H, z: ZL, joint: "pin" });
    nodes.push({ id: "BR" + i, x: xm, y: -H, z: ZR, joint: "pin" });
  }
  const names = Object.keys(pos);
  const nidx = {};
  names.forEach((n, i) => { nidx[n] = i; });
  const NC = 3 * names.length;

  // ---- base topology ----
  let mem = [];
  const add = (a, b, g, idx) => { mem.push({ a: a, b: b, g: g, idx: idx }); };
  for (let i = 0; i <= 10; i++) {
    add("L" + i, "BL" + i, "D", 14);
    add("BL" + i, "L" + (i + 1), "D", 14);
    add("R" + i, "BR" + i, "D", 14);
    add("BR" + i, "R" + (i + 1), "D", 14);
    add("L" + i, "L" + (i + 1), "TC", 18);
    add("R" + i, "R" + (i + 1), "TC", 18);
  }
  for (let i = 0; i <= 9; i++) {
    add("BL" + i, "BL" + (i + 1), "BC", 17);
    add("BR" + i, "BR" + (i + 1), "BC", 17);
  }
  for (let i = 0; i <= 11; i++) add("L" + i, "R" + i, "ST", 8);
  for (let i = 0; i <= 10; i++) add("L" + i, "R" + (i + 1), "TL", 8);
  for (let i = 0; i <= 10; i++) add("BL" + i, "BR" + i, "BS", 8);
  for (let i = 0; i <= 9; i++) add("BL" + i, "BR" + (i + 1), "BB", 8);

  const key = (a, b) => (a < b ? a + "|" + b : b + "|" + a);
  const conn = new Set();
  mem.forEach(m => conn.add(key(m.a, m.b)));

  // ---- rigidity (rank of member directions + bearing restraints) ----
  const buildRows = (list) => {
    const rows = [];
    for (const m of list) {
      const pa = pos[m.a], pb = pos[m.b];
      const d = [pb[0] - pa[0], pb[1] - pa[1], pb[2] - pa[2]];
      const L = Math.sqrt(d[0] * d[0] + d[1] * d[1] + d[2] * d[2]);
      const r = new Array(NC).fill(0);
      for (let k = 0; k < 3; k++) {
        r[3 * nidx[m.a] + k] = -d[k] / L;
        r[3 * nidx[m.b] + k] = d[k] / L;
      }
      rows.push(r);
    }
    const bear = [["L0", [0, 1, 2]], ["R0", [0, 1]], ["L11", [0, 1, 2]], ["R11", [0, 1]]];
    for (const bb of bear) {
      for (const k of bb[1]) {
        const r = new Array(NC).fill(0);
        r[3 * nidx[bb[0]] + k] = 1;
        rows.push(r);
      }
    }
    return rows;
  };

  const rankOf = (rows) => {
    const A = rows.map(r => r.slice());
    const nR = A.length;
    let rank = 0;
    for (let c = 0; c < NC && rank < nR; c++) {
      let piv = -1, best = 1e-9;
      for (let r = rank; r < nR; r++) {
        const v = Math.abs(A[r][c]);
        if (v > best) { best = v; piv = r; }
      }
      if (piv < 0) continue;
      const tmp = A[rank]; A[rank] = A[piv]; A[piv] = tmp;
      const p = A[rank];
      for (let r = rank + 1; r < nR; r++) {
        const f = A[r][c] / p[c];
        if (f !== 0) {
          const row = A[r];
          for (let k = c; k < NC; k++) row[k] -= f * p[k];
        }
      }
      rank++;
    }
    return rank;
  };

  // ---- joint geometry: >= 12 deg between members, <= 12 members per joint ----
  const cos12 = Math.cos(12 * Math.PI / 180);
  const jointOK = (n, other, list) => {
    const pn = pos[n], po = pos[other];
    const u = [po[0] - pn[0], po[1] - pn[1], po[2] - pn[2]];
    const lu = Math.sqrt(u[0] * u[0] + u[1] * u[1] + u[2] * u[2]);
    let count = 0;
    for (const m of list) {
      let o = null;
      if (m.a === n) o = m.b; else if (m.b === n) o = m.a;
      if (o === null) continue;
      count++;
      const pq = pos[o];
      const v = [pq[0] - pn[0], pq[1] - pn[1], pq[2] - pn[2]];
      const lv = Math.sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]);
      const c = (u[0] * v[0] + u[1] * v[1] + u[2] * v[2]) / (lu * lv);
      if (c > cos12) return false;
    }
    return count < 12;
  };

  // ---- candidate cross members: bottom node to deck node, short ones first ----
  const bottoms = names.filter(n => n[0] === "B");
  const decks = names.filter(n => n[0] !== "B");
  const cands = [];
  for (const b of bottoms) {
    for (const d of decks) {
      if (conn.has(key(b, d))) continue;
      const pb = pos[b], pd = pos[d];
      const L = Math.hypot(pb[0] - pd[0], pb[1] - pd[1], pb[2] - pd[2]);
      if (L <= 12) cands.push({ a: b, b: d, len: L });
    }
  }
  cands.sort((p, q) => p.len - q.len);

  // add members until the frame carries no internal mechanism
  let cur = rankOf(buildRows(mem));
  let guard = 0;
  while (cur < NC && guard < 12) {
    let done = false;
    for (const c of cands) {
      if (conn.has(key(c.a, c.b))) continue;
      if (!jointOK(c.a, c.b, mem) || !jointOK(c.b, c.a, mem)) continue;
      const trial = mem.concat([{ a: c.a, b: c.b, g: "X", idx: 8 }]);
      const rr = rankOf(buildRows(trial));
      if (rr > cur) {
        mem = trial;
        conn.add(key(c.a, c.b));
        cur = rr;
        done = true;
        break;
      }
    }
    if (!done) break;
    guard++;
  }

  // ---- sizing loop ----
  const build = () => ({
    note: "Twin Warren girders with top/bottom lateral bracing and cross members added to remove the mechanism; S690 CHS sized per member by utilisation, fatigue proxy and global checks.",
    nodes: nodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: n.joint })),
    joints: {},
    members: mem.map(m => ({ a: m.a, b: m.b, spec: MAT + SEC[m.idx] }))
  });

  let best = null, last = null;
  for (let it = 0; it < 60; it++) {
    const d = build();
    const r = analyse(d);
    if (!r || r.error) break;
    last = d;
    if (r.ok && (best === null || r.mass < best.mass)) best = { mass: r.mass, d: d };

    const mr = Array.isArray(r.members) ? r.members : [];
