  };

  const toDesign = (T, note) => ({
    note: note,
    nodes: T.nodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: "pin" })),
    joints: {},
    members: T.mem.map(m => ({ a: m.a, b: m.b, spec: MAT + SEC[m.idx] }))
  });

  const run = (kind, iters, deadline) => {
    const T = buildTopo(kind);
    const mem = T.mem;
    const G = {};
    GROUPS.forEach(g => { G[g] = 1; });
    let bestP = null, bestAny = null, last = null;
    for (let it = 0; it < iters; it++) {
      if (elapsed() > deadline) break;
      const d = toDesign(T, "AL7075 CHS " + kind + " girders sized per member to a utilisation target, with global group multipliers for sag, sway, frequency and alphaCr.");
      const r = analyse(d);
      if (!r || r.error) break;
      last = d;

      const mass = typeof r.mass === "number" ? r.mass : Infinity;
      const mU = typeof r.maxUtil === "number" ? r.maxUtil : 1;
      const sr = (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sagLimit > 0) ? r.sag / r.sagLimit : 0;
      const wr = (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.swayLimit > 0) ? r.sway / r.swayLimit : 0;
      const fM = typeof r.fMin === "number" ? r.fMin : (typeof r.frequency === "number" ? r.frequency : null);
      const al = typeof r.alphaCr === "number" ? r.alphaCr : null;
      const good = !!r.ok && mU <= UMAX && sr <= SAGF && wr <= SWF &&
        (al === null || al >= ALMIN) && (fM === null || fM >= FMIN);
      if (good && (bestP === null || mass < bestP.mass)) bestP = { mass: mass, d: d };
      if (r.ok && mU <= 1 && (bestAny === null || mass < bestAny.mass)) bestAny = { mass: mass, d: d };

