      } else if (sr < 0.6) {
        ["TC", "BC"].forEach(g => { G[g] *= 0.97; });
      }
      if (fM !== null && fM < 1.3) { G.TC *= 1.05; G.BC *= 1.05; }
      if (al !== null) {
        if (al < 7) BRACE.forEach(g => { G[g] *= 1.1; });
        if (al < 5.5) { G.TC *= 1.05; G.BC *= 1.05; }
        if (al > 14 && wr < 0.6) BRACE.forEach(g => { G[g] *= 0.97; });
      }
      if (wr > 0.85) BRACE.forEach(g => { G[g] *= 1.1; });
      GROUPS.forEach(g => { G[g] = Math.min(30, Math.max(0.3, G[g])); });

      // per-member utilisation sizing
      const mr = Array.isArray(r.members) ? r.members : [];
      const byId = {};
      mr.forEach(e => { if (e && e.id) byId[e.id] = e; });
      let changed = 0;
      for (let k = 0; k < mem.length; k++) {
        const m = mem[k];
        const e = byId[m.a + "-" + m.b] || byId[m.b + "-" + m.a] || (mr.length === mem.length ? mr[k] : null);
        const u = (e && typeof e.util === "number") ? e.util : null;
        if (u === null) continue;
        const base = AREA[m.idx] * Math.max(u, 0.02) / UT;
        const want = Math.max(base, FLOOR[m.g]) * G[m.g];
        let j = 0;
        while (j < NS - 1 && AREA[j] < want) j++;
        let ni = Math.max(j, m.idx - 3);
        ni = Math.min(ni, m.idx + 4);
        ni = clampI(ni);
        if (ni !== m.idx) changed++;
        m.idx = ni;
      }
      if (changed === 0 && good) break;
    }
    return { bestP: bestP, bestAny: bestAny, last: last };
  };

  const RW = run("W", 90, 38);
  const RP = run("P", 90, 78);
  const picks = [];
  [RW, RP].forEach(R => {
    if (R.bestP) picks.push({ tier: 0, mass: R.bestP.mass, d: R.bestP.d });
    else if (R.bestAny) picks.push({ tier: 1, mass: R.bestAny.mass, d: R.bestAny.d });
  });
  picks.sort((p, q) => (p.tier - q.tier) || (p.mass - q.mass));
  if (picks.length) return picks[0].d;
  if (RW.last) return RW.last;
  if (RP.last) return RP.last;
  return toDesign(buildTopo("W"), "fallback Warren girders");
}

function design(site, analyse) {
  // Pratt twin girders of AL7075 CHS, pinned joints, top and bottom lateral bracing.
  // Each member is sized to a utilisation target below the nominal cap, so that the
  // built-unit draws (strength, thickness, imperfection) still leave margin.
  // Global group multipliers respond to sag, sway, frequency and alphaCr.
  const X = [0, 4.918, 9.836, 14.755, 19.673, 24.591, 29.509, 34.427, 39.345, 44.264, 49.182, 54.1];
  const ZL = -4.35, ZR = 4.35, H = 7.52;
  const MAT = "AL7075 ";
  const SEC = ["CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2", "CHS60.3x3.2", "CHS60.3x4", "CHS76.1x3.2",
    "CHS76.1x4", "CHS88.9x4", "CHS88.9x5", "CHS114.3x4", "CHS114.3x5", "CHS139.7x5", "CHS168.3x5",
    "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x6.3", "CHS193.7x8", "CHS219.1x8", "CHS244.5x8",
    "CHS273x10", "CHS323.9x10", "CHS355.6x12.5", "CHS406.4x12.5", "CHS457x16"];
