  const UT = 0.66, UMAX = 0.74, UMAX2 = 0.85, ALMIN = 10.2, FMIN = 1.35, SAGF = 0.85, SWF = 0.85;
  const INIT = { D: 16, V: 16, TC: 18, BC: 18, ST: 10, TL: 10, BS: 10, BB: 10, X: 10 };
  const FLOOR = { D: 0, V: 0, TC: 0, BC: 0, ST: 4, TL: 4, BS: 4, BB: 4, X: 4 };
