    const sr = (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sagLimit > 0) ? r.sag / r.sagLimit : 0;
    const wr = (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.swayLimit > 0) ? r.sway / r.swayLimit : 0;
    const fM = typeof r.fMin === "number" ? r.fMin : (typeof r.frequency === "number" ? r.frequency : null);
