        BRACE.forEach(g => { G[g] *= f; });
        G.TC *= f; G.BC *= f;
      } else if (al > 14 && wr < 0.6 && (fM === null || fM > 1.6)) {
        BRACE.forEach(g => { G[g] *= 0.97; });
      }
    }
    GROUPS.forEach(g => { G[g] = Math.min(30, Math.max(0.3, G[g])); });

    // per-member utilisation sizing
    const mr = Array.isArray(r.members) ? r.members : [];
    const byId = {};
    mr.forEach(e => { if (e && e.id) byId[e.id] = e; });
    let changed = 0;
    for (let k = 0; k < mem.length; k++) {
      const m = mem[k];
      const e = byId[m.a + "-" + m.b] || byId[m.b + "-" + m.a] || (mr.length === mem.length ? mr[k] : null);
      const u = (e && typeof e.util === "number") ? e.util : null;
      if (u === null) continue;
      const base = AREA[m.idx] * Math.max(u, 0.03) / UT;
      const want = base * G[m.g];
      let j = 0;
      while (j < NS - 1 && AREA[j] < want) j++;
      let ni = Math.max(j, m.idx - 4);
      ni = Math.min(ni, m.idx + 5);
      ni = Math.max(ni, FLOOR[m.g]);
      ni = clampI(ni);
      if (ni !== m.idx) changed++;
      m.idx = ni;
    }
    if (changed === 0 && feas !== null) break;
  }

  if (feas) return feas.d;
  if (feas2) return feas2.d;
  if (anyOK) return anyOK.d;
  return last || toDesign(T, "fallback Pratt girders");
}

function design(site, analyse) {
  // Pratt twin girders of AL7075 CHS with top and bottom lateral bracing, as in attempts 6 and 7.
  // Sizing starts from small sections and grows each member to a utilisation target, so the search
  // approaches the lightest section from below. A trim pass then shrinks the least-used members one
  // step at a time, keeping a change only if every check still holds and the mass falls.
  const X = [0, 4.918, 9.836, 14.755, 19.673, 24.591, 29.509, 34.427, 39.345, 44.264, 49.182, 54.1];
  const ZL = -4.35, ZR = 4.35, H = 7.5;
  const MAT = "AL7075 ";
  const SEC = ["CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2", "CHS60.3x3.2", "CHS60.3x4", "CHS76.1x3.2",
    "CHS76.1x4", "CHS88.9x4", "CHS88.9x5", "CHS114.3x4", "CHS114.3x5", "CHS139.7x5", "CHS168.3x5",
    "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x6.3", "CHS193.7x8", "CHS219.1x8", "CHS244.5x8",
    "CHS273x10", "CHS323.9x10", "CHS355.6x12.5", "CHS406.4x12.5", "CHS457x16"];
  const AREA = [2.54, 3.94, 4.53, 5.74, 7.07, 7.33, 9.06, 10.67, 13.18, 13.86, 17.17, 21.16, 25.65,
    26.4, 32.06, 37.09, 46.67, 53.06, 59.44, 82.62, 98.61, 134.74, 154.68, 221.67];
  const NS = SEC.length;
  const UT = 0.72, UMAX = 0.80, SAGF = 0.92, SWF = 0.90, ALMIN = 6.0, FMIN = 1.25;
  const INIT = { D: 12, V: 12, TC: 14, BC: 14, ST: 6, TL: 6, BS: 6, BB: 6, X: 6 };
  const FLOOR = { D: 0, V: 0, TC: 0, BC: 0, ST: 4, TL: 4, BS: 4, BB: 4, X: 4 };
  const BRACE = ["ST", "TL", "BS", "BB", "X"];
  const GROUPS = ["D", "V", "TC", "BC", "ST", "TL", "BS", "BB", "X"];
  const cos12 = Math.cos(12 * Math.PI / 180);
  const t0 = (typeof Date !== "undefined") ? Date.now() : 0;
  const elapsed = () => ((typeof Date !== "undefined") ? (Date.now() - t0) / 1000 : 0);
  const key = (a, b) => (a < b ? a + "|" + b : b + "|" + a);
  const clampI = (v) => Math.max(0, Math.min(NS - 1, v));
  const NOTE = "AL7075 CHS Pratt twin girders sized up from small sections to a 0.72 utilisation target, cap 0.80, then trimmed member by member while all checks hold.";

  const rankOf = (rows, NC) => {
    const A = rows.map(r => r.slice());
    const nR = A.length;
    let rank = 0;
    for (let c = 0; c < NC && rank < nR; c++) {
      let piv = -1, best = 1e-9;
      for (let r = rank; r < nR; r++) {
        const v = Math.abs(A[r][c]);
        if (v > best) { best = v; piv = r; }
      }
      if (piv < 0) continue;
      const tmp = A[rank]; A[rank] = A[piv]; A[piv] = tmp;
      const p = A[rank];
      for (let r = rank + 1; r < nR; r++) {
        const f = A[r][c] / p[c];
        if (f !== 0) {
          const row = A[r];
          for (let k = c; k < NC; k++) row[k] -= f * p[k];
        }
      }
      rank++;
    }
    return rank;
  };

  const buildTopo = () => {
    const pos = {}, nodes = [];
    for (let i = 0; i < 12; i++) { pos["L" + i] = [X[i], 0, ZL]; pos["R" + i] = [X[i], 0, ZR]; }
    for (let i = 0; i < 12; i++) {
      pos["BL" + i] = [X[i], -H, ZL];
      pos["BR" + i] = [X[i], -H, ZR];
      nodes.push({ id: "BL" + i, x: X[i], y: -H, z: ZL });
      nodes.push({ id: "BR" + i, x: X[i], y: -H, z: ZR });
    }
    let mem = [];
    const conn = new Set();
    const add = (a, b, g) => { mem.push({ a: a, b: b, g: g, idx: INIT[g] }); conn.add(key(a, b)); };
    for (let i = 0; i <= 10; i++) { add("L" + i, "L" + (i + 1), "TC"); add("R" + i, "R" + (i + 1), "TC"); }
    for (let i = 0; i <= 11; i++) add("L" + i, "R" + i, "ST");
    for (let i = 0; i <= 10; i++) add("L" + i, "R" + (i + 1), "TL");
    for (let i = 0; i <= 11; i++) { add("L" + i, "BL" + i, "V"); add("R" + i, "BR" + i, "V"); }
    for (let j = 0; j <= 10; j++) {
      if (j <= 4) { add("L" + j, "BL" + (j + 1), "D"); add("R" + j, "BR" + (j + 1), "D"); }
      else { add("L" + (j + 1), "BL" + j, "D"); add("R" + (j + 1), "BR" + j, "D"); }
    }
    for (let i = 0; i <= 10; i++) { add("BL" + i, "BL" + (i + 1), "BC"); add("BR" + i, "BR" + (i + 1), "BC"); }
    for (let i = 0; i <= 11; i++) add("BL" + i, "BR" + i, "BS");
    for (let i = 0; i <= 10; i++) add("BL" + i, "BR" + (i + 1), "BB");

    const names = Object.keys(pos);
    const nidx = {};
    names.forEach((n, i) => { nidx[n] = i; });
    const NC = 3 * names.length;
    const rowsOf = (list) => {
      const rows = [];
      for (const m of list) {
        const pa = pos[m.a], pb = pos[m.b];
        const d = [pb[0] - pa[0], pb[1] - pa[1], pb[2] - pa[2]];
        const L = Math.sqrt(d[0] * d[0] + d[1] * d[1] + d[2] * d[2]);
        const r = new Array(NC).fill(0);
        for (let k = 0; k < 3; k++) {
          r[3 * nidx[m.a] + k] = -d[k] / L;
          r[3 * nidx[m.b] + k] = d[k] / L;
        }
        rows.push(r);
      }
      const bear = [["L0", [0, 1, 2]], ["R0", [0, 1]], ["L11", [0, 1, 2]], ["R11", [0, 1]]];
      for (const bb of bear) {
        for (const k of bb[1]) {
          const r = new Array(NC).fill(0);
          r[3 * nidx[bb[0]] + k] = 1;
          rows.push(r);
        }
      }
      return rows;
    };
    const jointOK = (n, other, list) => {
      const pn = pos[n], po = pos[other];
      const u = [po[0] - pn[0], po[1] - pn[1], po[2] - pn[2]];
      const lu = Math.sqrt(u[0] * u[0] + u[1] * u[1] + u[2] * u[2]);
      let count = 0;
      for (const m of list) {
        let o = null;
        if (m.a === n) o = m.b; else if (m.b === n) o = m.a;
        if (o === null) continue;
        count++;
        const pq = pos[o];
        const v = [pq[0] - pn[0], pq[1] - pn[1], pq[2] - pn[2]];
        const lv = Math.sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]);
        const c = (u[0] * v[0] + u[1] * v[1] + u[2] * v[2]) / (lu * lv);
        if (c > cos12) return false;
      }
      return count < 12;
    };
    let cur = rankOf(rowsOf(mem), NC);
    const bottoms = names.filter(n => n[0] === "B");
    const decks = names.filter(n => n[0] !== "B");
    const cands = [];
    for (const b of bottoms) {
      for (const d of decks) {
        if (conn.has(key(b, d))) continue;
        const pb = pos[b], pd = pos[d];
        const L = Math.sqrt((pb[0] - pd[0]) ** 2 + (pb[1] - pd[1]) ** 2 + (pb[2] - pd[2]) ** 2);
        if (L <= 12) cands.push({ a: b, b: d, len: L });
      }
    }
    cands.sort((p, q) => p.len - q.len);
    let guard = 0;
    while (cur < NC && guard < 12) {
      let done = false;
      for (const c of cands) {
        if (conn.has(key(c.a, c.b))) continue;
        if (!jointOK(c.a, c.b, mem) || !jointOK(c.b, c.a, mem)) continue;
        const trial = mem.concat([{ a: c.a, b: c.b, g: "X", idx: INIT.X }]);
        const rr = rankOf(rowsOf(trial), NC);
        if (rr > cur) {
          mem = trial;
          conn.add(key(c.a, c.b));
          cur = rr;
          done = true;
          break;
        }
      }
      if (!done) break;
      guard++;
    }
    return { nodes: nodes, mem: mem, rank: cur, NC: NC };
  };

  const toDesign = (T, note) => ({
    note: note,
    nodes: T.nodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: "pin" })),
    joints: {},
    members: T.mem.map(m => ({ a: m.a, b: m.b, spec: MAT + SEC[m.idx] }))
  });

  const T = buildTopo();
  const mem = T.mem;
  const G = {};
  GROUPS.forEach(g => { G[g] = 1; });

  const read = (r) => {
    const mass = typeof r.mass === "number" ? r.mass : Infinity;
    const mU = typeof r.maxUtil === "number" ? r.maxUtil : 1;
    const sr = (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sagLimit > 0) ? r.sag / r.sagLimit : 0;
    const wr = (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.swayLimit > 0) ? r.sway / r.swayLimit : 0;
    const fM = typeof r.fMin === "number" ? r.fMin : (typeof r.frequency === "number" ? r.frequency : null);
    const al = typeof r.alphaCr === "number" ? r.alphaCr : null;
    const good = !!r.ok && mU <= UMAX && sr <= SAGF && wr <= SWF &&
      (al === null || al >= ALMIN) && (fM === null || fM >= FMIN);
    return { mass: mass, mU: mU, sr: sr, wr: wr, fM: fM, al: al, good: good };
  };

  const utilsOf = (r) => {
    const mr = Array.isArray(r.members) ? r.members : [];
    const byId = {};
    mr.forEach(e => { if (e && e.id) byId[e.id] = e; });
    return mem.map((m, k) => {
      const e = byId[m.a + "-" + m.b] || byId[m.b + "-" + m.a] || (mr.length === mem.length ? mr[k] : null);
      return (e && typeof e.util === "number") ? e.util : null;
    });
  };

  let bestP = null, last = null;

  // Phase 1: grow sections from small to the utilisation target, global multipliers as before.
  for (let it = 0; it < 240; it++) {
    if (elapsed() > 60) break;
    const d = toDesign(T, NOTE);
    let r;
    try { r = analyse(d); } catch (e) { break; }
    if (!r || r.error) break;
    last = d;

    const info = read(r);
    const util = utilsOf(r);
    if (info.good && (bestP === null || info.mass < bestP.mass)) {
      bestP = { mass: info.mass, idx: mem.map(m => m.idx), util: util };
    }

    const sr = info.sr, wr = info.wr, fM = info.fM, al = info.al;
    if (sr > 0.85) { const f = Math.min(1.15, sr / 0.8); ["TC", "BC", "D", "V"].forEach(g => { G[g] *= f; }); }
    else if (sr < 0.6) { ["TC", "BC"].forEach(g => { G[g] *= 0.97; }); }
    if (fM !== null && fM < 1.3) { G.TC *= 1.05; G.BC *= 1.05; }
    if (al !== null) {
      if (al < 6.5) BRACE.forEach(g => { G[g] *= 1.08; });
      if (al < 6.0) { G.TC *= 1.05; G.BC *= 1.05; }
      if (al > 14 && wr < 0.6) BRACE.forEach(g => { G[g] *= 0.97; });
    }
    if (wr > 0.85) BRACE.forEach(g => { G[g] *= 1.1; });
    GROUPS.forEach(g => { G[g] = Math.min(30, Math.max(0.3, G[g])); });

    let changed = 0;
    for (let k = 0; k < mem.length; k++) {
      const m = mem[k];
      const u = util[k];
      if (u === null) continue;
      const base = AREA[m.idx] * Math.max(u, 0.02) / UT;
      const want = Math.max(base, AREA[FLOOR[m.g]]) * G[m.g];
      let j = 0;
      while (j < NS - 1 && AREA[j] < want) j++;
      let ni = Math.max(j, m.idx - 3);
      ni = Math.min(ni, m.idx + 8);
      ni = Math.max(ni, FLOOR[m.g]);
      ni = clampI(ni);
      if (ni !== m.idx) changed++;
      m.idx = ni;
    }
    if (changed === 0 && info.good) break;
  }

  // Phase 2: trim the least-used members one step at a time from the best feasible design.
  if (bestP) {
    let thr = 0.5;
    for (let it = 0; it < 40 && thr >= 0.2; it++) {
      if (elapsed() > 84) break;
      mem.forEach((m, k) => { m.idx = bestP.idx[k]; });
      let changed = 0;
      mem.forEach((m, k) => {
        const u = bestP.util[k];
        if (u !== null && u < thr && m.idx > FLOOR[m.g]) { m.idx -= 1; changed++; }
      });
      if (changed === 0) { thr -= 0.05; continue; }
      const d = toDesign(T, NOTE);
      let r;
      try { r = analyse(d); } catch (e) { break; }
      if (!r || r.error) break;
      const info = read(r);
      if (info.good && info.mass < bestP.mass) {
        bestP = { mass: info.mass, idx: mem.map(m => m.idx), util: utilsOf(r) };
      } else {
        thr -= 0.05;
      }
    }
    mem.forEach((m, k) => { m.idx = bestP.idx[k]; });
    return toDesign(T, NOTE);
  }

  if (last) return last;
  return toDesign(T, "fallback Pratt girders");
}
